INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('245f430d-cdfd-4fbd-8503-9c3007759ba4', 'quantum__breakthrough__toshiba-cambridge-world-s-first-qkd-over-100-km-of-optical-fibre', 'quantum', 'breakthrough', NULL, 'Toshiba Cambridge — world''s first QKD over 100 km of optical fibre', 'Andrew Shields (head of quantum group); Toshiba Research Europe Cambridge Research Laboratory', '2003', '2003-01-01', 'year', 'First demonstration of quantum key distribution over 100 km of standard optical fibre — tripling the previous maximum range of ~30 km. The result established that QKD could work at metropolitan and inter-city scale, not just in short-range lab settings. Toshiba Cambridge had begun quantum cryptography research in 1999 and would go on to hold more QKD distance and speed records than any other organisation over the following two decades.', 'https://www.global.toshiba/ww/products-solutions/security-ict/qkd/why.html', true, 'First in a long series of world records from the Cambridge lab (2003: 100 km; 2010: >1 Mbit/s; 2017: >10 Mbit/s; 2018: TF-QKD protocol; 2021: 600 km). Andrew Shields was elected a Fellow of the Royal Society in part for this body of work. The Cambridge lab went on to deliver the first city-scale QKD network in the UK (2018–19).', 'active', '2026-07-01', 0) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('e32593d2-a62d-4191-8f8a-e23c96b2fcd6', 'quantum__breakthrough__bristol-centre-for-quantum-photonics-first-quantum-photonic-circuits-on-a-silico', 'quantum', 'breakthrough', NULL, 'Bristol Centre for Quantum Photonics — first quantum photonic circuits on a silicon chip', 'Alberto Politi (first author); Dr Martin Cryan; Prof John Rarity; Dr Siyuan Yu; Dr Jeremy O''Brien; University of Bristol Centre for Quantum Photonics', 'Mar 2008', '2008-03-01', 'month', 'First demonstration of key quantum photonic circuits — including a two-photon quantum interference (94.8% visibility), a CNOT gate (94.3% logical basis fidelity), and path-entangled two-photon states — all built into a silica-on-silicon chip. This reduced the physical footprint of quantum optical circuits from a square metre of optical table to millimetre-scale chips, solving a major scalability and stability problem for photonic quantum computing. The paper coined the term "integrated quantum photonics" as a field.', 'https://www.science.org/doi/10.1126/science.1155441', true, 'Published in Science 320, 646 (Mar 2008). Won the 2008 IET Emerging Technologies Award. Prof O''Brien received the IUPAP Young Investigator Award (2009), IOP Moseley Medal (2010), and Adolph Lomb Medal (2010) for this body of work. The paper became one of the most cited in quantum photonics and spawned the field now worth hundreds of millions of pounds of investment globally. PsiQuantum (founded 2017 by O''Brien, Rudolph, Thompson, Sparrow) traces directly to this work.', 'active', '2026-07-01', 1) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('3a5ea8cf-40f5-4015-8984-8227bd78679e', 'quantum__breakthrough__bristol-centre-for-quantum-photonics-first-quantum-algorithm-run-on-a-chip', 'quantum', 'breakthrough', NULL, 'Bristol Centre for Quantum Photonics — first quantum algorithm run on a chip', 'Alberto Politi; Jonathan Matthews; Dr Jeremy O''Brien; University of Bristol', 'Sep 2009', '2009-09-01', 'month', 'First experimental demonstration of quantum algorithms — including Shor''s factoring algorithm and a quantum walk — running on an integrated photonic chip. Used four photons coupled into silica waveguide circuits on a silicon chip, executing quantum logic sequences through a series of gates. Demonstrated that a chip-scale device could carry out complete quantum computations, not just individual gates.', 'https://www.science.org/doi/10.1126/science.1173731', true, 'Published in Science 325, 1221 (Sep 2009). This was a landmark integration of quantum algorithm execution with integrated photonics. Matthews, Politi and Stefanov et al. followed this in 2009 (Nature Photonics 3, 346) with a further manipulation of multi-photon entanglement in waveguide circuits. The work established Bristol as a world-leading centre for quantum photonics.', 'active', '2026-07-01', 2) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('084fdff9-7a2b-4b3f-b631-f11a078dd609', 'quantum__breakthrough__university-of-oxford-world-record-single-qubit-gate-fidelity-99-9999-1-in-1-mill', 'quantum', 'breakthrough', NULL, 'University of Oxford — world record single-qubit gate fidelity 99.9999% (1 in 1 million error rate)', 'Dr Tom Harty (first author); Dr David Allcock; Dr Chris Ballance; L. Guidoni; H. Janacek; Dr Norbert Linke; Dr David Stacey; Prof David Lucas; Department of Physics, University of Oxford', 'Nov 2014', '2014-11-01', 'month', 'World record single-qubit gate fidelity: 99.9999% (error rate of 10⁻⁶, or one mistake per million operations) — the first time ALL single-qubit operations (state preparation, gates, memory and readout) had been demonstrated significantly above the fault-tolerance threshold simultaneously. Used ⁴³Ca⁺ hyperfine qubits with microwave control. Achieved at room temperature without magnetic shielding, demonstrating practical viability. Memory coherence time of T*₂ = 50 seconds also set a record. The previous single-qubit record was orders of magnitude worse.', 'https://link.aps.org/doi/10.1103/PhysRevLett.113.220501', true, 'Published in Physical Review Letters 113, 220501 (24 Nov 2014). The record stood for over a decade until the same group (Smith, Leu, Gely, Lucas) broke it in June 2025 (10⁻⁷ level). Tom Harty and Chris Ballance — both authors on this paper — went on to co-found Oxford Ionics in 2019, translating this expertise directly into a commercial quantum computing company.', 'active', '2026-07-01', 3) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('1ed746c0-a979-4ab2-9b61-796d928d49b5', 'quantum__breakthrough__university-of-oxford-first-two-qubit-gate-above-the-fault-tolerance-threshold', 'quantum', 'breakthrough', NULL, 'University of Oxford — first two-qubit gate above the fault-tolerance threshold', 'Dr Chris Ballance (first author); Dr Tom Harty; Dr Norbert Linke; Dr Michael Sepiol; Prof David Lucas; Department of Physics, University of Oxford', 'Aug 2016', '2016-08-01', 'month', 'First trapped-ion two-qubit gate to exceed the ~99% fidelity threshold required for surface-code fault-tolerant quantum computation, achieving 99.9% two-qubit and 99.9934% single-qubit gate fidelities. Published simultaneously (same journal, same issue) with near-identical results from NIST (Gaebler et al.), with the two groups confirming the threshold crossing independently. The result triggered a global research push and is widely cited as the moment trapped-ion hardware crossed into the fault-tolerant regime. Used ⁴³Ca⁺ ions in a room-temperature trap, laser-driven gates.', 'https://link.aps.org/doi/10.1103/PhysRevLett.117.060504', true, 'Published in Physical Review Letters 117, 060504 (4 Aug 2016). One of the most cited papers in the entire field of quantum computing hardware (2,000+ citations). Prof David Lucas: "this is the sort of fidelity needed to run quantum error-correction codes." Ballance and Harty founded Oxford Ionics in 2019, which in July 2024 extended the two-qubit record to 99.97% without error correction — on a chip manufacturable in standard semiconductor fabs.', 'active', '2026-07-01', 4) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('10b93ba4-6682-4f2b-95a8-0183c4e62521', 'quantum__breakthrough__toshiba-cambridge-invention-of-twin-field-qkd-protocol-overcoming-the-fundamenta', 'quantum', 'breakthrough', NULL, 'Toshiba Cambridge — invention of Twin Field QKD protocol, overcoming the fundamental rate-distance limit', 'Marco Lucamarini (first author); Zhiliang Yuan; James Dynes; Andrew Shields; Toshiba Research Europe Cambridge Research Laboratory', 'May 2018', '2018-05-01', 'month', 'Invention of the Twin Field Quantum Key Distribution (TF-QKD) protocol — a theoretical breakthrough that overcomes the fundamental "PLOB bound" (the maximum secret key rate achievable per photon transmitted, previously thought to require quantum repeaters to exceed). By sending phase-randomised optical fields from both ends to a central relay, TF-QKD scales key rate with the square root (rather than the linear) of channel loss, enabling QKD over hundreds of kilometres without intermediate trusted nodes. The invention resolved a problem that had been considered impossible to solve without quantum repeaters.', 'https://www.nature.com/articles/s41586-018-0066-6', true, 'Published in Nature 557, 400–403 (May 2018). Immediately recognised as a fundamental advance, spawning a global experimental race. Toshiba itself demonstrated TF-QKD over 600 km in 2021 using the protocol. China, Japan and others have since pushed this beyond 800 km. Andrew Shields described this as one of the most important advances in QKD since BB84. The protocol is now the standard approach for long-haul quantum-secure networks.', 'active', '2026-07-01', 5) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('2feb8067-3850-4e1d-88e2-af41810041fa', 'quantum__breakthrough__toshiba-twin-field-qkd-and-600-km-fibre-record', 'quantum', 'breakthrough', NULL, 'Toshiba Twin Field QKD & 600 km fibre record', 'Mirko Pittaluga; Andrew Shields; Marco Lucamarini; Toshiba Europe Cambridge Research Laboratory', 'Jun 2021', '2021-06-01', 'month', 'First QKD over 600 km of optical fibre using a new "dual-band stabilisation" technique. The dual-band approach solves the phase-stability problem that had blocked long-haul coherent quantum comms; it extended viable QKD range 3–4× beyond the previous limit. Toshiba had invented the underlying Twin Field QKD protocol in 2018 (Lucamarini et al., Nature). This 2021 result was the first field-cable implementation on real long fibres.', 'https://www.toshiba.eu/quantum/news/toshiba-announces-breakthrough-in-long-distance-quantum-communication/', true, 'Published in Nature Photonics (2021). Described by Andrew Shields as validating a "commercially viable global quantum-secure network". Toshiba Cambridge is the world''s longest-running QKD research group, having held multiple distance and speed records since 2003.', 'active', '2026-07-01', 6) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('956dbd63-fbd3-4401-927d-c2c8123edeb5', 'quantum__breakthrough__bristol-qet-labs-error-protected-qubits-on-a-silicon-photonic-chip', 'quantum', 'breakthrough', NULL, 'Bristol QET Labs — error-protected qubits on a silicon photonic chip', 'Dr Caterina Vigliar (lead); Stefano Paesani; Jeremy Adcock; Prof Anthony Laing; Prof Mark Thompson; Prof John Rarity; Sam Morley-Short; University of Bristol QET Labs', 'Sep 2021', '2021-09-01', 'month', 'First integrated silicon photonic architecture that both entangles multiple photons and encodes multiple physical qubits per photon to produce error-protected (logical) qubits. Running a phase-estimation algorithm, the team improved success rate from 62.5% to 95.8% with error protection active. Demonstrated reconfigurable graph states including hypergraph states that protect against correlated errors — a key step towards all-photonic fault-tolerant quantum computing.', 'https://www.nature.com/articles/s41567-021-01333-w', true, 'Published in Nature Physics, 29 Sep 2021 (DOI: 10.1038/s41567-021-01333-w). Anthony Laing noted: "Finding ways to efficiently deliver large numbers of error protected qubits is key to one day delivering quantum computers."', 'active', '2026-07-01', 7) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('bf7d5e32-9117-4734-be84-52ca861e13c1', 'quantum__breakthrough__bristol-qet-labs-redefining-the-quantum-advantage-boundary-in-photonic-computing', 'quantum', 'breakthrough', NULL, 'Bristol QET Labs — redefining the quantum advantage boundary in photonic computing', 'Jacob Bulmer (lead); Prof Anthony Laing; Benjamin Morrison; Levon Halvagizyan; University of Bristol QET Labs; Imperial College London; Hewlett Packard Enterprise', 'Jan 2022', '2022-01-01', 'month', 'Produced substantially faster classical algorithms for simulating Gaussian Boson Sampling (GBS) experiments — achieving a ~1 billion-fold speedup over previous classical simulation estimates. Testing on a ~100,000-core supercomputer, the team reduced the claimed "600 million years to simulate" claims to mere months, fundamentally redefining where the quantum-classical boundary sits for photonic quantum advantage. Introduced new distributions to better certify future quantum advantage claims.', 'https://www.science.org/doi/10.1126/sciadv.abl9236', true, 'Published in Science Advances, Jan 2022. A pivotal methodological contribution: rather than claiming quantum advantage, this work clarified the evidential standards that must be met — shaping how future quantum advantage experiments are designed and reported globally.', 'active', '2026-07-01', 8) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('25399256-4b2a-4bd1-bdb1-c99227ee048b', 'quantum__breakthrough__birmingham-qusit-hub-world-s-first-field-quantum-gravity-gradiometer', 'quantum', 'breakthrough', NULL, 'Birmingham QuSIT Hub — world''s first field quantum gravity gradiometer', 'Dr Ben Stray (first author); Dr Andrew Lamb; Dr Aisha Kaushik; Jamie Vovrosh; Dr Michael Holynski (PI); Prof Kai Bongs (hub director); Prof Nicole Metje (civil engineering lead); Jonathan Winch; George Tuckwell (RSK); University of Birmingham; Dstl; RSK Group', 'Feb 2022', '2022-02-01', 'month', 'World''s first outdoor, real-world deployment of a quantum gravity gradiometer, detecting a tunnel buried beneath a Birmingham street. The atom-interferometry sensor uses two clouds of rubidium-87 atoms at microkelvin temperatures separated by 1 m vertically, comparing their interference patterns to map subsurface density changes while cancelling vibration noise. Gravity surveys that took a month are now deliverable in days.', 'https://www.nature.com/articles/s41586-021-04315-3', true, 'Published in Nature 602, 590–594 (23 Feb 2022; DOI: 10.1038/s41586-021-04315-3). Built under a Ministry of Defence contract and Innovate UK''s Gravity Pioneer project. Prof Kai Bongs described it as "an Edison moment in sensing." Led directly to the spinout Delta-g (2023, raised £1.5m). Described by Dstl as "transformational for the UK''s sovereign sensing capability."', 'active', '2026-07-01', 9) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('bd5800a4-0d0b-4a9b-b9dd-56aefcd9fc82', 'quantum__breakthrough__oxford-device-independent-qkd-certified-by-bell-s-theorem', 'quantum', 'breakthrough', NULL, 'Oxford — device-independent QKD certified by Bell''s theorem', 'David Nadlinger; Peter Drmota; Ben Nichol; Guillermo Araneda; Dougal Main; Dr Raghavendra Srinivas; Prof David Lucas; Dr Chris Ballance; University of Oxford', 'Jul 2022', '2022-07-01', 'month', 'First experimental demonstration of device-independent quantum key distribution (DI-QKD) using a trapped-ion quantum network node — the most fundamentally secure form of QKD in which security is guaranteed by the laws of physics alone, with no trust required in the devices themselves. Security certified by violation of Bell''s theorem. Three teams worldwide published simultaneously; Oxford''s was the first using matter (ion) qubits rather than photons.', 'https://www.nature.com/articles/s41586-022-04891-y', true, 'Published in Nature 607, 682–686 (2022). Published alongside two competing demonstrations (Munich photon-based; China photon-based), all three confirming the feasibility of DI-QKD. Oxford''s ion-trap approach offers a path to a full quantum repeater network. One of the most cited quantum security papers of the decade.', 'active', '2026-07-01', 10) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('cb9bc137-9434-4849-9f9f-eda562587ab3', 'quantum__breakthrough__oxford-first-quantum-network-of-entangled-optical-atomic-clocks', 'quantum', 'breakthrough', NULL, 'Oxford — first quantum network of entangled optical atomic clocks', 'Ben Nichol (first author); Dr Raghavendra Srinivas; David Nadlinger; Guillermo Araneda; Prof David Lucas; University of Oxford', 'Sep 2022', '2022-09-01', 'month', 'First demonstration of a quantum network of two remotely entangled optical atomic clocks. By sharing entanglement via a photonic link, the two Sr⁺ ion clocks surpassed the measurement precision achievable without entanglement — demonstrating that the "quantum projection noise limit" can be beaten across a network. Applications include the most precise tests of fundamental constants, geodesy, dark matter detection, and future global quantum clock networks.', 'https://www.nature.com/articles/s41586-022-05088-z', true, 'Published in Nature 609, 689–694 (Sep 2022). Prof David Lucas: "Our experiment shows the importance of quantum networks for metrology, with applications to fundamental physics." First demonstration that remote entanglement can genuinely enhance precision measurement across a physical network.', 'active', '2026-07-01', 11) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('d1745f9f-90ee-4b45-b1ee-34fda6ae0f90', 'quantum__breakthrough__sussex-universal-quantum-world-record-qubit-transfer-between-quantum-chip-module', 'quantum', 'breakthrough', NULL, 'Sussex / Universal Quantum — world-record qubit transfer between quantum chip modules', 'Dr Mariam Akhtar (lead researcher); Prof Winfried Hensinger (PI); Dr Sebastian Weidt; University of Sussex; Universal Quantum', 'Feb 2023', '2023-02-01', 'month', 'First ever transfer of quantum bits between separate quantum computing microchip modules using electric field ("quantum matter") links. Achieved 99.999993% fidelity and 2,424 transfers/second — both world records, orders of magnitude better than previous fibre-optic approaches. The "UQ Connect" technique allows modules to slot together like a jigsaw, providing a practical route to million-qubit modular quantum computers. The electric-field link operates at ~70 K, far warmer than competing superconducting approaches.', 'https://www.nature.com/articles/s41467-022-35285-3', true, 'Published in Nature Communications (8 Feb 2023). Universal Quantum won the IOP Business Start-up Award (2022) and a €67m contract from the German Aerospace Center (DLR) — at the time one of the largest single-company quantum computing government contracts worldwide. Prof Hensinger: "We have demonstrated a path to building a large-scale quantum computer."', 'active', '2026-07-01', 12) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('2b4a1528-2fb8-4559-9af9-d21065b56579', 'quantum__breakthrough__birmingham-delta-g-quantum-gravimeter-validated-at-sea', 'quantum', 'breakthrough', NULL, 'Birmingham / Delta-g — quantum gravimeter validated at sea', 'Dr Andrew Hinton; Adam Seedat; Dr Sanaz Roshanmanesh; Prof Michael Holynski; Dr Farzad Hayati; Dr Sha Luo; Dr Thomas King; Prof Nicole Metje; Jonathan Winch; Dr Andrew Lamb; University of Birmingham; Delta-g', 'Jul 2023', '2023-07-01', 'month', 'First validation of the Birmingham quantum gravity gradiometer in open marine conditions — operated on the open deck of a vessel in variable weather, including direct sunlight and rain, without inertial stabilisation, tilt control or temperature control. The system maintained atom interferometry throughout, demonstrating robustness beyond laboratory conditions and enabling marine gravity survey applications for subsea infrastructure, geodesy and mineral exploration.', 'https://www.birmingham.ac.uk/news/2023/quantum-sensor-for-gravity-gradiometry-successfully-validated-at-sea', true, 'Built on the 2022 Nature paper (DOI: 10.1038/s41586-021-04315-3). The marine validation was a key milestone for commercialisation via Delta-g. Prof Holynski: "The system was able to perform atom interferometry in variable weather conditions." Delta-g subsequently raised £1.5m seed funding (Jul 2023) to commercialise the technology.', 'active', '2026-07-01', 13) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('318161f7-ed75-4777-b1c2-3e2a0e0196bc', 'quantum__breakthrough__oxford-verifiable-blind-quantum-computing-with-trapped-ions-and-photons', 'quantum', 'breakthrough', NULL, 'Oxford — verifiable blind quantum computing with trapped ions and photons', 'Peter Drmota; David Nadlinger; Dougal Main; Ben Nichol; Emily Ainley; Dr Raghavendra Srinivas; Guillermo Araneda; Prof Elham Kashefi (Edinburgh); Dr Chris Ballance; Prof David Lucas; University of Oxford / University of Edinburgh / University of Maryland', 'Apr 2024', '2024-04-01', 'month', 'First hybrid matter-photon implementation of verifiable blind quantum computing (VBQC) — a protocol allowing a client to delegate computations to a remote quantum server with cryptographic proof that (a) the server performs the right computation, and (b) the server learns at most 0.03 bits per qubit about the computation. Uses a trapped-ion quantum server linked via optical fibre to a simple photon-detector client. Crucially, the scheme works without post-selection (a limitation of prior demonstrations), making it compatible with interactive protocols.', 'https://link.aps.org/doi/10.1103/PhysRevLett.132.150604', true, 'Published in Physical Review Letters 132, 150604 (10 Apr 2024). Selected as an "Editor''s Suggestion." Prof Kashefi (Edinburgh/NQCC Chief Scientist): "This demonstrates a path to fully verified quantum computing in the cloud." Foundational for a future quantum internet where users can securely outsource computations.', 'active', '2026-07-01', 14) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('3c938ad3-894f-4e81-84fb-556d2f50a3af', 'quantum__breakthrough__oxford-ionics-world-s-highest-performing-manufacturable-quantum-chip-without-err', 'quantum', 'breakthrough', NULL, 'Oxford Ionics — world''s highest-performing manufacturable quantum chip (without error correction)', 'Dr Chris Ballance (CEO, co-founder); Dr Tom Harty (Chief Scientist, co-founder); Oxford Ionics', 'Jul 2024', '2024-07-01', 'month', 'Demonstrated the highest-performing quantum chip in the world that can be manufactured in standard semiconductor fabrication plants using the company''s patented Electronic Qubit Control (EQC) system, which replaces laser control with embedded silicon electronics. Achieved two-qubit gate fidelity of 99.97% and single-qubit fidelity of 99.9992% — setting industry records without requiring error correction. Previous world records had relied on error correction to reach comparable levels using 10× more qubits. IonQ (which acquired Oxford Ionics in 2025) subsequently extended this to 99.99% using the same EQC technology (Oct 2025).', 'https://www.oxionics.com/announcements/oxford-ionics-breaks-global-quantum-performance-records/', true, 'Announced 11 Jul 2024. Validated at the University of Oxford physics labs. Dr Michael Cuthbert (NQCC Director): "These results validate the scalability of the technology." Oxford Ionics also set a separate world record for SPAM fidelity of 99.9993% (Sep 2024), a 13× improvement on the previous best approach.', 'active', '2026-07-01', 15) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('04772cc7-3432-4de8-a246-231024aacf19', 'quantum__breakthrough__oxford-first-distributed-quantum-algorithm-across-separate-quantum-processors', 'quantum', 'breakthrough', NULL, 'Oxford — first distributed quantum algorithm across separate quantum processors', 'Dougal Main (lead); Peter Drmota; David Nadlinger; Emily Ainley; Aniruth Agrawal; Ben Nichol; Dr Raghavendra Srinivas; Guillermo Araneda; Prof David Lucas; University of Oxford', 'Feb 2025', '2025-02-01', 'month', 'First ever demonstration of a quantum algorithm distributed across two physically separate quantum processors linked by an optical fibre. Used deterministic quantum gate teleportation (CZ gate, 86% fidelity) between two trapped-ion modules to run Grover''s search algorithm — the first distributed quantum algorithm involving multiple non-local two-qubit gates (71% success rate). Also demonstrated distributed iSWAP and SWAP circuits. The architecture allows arbitrary two-qubit operations to be distributed across modules, enabling modular quantum computers of arbitrary scale.', 'https://www.nature.com/articles/s41586-024-08404-x', true, 'Published in Nature 638, 383–388 (Feb 2025). Prof David Lucas (principal investigator): "Our experiment demonstrates that network-distributed quantum information processing is feasible with current technology." Dougal Main: "We use quantum teleportation to create interactions between physically separated systems." Recognised internationally as a key milestone for the quantum internet and modular quantum computing.', 'active', '2026-07-01', 16) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('cdeee259-b584-4209-9c5a-fb1c1eb4e49a', 'quantum__breakthrough__university-of-oxford-world-record-single-qubit-gate-fidelity-99-99999', 'quantum', 'breakthrough', NULL, 'University of Oxford — world record single-qubit gate fidelity (99.99999%)', 'Molly Smith (lead, grad student); Aaron Leu (co-lead); Dr Mario Gely; Prof David Lucas; Dr Koichiro Miyanishi (visiting, Osaka University); University of Oxford QCS Hub', 'Jun 2025', '2025-06-01', 'month', 'World record single-qubit gate fidelity on any quantum computing platform: error rate below 10⁻⁷ (one error per 6.7 million operations, fidelity >99.99999%). Nearly an order of magnitude improvement on the previous benchmark set by the same group a decade earlier. Achieved using a single ⁴³Ca⁺ trapped-ion qubit with hyperfine "clock" transition. A person is more likely to be struck by lightning in a year (1 in 1.2 million chance) than for one of these gates to fail. Addresses one of the core barriers to fault-tolerant quantum computing.', 'https://journals.aps.org/prl/accepted/10.1103/42w2-6ccy', true, 'Published in Physical Review Letters 134, 230601 (13 Jun 2025; DOI: 10.1103/42w2-6ccy). Prof David Lucas: "As far as we are aware, this is the most accurate qubit operation ever recorded anywhere in the world. It is an important step toward building practical quantum computers that can tackle real-world problems." Part of the NQTP Quantum Computing and Simulation Hub.', 'active', '2026-07-01', 17) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('88d46a99-8aab-4104-bcdf-c17e7f4a7d39', 'quantum__breakthrough__riverlane-world-s-first-dedicated-hardware-quantum-error-correction-decoder', 'quantum', 'breakthrough', NULL, 'Riverlane — world''s first dedicated hardware quantum error correction decoder', 'Steve Brierley (CEO, founder); Konstantina Maragkou (CTO); Riverlane (Cambridge spinout)', 'Dec 2025', '2025-12-01', 'month', 'First dedicated hardware decoder delivering real-time, scalable quantum error correction at utility-relevant speeds. Deltaflow 2''s Local Clustering Decoder (LCD) achieves 16.32 µs mean latency — 4× faster than Google''s published results on the same Willow surface code experiment, and up to 10× lower sub-shot latency. Processes up to 250 physical qubits in real time. The hardware decoder enables "streaming" error correction: detecting and correcting errors as computation runs, without interrupting it — a prerequisite for fault-tolerant quantum computers. Deployed at the NQCC at Harwell and Oak Ridge National Laboratory.', 'https://www.riverlane.com/news/riverlane-unveils-first-hardware-decoder-to-deliver-real-time-scalable-quantum-error-correction', true, 'Announced Dec 2025. Steve Brierley: "We have shown that real-time error correction is possible." Riverlane is partnered with >60% of the world''s quantum computer companies and has raised >$120m, including an $85m Series C in 2024. Part of NQCC testbed programme. Deltaflow 3 (streaming logic for logical qubits) expected late 2026.', 'active', '2026-07-01', 18) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('4f14c621-ab2d-489c-9234-7eab9cc4df25', 'quantum__breakthrough__orca-computing-vodafone-first-quantum-accelerated-real-world-telco-network-optim', 'quantum', 'breakthrough', NULL, 'ORCA Computing / Vodafone — first quantum-accelerated real-world telco network optimisation', 'Richard Murray (CEO, ORCA); Prof Ian Walmsley (Chair, ORCA); James Fletcher (Head of Solutions Architecture, ORCA); Luke Ibbetson (Head of R&D, Vodafone); via UK Quantum Technology Access Programme (QTAP)', 'Jun 2025', '2025-06-01', 'month', 'First demonstration of a photonic quantum computer solving a commercially relevant telecommunications optimisation problem — the Steiner Tree Problem (identifying the most cost-efficient way to extend connectivity) — in minutes, versus hours with classical methods. Used ORCA''s room-temperature PT-2 photonic quantum system. Vodafone aims to apply this to optimise its global network spanning 200+ destinations, including undersea cables carrying 1/6 of the world''s internet traffic. Both parties signed a Letter of Intent for commercial development. First photonic quantum system installed in the UK public sector (NQCC, Oct 2024).', 'https://orcacomputing.com/vodafone-partners-with-orca-computing-to-model-future-networks-in-minutes-using-quantum-technology/', true, 'Announced Jun 2025. James Fletcher (ORCA): "We have shown that quantum acceleration of telecommunications use cases is not just a theoretical concept, it''s a viable, deployable and commercially compelling solution." Built on the joint UKRI/industry Quantum Technology Access Programme. Vodafone''s network spans 200+ destinations including an undersea cable network carrying ~1/6 of global internet traffic.', 'active', '2026-07-01', 19) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('f0cb0bd2-1590-4f61-99ac-73d72fc4f0f6', 'quantum__evolving__department-name-changed-twice-within-days', 'quantum', 'evolving', NULL, 'Department name changed twice within days', NULL, 'Jul 2026', '2026-07-01', 'month', 'DSIT''s functions were redistributed into a business department initially referred to as "DBIST"; GOV.UK''s own Machinery of Government fact sheet was itself corrected on 27 Jul 2026, shortening the acronym to "BIST." This tool uses "DBIST"/the business department descriptively throughout — worth checking current usage before publishing further updates.', 'https://www.gov.uk/government/news/machinery-of-government-changes-fact-sheet', true, 'Terminology genuinely still in flux; affects every sector in this tool, not just quantum.', 'active', '2026-07-01', 0) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('7d5a78c5-59e7-4aeb-98e5-f0ac601178e2', 'quantum__evolving__continuity-of-quantum-specific-policy-leadership-still-unclear', 'quantum', 'evolving', NULL, 'Continuity of quantum-specific policy leadership still unclear', NULL, 'Jul 2026 – ongoing', '2026-07-01', 'range', 'Industry commentary has noted that the written statement announcing the DSIT split did not mention quantum specifically, despite £2bn committed to the sector in March 2026 (including roughly £1bn for the ProQure quantum-computer procurement programme) and the first ProQure contracts due in October 2026 — widely framed as the new department''s first real test on quantum.', NULL, false, 'No official statement identified yet confirming continuity of quantum-specific leadership within the reorganised department.', 'active', '2026-07-01', 1) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('0d682f01-d9aa-45a3-bc7e-716f30071c8e', 'quantum__evolving__us-uk-technology-prosperity-deal-quantum-strand-still-unsettled', 'quantum', 'evolving', NULL, 'US–UK Technology Prosperity Deal — quantum strand still unsettled', NULL, 'Since Dec 2025', '2025-12-01', 'range', 'Beyond the pause/restart already noted in this tool''s footer, industry analysis published Feb 2026 described talks as having resumed in Jan 2026 with a "realistic possibility" of further negotiation on regulatory cooperation; the TPD''s committed joint US-UK quantum benchmarking task force and a proposed Quantum Exchange Program had not, as of that analysis, produced confirmed delivery detail.', NULL, false, 'Status of the quantum-specific commitments within the wider TPD genuinely unclear as of this research.', 'active', '2026-07-01', 2) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('a5812e38-95ce-4a48-b86d-e9233fde56c1', 'quantum__evolving__quantum-growth-alliance-newly-announced-unproven', 'quantum', 'evolving', NULL, 'Quantum Growth Alliance — newly announced, unproven', NULL, 'Jun 2026', '2026-06-01', 'month', 'Announced by the then-Science Minister as an industry coalition spanning finance, pharmaceuticals, energy, defence and telecommunications, intended to stimulate domestic demand for quantum technology. Too new to assess delivery; also announced alongside an "upcoming" £12m fund for hybrid quantum algorithms not yet formally launched at time of announcement.', NULL, false, NULL, 'active', '2026-07-01', 3) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('2f323479-20df-4f37-b2fe-ad1862048111', 'engbio__timeline__a-synthetic-biology-roadmap-for-the-uk-published', 'engbio', 'timeline', NULL, 'A Synthetic Biology Roadmap for the UK published', NULL, 'Jul 2012', '2012-07-01', 'month', 'Foundational roadmap from an independent panel of 70+ stakeholders, commissioned via the Technology Strategy Board for the Department for Business, Innovation and Skills. Set five core recommendations including investment in a network of multidisciplinary centres. Accompanied by a £50m government capital investment (2012 Autumn Statement) and the establishment of the Synthetic Biology Leadership Council (SBLC).', 'https://iuk-business-connect.org.uk/perspectives/a-strategic-roadmap-for-synthetic-biology-in-the-uk-2012/', true, NULL, 'active', '2026-08-01', 0) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('bc0f7587-f644-48fd-b055-f7544645c003', 'engbio__timeline__synthetic-biology-named-one-of-uk-s-eight-great-technologies-synbicite-establish', 'engbio', 'timeline', NULL, 'Synthetic biology named one of UK''s "Eight Great Technologies"; SynbiCITE established', NULL, '2013', '2013-01-01', 'year', 'Government elevation of the field to a named national R&D priority; UK-wide competition established SynbiCITE at Imperial College London as the national Innovation & Knowledge Centre for synthetic/engineering biology.', 'https://en.wikipedia.org/wiki/SynbiCITE', true, NULL, 'active', '2026-08-01', 1) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('f6af3f06-1d69-4fd8-834f-abd45012c4ed', 'engbio__timeline__uk-synthetic-biology-strategic-plan-2016-biodesign-for-the-bioeconomy', 'engbio', 'timeline', NULL, 'UK Synthetic Biology Strategic Plan 2016 — "Biodesign for the Bioeconomy"', NULL, 'Feb 2016', '2016-02-01', 'month', 'Refresh of the 2012 Roadmap published by the Synthetic Biology Leadership Council, launched by Life Sciences Minister George Freeman MP at SynbiCITE. Five strategic themes including accelerating industrialisation/commercialisation and building value from international partnerships.', 'https://www.engbio.cam.ac.uk/news/synbio-strategic-plan-2016', true, NULL, 'active', '2026-08-01', 2) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('b4a85eb3-952c-444b-871f-614e27d0f177', 'engbio__timeline__rosalind-franklin-institute-launched', 'engbio', 'timeline', NULL, 'Rosalind Franklin Institute launched', NULL, 'Jun 2018', '2018-06-01', 'month', '£103m EPSRC investment; national life-science technology institute at Harwell backed by 10 universities, STFC and Diamond Light Source. Later did engineering-biology-relevant work in protein post-translational modification and in-cell chemistry. Officially opened Sep 2021.', 'https://www.ukri.org/who-we-are/epsrc/centres-and-institutes/rosalind-franklin-institute/', true, NULL, 'active', '2026-08-01', 3) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('d2931e5d-66a9-40d7-92dc-bbd38641804e', 'engbio__timeline__synthetic-biology-leadership-council-renamed-engineering-biology-leadership-coun', 'engbio', 'timeline', NULL, 'Synthetic Biology Leadership Council renamed Engineering Biology Leadership Council', NULL, 'c. 2020', '2020-01-01', 'range', 'Reflects the field''s shift from "synthetic biology" (research-base term) to "engineering biology" (government''s preferred applied/industrial term); co-chaired at the time by Nadhim Zahawi MP.', 'https://www.newstatesman.com/spotlight/2020/07/growing-strong', true, NULL, 'active', '2026-08-01', 4) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('4b5406a5-4d5f-4a70-a67e-2d3bb8533d0d', 'engbio__timeline__eblc-publishes-engineering-biology-for-the-uk-a-resource-to-help-build-back-bett', 'engbio', 'timeline', NULL, 'EBLC publishes "Engineering Biology for the UK: A Resource to Help Build Back Better"', NULL, 'Jul 2021', '2021-07-01', 'month', 'Industry-government council report identifying priority actions across agri-food, chemicals/materials and healthcare application segments.', 'https://iuk-business-connect.org.uk/wp-content/uploads/2021/07/EBLC-Building-back-better-with-Engineering-Biology_upload.pdf', true, NULL, 'active', '2026-08-01', 5) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('b6a1cddc-24ef-4e0f-8d61-8aa861ac4540', 'engbio__timeline__genetic-technology-precision-breeding-act-2023-royal-assent', 'engbio', 'timeline', NULL, 'Genetic Technology (Precision Breeding) Act 2023 — Royal Assent', NULL, '23 Mar 2023', '2023-03-23', 'day', 'Removes gene-edited ("precision bred") organisms whose changes could occur naturally or through conventional breeding from GMO regulation — England only.', 'https://bills.parliament.uk/bills/3167', true, 'Applies to England only; Scotland, Wales and Northern Ireland retain separate GMO regimes — see footer.', 'active', '2026-08-01', 6) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('1db8ae32-f365-4f4f-acf4-b87f298394de', 'engbio__timeline__uk-biological-security-strategy-published', 'engbio', 'timeline', NULL, 'UK Biological Security Strategy published', NULL, 'Jun 2023', '2023-06-01', 'month', 'Cabinet Office cross-government strategy on biological risk, explicitly linking biosecurity to engineering biology R&D growth. Established the UK Biological Security Leadership Council (Sept 2023).', 'https://assets.publishing.service.gov.uk/media/64c0ded51e10bf000e17ceba/UK_Biological_Security_Strategy.pdf', true, NULL, 'active', '2026-08-01', 7) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('c0d65e35-b031-4bb2-b01f-8dd8798b13bf', 'engbio__timeline__national-vision-for-engineering-biology-published', 'engbio', 'timeline', NULL, 'National Vision for Engineering Biology published', NULL, '5 Dec 2023', '2023-12-05', 'day', 'DSIT policy paper (Minister Andrew Griffith MP) — £2bn over 10 years; defines government''s collective ambition and regulatory/investment direction. Engineering biology named alongside AI, quantum, semiconductors and future telecoms as one of five critical technologies.', 'https://www.gov.uk/government/publications/national-vision-for-engineering-biology/national-vision-for-engineering-biology', true, NULL, 'active', '2026-08-01', 8) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('0d548d20-9020-477f-b49d-3b26d87dcf24', 'engbio__timeline__ukri-announces-100-125m-engineering-biology-mission-hubs-and-awards', 'engbio', 'timeline', NULL, 'UKRI announces £100–125m Engineering Biology Mission Hubs & Awards', NULL, 'Feb 2024', '2024-02-01', 'month', '6 Mission Hubs (up to £12m each, 5 years) + 22 Mission Awards (sharing £30m, 2 years), funded via £60m Technology Missions Fund + £65m UKRI core budget.', 'https://www.ukri.org/news/new-100m-fund-will-unlock-the-potential-of-engineering-biology/', true, NULL, 'active', '2026-08-01', 9) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('48c79e10-6790-4f8c-8dd3-bf42e883c1c2', 'engbio__timeline__engineering-biology-metrics-and-technical-standards-for-the-global-bioeconomy-pu', 'engbio', 'timeline', NULL, 'Engineering Biology Metrics and Technical Standards for the Global Bioeconomy published', NULL, 'May 2024', '2024-05-01', 'month', 'International standards report coordinated by Imperial College London (Prof Paul Freemont), EBRC (US), NIST (US) and NUS (Singapore), supported by Schmidt Sciences. Identifies 10 priority focus areas for the bioeconomy.', 'https://ebrc.org/publications-metrics-and-standards/', true, NULL, 'active', '2026-08-01', 10) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('b46d24e1-e75e-4765-b6a4-f0085c6d503a', 'engbio__timeline__regulatory-innovation-office-rio-established-first-engineering-biology-sandbox-f', 'engbio', 'timeline', NULL, 'Regulatory Innovation Office (RIO) established; first Engineering Biology Sandbox Fund winners announced', NULL, '8 Oct 2024', '2024-10-08', 'day', 'New DSIT office to speed regulatory decisions; engineering biology named a founding focus sector alongside space, AI, healthcare and drones. Same-day announcement of first-round Sandbox Fund winners (£1.6m), incl. the Food Standards Agency''s Cell-Cultivated Product Regulatory Sandbox.', 'https://en.wikipedia.org/wiki/Regulatory_Innovation_Office', true, NULL, 'active', '2026-08-01', 11) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('d00d710b-02de-46e1-a551-276266e1c3f1', 'engbio__timeline__house-of-lords-s-and-t-committee-report-don-t-fail-to-scale-seizing-the-opportun', 'engbio', 'timeline', NULL, 'House of Lords S&T Committee report — "Don''t fail to scale: Seizing the opportunity of engineering biology"', NULL, '14 Jan 2025', '2025-01-14', 'day', 'Recommended a "national sector champion" for the field; pressed on Biological Security Strategy follow-through and international coordination.', 'https://lordslibrary.parliament.uk/science-and-technology-committee-report-on-seizing-the-opportunity-of-engineering-biology/', true, NULL, 'active', '2026-08-01', 12) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('e5473455-f0b0-4b19-86a9-c33f0f73967c', 'engbio__timeline__modern-industrial-strategy-digital-and-technologies-sector-plan-published', 'engbio', 'timeline', NULL, 'Modern Industrial Strategy + Digital and Technologies Sector Plan published', NULL, '23 Jun 2025', '2025-06-23', 'day', 'Engineering biology confirmed as 1 of 6 frontier technologies. £380m new funding: £196m National Engineering Biology Programme continuation + £184m Engineering Biology Scale-up Infrastructure Programme.', 'https://www.bioindustry.org/resource/industrial-strategy-digital-and-technologies-sector-plan.html', true, NULL, 'active', '2026-08-01', 13) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('82064a31-c4a1-437a-9d2e-03c381ec86d6', 'engbio__timeline__us-uk-technology-prosperity-deal-signed', 'engbio', 'timeline', NULL, 'US–UK Technology Prosperity Deal signed', NULL, '18 Sep 2025', '2025-09-18', 'day', 'MoU signed by President Trump and PM Starmer at Chequers; includes a flagship AI-for-biotechnology/precision-medicine research programme linking US DOE/NSF/NIH with UKRI.', 'https://uk.usembassy.gov/the-u-s-state-visit-to-the-uk-securing-the-tech-prosperity-deal/', true, 'Paused 16 Dec 2025; partially restarted Feb 2026 — see footer.', 'active', '2026-08-01', 14) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('295ecca6-b9bf-48e4-94a9-c06b0e4c3128', 'engbio__timeline__genetic-technology-precision-breeding-regulations-2025-in-force', 'engbio', 'timeline', NULL, 'Genetic Technology (Precision Breeding) Regulations 2025 in force', NULL, '13 Nov 2025', '2025-11-13', 'day', 'Completes the operational pathway for the 2023 Act for plants in England; gene-edited products could reach UK shelves by late 2026.', 'https://www.mofo.com/resources/insights/251125-uk-finalizes-precision-breeding-rules', true, NULL, 'active', '2026-08-01', 15) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('d07c06d7-b0af-46b5-b316-ec5c57be4f02', 'engbio__timeline__engineering-biology-research-in-northern-ireland-strategic-roadmap-published', 'engbio', 'timeline', NULL, '"Engineering Biology Research in Northern Ireland" strategic roadmap published', NULL, 'Apr 2026', '2026-04-01', 'month', 'First integrated engineering biology framework for Northern Ireland, commissioned by Matrix (NI Science Industry Panel) and launched by NI Economy Minister Dr Caoimhe Archibald. Notes NI receives ~1% of UKRI funding against 2.8% of UK population.', 'https://matrixni.org/wp-content/uploads/2026/04/Matrix_EBNI_Full_Report-Digital-April2026.pdf', true, NULL, 'active', '2026-08-01', 16) ON CONFLICT (record_key) DO NOTHING;
