INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('0575f2c1-72af-42bc-8b78-8a837a9af316', 'engbio__timeline__dsit-abolished-engineering-biology-policy-moves-to-dbist', 'engbio', 'timeline', NULL, 'DSIT abolished; engineering biology policy moves to DBIST', NULL, 'Jul 2026', '2026-07-01', 'month', 'Department for Science, Innovation and Technology dissolved under new PM Andy Burnham and merged into the newly created Department for Business, Innovation, Science and Trade (DBIST). Chris McDonald MP appointed Science Minister with oversight of UKRI; no dedicated engineering biology minister named separately as of this research.', 'https://www.techuk.org/resource/chris-mcdonald-named-science-minister-at-newly-formed-dbist.html', true, 'Machinery-of-government change; historical entries above are preserved as accurate records under the ministers/department who held responsibility at the time.', 'active', '2026-08-01', 18) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('44b0d682-4712-44c8-a413-9078e0b36daa', 'engbio__institution__dsit-dissolved-jul-2026', 'engbio', 'institution', NULL, 'DSIT (dissolved Jul 2026)', NULL, NULL, NULL, NULL, 'Former Department for Science, Innovation and Technology; set engineering biology policy and held the budget until dissolved and folded into DBIST in July 2026.', 'https://www.gov.uk/government/organisations/department-for-science-innovation-and-technology', true, 'Abolished Jul 2026; functions transferred to DBIST.', 'dissolved', '2026-08-01', 0) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('cf5e1041-2d80-47ec-a1ad-d230b6001374', 'engbio__institution__dbist', 'engbio', 'institution', NULL, 'DBIST', NULL, NULL, NULL, NULL, 'Department for Business, Innovation, Science and Trade — successor department formed Jul 2026 from the merger of DSIT into the business department; now sets engineering biology policy and holds the budget via UKRI oversight (Science Minister Chris McDonald MP).', 'https://www.gov.uk/government/organisations/department-for-business-and-trade', true, NULL, 'active', '2026-08-01', 1) ON CONFLICT (record_key) DO NOTHING;
