INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('c1b4809e-b1e3-4493-b477-88f43bedf32a', 'engbio__initiative__erasynbio-era-cobiotech-horizon-europe-re-association', 'engbio', 'initiative', 'international', 'ERASynBio → ERA CoBioTech / Horizon Europe re-association', NULL, '2012–present', '2012-01-01', 'range', 'ERASynBio ran as an EC-funded ERA-Net (2012–14), then self-sustaining from 2015; folded into ERA CoBioTech (Horizon 2020 Cofund). UK formally re-associated with Horizon Europe from Dec 2023/2024 Work Programme onward, restoring full-terms eligibility for this collaboration pathway.', 'https://www.ukro.ac.uk/wp-content/uploads/2023/12/UK_association_factsheet.pdf', true, NULL, 'active', '2026-08-01', 21) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('d5a7f9de-2ae9-48fe-b06f-ea94a40749e5', 'engbio__breakthrough__synbicite-opens-the-london-biofoundry', 'engbio', 'breakthrough', NULL, 'SynbiCITE opens the London Biofoundry', 'SynbiCITE / Imperial College London', '2016', '2016-01-01', 'year', 'UK''s first commercial synthetic biology foundry, providing automated end-to-end design, construction and validation of synthetic biological components.', 'https://www.clinicaltrialsarena.com/news/newssynbicite-opens-commercial-synthetic-biology-foundry-imperial-college-london-uk-4858329/', true, NULL, 'active', '2026-08-01', 0) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('f3c8993e-6a43-46ed-921c-d83e82861d3b', 'engbio__breakthrough__syn61-world-s-first-organism-with-a-fully-synthetic-radically-recoded-genome', 'engbio', 'breakthrough', NULL, 'Syn61 — world''s first organism with a fully synthetic, radically recoded genome', 'Prof Jason Chin; MRC Laboratory of Molecular Biology, Cambridge', 'May 2019', '2019-05-01', 'month', 'Synthesised and recoded the entire E. coli genome to use only 61 of the 64 codons — roughly 4x larger gene replacement than any prior organism, creating a bacterium with a different genetic code from all other known life.', 'https://www.chemistryviews.org/details/news/11155195/Bacterium_with_Fully_Synthetic_Genome_Created/', true, 'Published in Nature 569, 514–518 (2019). Called "a major milestone" by Harvard''s George Church. Chin later founded Constructive Bio to commercialise this platform.', 'active', '2026-08-01', 1) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('651845ed-a019-40c5-8b72-1728108d21d8', 'engbio__breakthrough__genetic-code-reprogramming-demonstrates-viral-resistance', 'engbio', 'breakthrough', NULL, 'Genetic code reprogramming demonstrates viral resistance', 'Prof Jason Chin; MRC Laboratory of Molecular Biology, Cambridge', '2021', '2021-01-01', 'year', 'Showed that a recoded genome can confer multi-virus resistance — industrially relevant given phage contamination costs in bioproduction (E. coli is used in 30% of approved therapeutic proteins).', 'https://constructive.bio/about', true, 'Published in Science. Part of the same research programme that produced Syn61.', 'active', '2026-08-01', 2) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('4347eed4-b3ed-4ec4-a2a8-86e5277beaa3', 'engbio__breakthrough__be-car7-world-s-first-use-of-a-base-edited-cell-therapy', 'engbio', 'breakthrough', NULL, 'BE-CAR7 — world''s first use of a base-edited cell therapy', 'Prof Waseem Qasim; UCL Great Ormond Street Institute of Child Health; Great Ormond Street Hospital', 'May 2022', '2022-05-01', 'month', 'UK-developed base-editing platform first used in-human on 13-year-old patient Alyssa Tapley, treating previously-untreatable T-cell acute lymphoblastic leukaemia after all conventional therapies (including a bone marrow transplant) had failed. Base editing precisely changes single DNA letters without double-strand breaks — a more precise evolution of CRISPR.', 'https://www.ucl.ac.uk/news/2025/dec/world-first-base-edited-gene-therapy-helps-patients-fight-previously-incurable-blood-cancer', true, 'Funded by the Medical Research Council, Wellcome, Blood Cancer UK and NIHR. Further 3-patient trial data published in the New England Journal of Medicine, Dec 2025.', 'active', '2026-08-01', 3) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('b80eb3ce-7b4d-47e4-bb23-5d54bcb6c25e', 'engbio__breakthrough__mhra-approves-casgevy-world-s-first-crispr-cas9-gene-edited-therapy-approval', 'engbio', 'breakthrough', NULL, 'MHRA approves Casgevy — world''s first CRISPR/Cas9 gene-edited therapy approval', 'Vertex Pharmaceuticals; CRISPR Therapeutics', '16 Nov 2023', '2023-11-16', 'day', 'UK regulatory world-first, predating FDA approval by three weeks. Therapy (exagamglogene autotemcel) treats sickle cell disease and transfusion-dependent beta thalassemia.', 'https://news.vrtx.com/news-releases/news-release-details/vertex-and-crispr-therapeutics-announce-authorization-first', true, 'Base CRISPR-Cas9 system credited to Charpentier & Doudna (2020 Nobel Prize in Chemistry); Casgevy itself was developed by US firm Vertex and Swiss-founded CRISPR Therapeutics — a UK regulatory first rather than UK-origin science.', 'active', '2026-08-01', 4) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('4b83c191-b195-4481-bcb8-d76ea9d5cc13', 'engbio__breakthrough__uk-team-completes-synthetic-yeast-chromosome-xi-synxi', 'engbio', 'breakthrough', NULL, 'UK team completes synthetic yeast chromosome XI (synXI)', 'Dr Ben Blount, University of Nottingham; Prof Tom Ellis, Imperial College London', '8 Nov 2023', '2023-11-08', 'day', '660,000 base-pair synthetic chromosome, a 10-year construction effort — UK contribution to the international Sc2.0 project to build the world''s first synthetic yeast genome, alongside teams in the US, China, Singapore, France, Australia and Japan.', 'https://www.imperial.ac.uk/news/249414/scientists-take-huge-step-towards-making/', true, 'Published in Cell Genomics. One of 16 yeast chromosomes; part of the largest synthetic-genome collaboration ever undertaken.', 'active', '2026-08-01', 5) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('0829ed60-014b-4901-9acd-e3951da9c02b', 'engbio__breakthrough__trna-display-method-for-translation-machinery-engineering', 'engbio', 'breakthrough', NULL, 'tRNA display method for translation machinery engineering', 'Prof Jason Chin; MRC Laboratory of Molecular Biology / Constructive Bio', '2024', '2024-01-01', 'year', 'New method for engineering the cellular translation machinery itself, building toward genetically encoded synthesis of new materials and therapeutics.', 'https://constructive.bio/about', true, 'Published in Nature.', 'active', '2026-08-01', 6) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('0806305c-e499-4372-bd52-a2e64e10d6cb', 'engbio__breakthrough__advance-to-57-codon-genetic-code', 'engbio', 'breakthrough', NULL, 'Advance to 57-codon genetic code', 'Prof Jason Chin; Constructive Bio', '2025', '2025-01-01', 'year', 'Further compression of the genetic code (from 61 to 57 codons), widening the chemical space accessible to genetically encoded synthesis of novel biomolecules.', 'https://constructive.bio/about', true, 'Published in Science.', 'active', '2026-08-01', 7) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('f522f951-5dd2-4a80-b664-be064ba7c9ec', 'engbio__breakthrough__colorifix-first-fully-biological-commercial-textile-dyeing-process', 'engbio', 'breakthrough', NULL, 'Colorifix — first fully biological commercial textile dyeing process', 'Dr Jim Ajioka; Dr Orr Yarkoni; Dr David Nugent', '2016–present', '2016-01-01', 'range', 'Cambridge/Norwich spin-out from the Ajioka Lab, inspired by UKRI OpenPlant research. Genetically engineers bacteria to produce and fix natural pigments onto textiles, cutting water, energy and chemical use versus conventional dyeing.', 'https://www.discover.ukri.org/colorifix/index.html', true, '£18m Series B led by H&M Group (2022); partnered with Basecamp Research (2023) on AI-designed dye-production enzymes.', 'active', '2026-08-01', 8) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('ec8c526e-ed74-49f7-a4eb-17494c771d5f', 'engbio__breakthrough__bit-bio-opti-ox-human-cell-programming-platform', 'engbio', 'breakthrough', NULL, 'bit.bio — opti-ox human cell programming platform', 'Dr Mark Kotter; bit.bio', '2016–present', '2016-01-01', 'range', 'Cambridge spin-out reprogramming induced pluripotent stem cells into defined, mature human cell types at industrial scale via patented safe-harbour gene targeting — positioned as a New Approach Methodology reducing reliance on animal testing.', 'https://finance.yahoo.com/news/m-g-champions-uk-innovation-173100416.html', true, '$200m+ raised to date; $50m Series C led by M&G Investments (Jan 2026), following a $30m round in Dec 2024.', 'active', '2026-08-01', 9) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('a159b860-8f34-4773-931d-e01de4e6e923', 'engbio__breakthrough__touchlight-cell-free-doggybone-dna-dbdna-manufacturing-platform', 'engbio', 'breakthrough', NULL, 'Touchlight — cell-free "doggybone" DNA (dbDNA) manufacturing platform', 'Jonny Ohlson (founder); Touchlight', '2007–present', '2007-01-01', 'range', 'Enzymatic, cell-free synthetic DNA vector platform (proTLx/dbDNA) disrupting traditional plasmid-DNA production, used in genetic medicine manufacturing including DNA vaccines and advanced therapies.', 'https://www.genengnews.com/topics/genome-editing/give-a-dog-a-bone-touchlights-cell-free-dna-vector-synthesis-ignites-genetic-medicine-manufacturing/', true, '$125m+ raised as of a 2021 funding round led by Bridford Investments and Novator Partners.', 'active', '2026-08-01', 10) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('6457034c-5c4f-456a-a94c-d010af57d8f6', 'engbio__breakthrough__basecamp-research-biodiversity-mapped-ai-protein-design', 'engbio', 'breakthrough', NULL, 'Basecamp Research — biodiversity-mapped AI protein design', 'Glen Gowers (co-founder); Basecamp Research', 'c. 2020–present', '2020-01-01', 'range', 'UK company building the "BaseGraph" biodiversity-to-protein-design platform, partnering with 23 countries across 3 continents for environmental sampling and sequencing under benefit-sharing agreements.', 'https://www.synbiobeta.com/read/harnessing-environmental-biodiversity-for-synthetic-biology', true, '$20m Series A. Illustrates the AI x engineering-biology convergence relevant to your planned AI/AI-safety sector build too.', 'active', '2026-08-01', 11) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('383e5f23-ccdf-4141-8840-2c9cdc74975d', 'engbio__evolving__department-name-changed-twice-within-days', 'engbio', 'evolving', NULL, 'Department name changed twice within days', NULL, 'Jul 2026', '2026-07-01', 'month', 'DSIT''s functions were redistributed into a business department initially referred to as "DBIST"; GOV.UK''s own Machinery of Government fact sheet was itself corrected on 27 Jul 2026, shortening the acronym to "BIST." This tool uses "DBIST"/the business department descriptively throughout — worth checking current usage before publishing further updates.', 'https://www.gov.uk/government/news/machinery-of-government-changes-fact-sheet', true, 'Terminology genuinely still in flux; affects every sector in this tool, not just engineering biology.', 'active', '2026-08-01', 0) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('1d4b201e-abc6-41c3-8c4c-2528728910ca', 'engbio__evolving__uk-eu-sanitary-and-phytosanitary-sps-agreement-negotiations', 'engbio', 'evolving', NULL, 'UK–EU Sanitary and Phytosanitary (SPS) Agreement negotiations', NULL, 'Ongoing, possibly to 2027', '2027-01-01', 'range', 'Could affect how far the Genetic Technology (Precision Breeding) Act is able to diverge from EU rules on gene-edited crops. Industry commentary (Jan 2026) suggested that the EU''s own "New Genomic Techniques" legislation reaching a late-2025 breakthrough may point toward eventual UK-EU regulatory convergence, but the SPS talks themselves remain unresolved and could run for another year or more.', NULL, false, 'Genuinely live regulatory question with no confirmed resolution date.', 'active', '2026-08-01', 1) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('bd25cfef-dcad-47aa-983b-da645c3386a5', 'engbio__evolving__engineering-biology-scale-up-infrastructure-access-fund-status-upgraded-since-fi', 'engbio', 'evolving', NULL, 'Engineering Biology Scale-up Infrastructure Access Fund — status upgraded since first draft', NULL, 'Calls opening through Sept 2026', '2026-01-01', 'range', 'Previously flagged in this tool as "not yet fully deployed." UKRI has since published a forward-looking timeline of funding calls (proof-of-concept awards, scale-up infrastructure, collaborative R&D, investor partnership programmes) running to the end of Sept 2026, following BIA members reporting a difficult funding-call slowdown in preceding months.', 'https://www.bioindustry.org/resource/upcoming-ukri-funding-opportunities-for-engineering-biology.html', true, 'Calls not yet fully opened at time of this research.', 'active', '2026-08-01', 2) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('50fccad5-0489-4e33-8247-005aa32da384', 'engbio__evolving__engineering-biology-value-chain-growth-fund-launched', 'engbio', 'evolving', NULL, 'Engineering Biology Value Chain Growth Fund launched', NULL, 'By Jun 2026', '2026-06-01', 'range', 'New fund supporting high-growth-potential companies building capability across the engineering biology value chain, confirmed in the Digital and Technologies Sector Plan: Year One Update — not captured in this tool''s original Domestic Initiatives research.', 'https://www.gov.uk/government/publications/digital-and-technologies-sector-plan-year-one-update/digital-and-technologies-sector-plan-year-one-update', true, 'New since original research; scope and eligibility not yet fully reviewed for this tool.', 'active', '2026-08-01', 3) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('badccb7b-a928-4ef7-a843-5276a9a2b8c4', 'engbio__evolving__national-engineering-biology-programme-figure-revised-198m-vs-196m', 'engbio', 'evolving', NULL, 'National Engineering Biology Programme figure revised: £198m vs £196m', NULL, 'Jun 2026 update', '2026-06-01', 'range', 'The Jun 2025 Digital and Technologies Sector Plan cited £196m for NEBP continuation; the Jun 2026 Year One Update cites £198m for the "launched" programme. Both are official government figures — likely a scope or rounding refinement rather than a substantive change, but not reconciled in this research.', 'https://www.gov.uk/government/publications/digital-and-technologies-sector-plan-year-one-update/digital-and-technologies-sector-plan-year-one-update', true, 'Minor figure discrepancy between two official sources, not reconciled.', 'active', '2026-08-01', 4) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('8be05e95-8929-46ff-ba92-69753aadc0d7', 'ai__timeline__council-for-science-and-technology-age-of-algorithms-letter', 'ai', 'timeline', NULL, 'Council for Science and Technology "Age of Algorithms" letter', NULL, '7 Jun 2013', '2013-06-07', 'day', 'Letter to the Prime Minister proposing a National Centre for algorithms and data science research — the direct origin of the Alan Turing Institute.', 'https://www.turing.ac.uk/about-us', true, NULL, 'active', '2026-08-01', 0) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('e6c562df-6fa4-497f-91ba-1c07c1d92fea', 'ai__timeline__alan-turing-institute-founded', 'ai', 'timeline', NULL, 'Alan Turing Institute founded', NULL, '2015', '2015-01-01', 'year', 'UK''s national institute for data science (AI added to remit 2017); founded by 5 universities (Cambridge, Edinburgh, Oxford, UCL, Warwick) plus EPSRC; headquartered at the British Library; expanded to 13 university partners by 2018, now 65+ via the Turing University Network.', 'https://www.turing.ac.uk/about-us', true, NULL, 'active', '2026-08-01', 1) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('f231f294-4ef5-4381-978f-16cd883dbabb', 'ai__timeline__ai-sector-deal', 'ai', 'timeline', NULL, 'AI Sector Deal', NULL, 'Apr 2018', '2018-04-01', 'month', '~£1bn package (£300m private) as part of the 2017 Industrial Strategy; funded Turing AI Fellowships, 1,000 government-backed AI PhDs by 2025, 8,000 specialist computer science teachers, doubled Tier 1 exceptional-talent visas. Also stood up the Government Office for AI and the AI Council.', 'https://hansard.parliament.uk/commons/2018-04-26/debates/32372DF8-9B87-47C1-BDC0-6DCFE420AA61/ArtificialIntelligenceSectorDeal', true, NULL, 'active', '2026-08-01', 2) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('998d2f86-cc13-4e32-a74b-51ef6572b775', 'ai__timeline__centre-for-data-ethics-and-innovation-cdei-launched', 'ai', 'timeline', NULL, 'Centre for Data Ethics and Innovation (CDEI) launched', NULL, 'Jun 2018', '2018-06-01', 'month', 'Government body to lead AI/data governance frameworks. See Institutions for its subsequent lineage.', 'https://www.gov.uk/government/organisations/centre-for-data-ethics-and-innovation', true, NULL, 'active', '2026-08-01', 3) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('dc33a214-b1e5-4d25-9e5c-733b1c2f4526', 'ai__timeline__ai-council-publishes-ai-roadmap', 'ai', 'timeline', NULL, 'AI Council publishes AI Roadmap', NULL, 'Mar 2021', '2021-03-01', 'month', '16 recommendations that directly shaped the National AI Strategy published six months later.', 'https://assets.publishing.service.gov.uk/media/614db4d1e90e077a2cbdf3c4/National_AI_Strategy_-_PDF_version.pdf', true, NULL, 'active', '2026-08-01', 4) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('40e45ed1-0640-4d5c-aa0d-e786d7d455a2', 'ai__timeline__national-ai-strategy-published', 'ai', 'timeline', NULL, 'National AI Strategy published', NULL, '22 Sep 2021', '2021-09-22', 'day', '10-year plan to make the UK an "AI superpower"; three pillars (long-term investment, economy-wide benefits, effective governance); notable for addressing compute capacity directly in a national strategy.', 'https://assets.publishing.service.gov.uk/media/614db4d1e90e077a2cbdf3c4/National_AI_Strategy_-_PDF_version.pdf', true, NULL, 'active', '2026-08-01', 5) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('a040bf77-6a12-4b36-90fb-131a23040fe5', 'ai__timeline__ai-white-paper-a-pro-innovation-approach-to-ai-regulation', 'ai', 'timeline', NULL, 'AI White Paper — "A pro-innovation approach to AI regulation"', NULL, '29 Mar 2023', '2023-03-29', 'day', '5 cross-cutting principles (safety/security/robustness, transparency, fairness, accountability, contestability) enforced by existing sectoral regulators rather than a new AI-specific regulator or new legislation — a deliberate divergence from the EU AI Act.', 'https://www.gov.uk/government/publications/ai-regulation-a-pro-innovation-approach/white-paper', true, NULL, 'active', '2026-08-01', 6) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('765a09ee-30ed-4c5d-bfc1-47ee2b444b43', 'ai__timeline__cdei-s-independent-advisory-board-quietly-disbanded', 'ai', 'timeline', NULL, 'CDEI''s independent advisory board quietly disbanded', NULL, 'Sep 2023', '2023-09-01', 'month', 'Board of 8 outside experts dissolved without formal announcement, weeks ahead of the Bletchley Summit.', 'https://www.gov.uk/government/organisations/centre-for-data-ethics-and-innovation', true, NULL, 'active', '2026-08-01', 7) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('f57cf158-fa7f-4a9d-bde4-4044f68d701e', 'ai__timeline__bletchley-park-ai-safety-summit-bletchley-declaration', 'ai', 'timeline', NULL, 'Bletchley Park AI Safety Summit; Bletchley Declaration', NULL, '1–2 Nov 2023', '2023-11-02', 'range', 'World''s first global AI safety summit. 28 countries plus EU sign the Bletchley Declaration (New Zealand joined later, Oct 2024, taking it to 29). Frontier AI Taskforce renamed AI Safety Institute. £300m AI Research Resource (AIRR) package announced, including £225m for what became Isambard-AI.', 'https://www.gov.uk/government/publications/ai-safety-summit-2023-the-bletchley-declaration/the-bletchley-declaration-by-countries-attending-the-ai-safety-summit-1-2-november-2023', true, NULL, 'active', '2026-08-01', 8) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('d813dcc3-e197-455a-8c17-f6cedc3fa025', 'ai__timeline__government-publishes-ai-white-paper-consultation-response-cdei-becomes-the-respo', 'ai', 'timeline', NULL, 'Government publishes AI White Paper consultation response; CDEI becomes the Responsible Technology Adoption Unit (RTA)', NULL, 'Feb 2024', '2024-02-01', 'month', 'Response "largely unchanged" from the original White Paper, confirming the non-statutory, regulator-led approach.', 'https://www.gov.uk/government/organisations/centre-for-data-ethics-and-innovation', true, NULL, 'active', '2026-08-01', 9) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('41ccb093-7d6c-4331-82d0-e9b2d87338ab', 'ai__timeline__ai-seoul-summit', 'ai', 'timeline', NULL, 'AI Seoul Summit', NULL, 'May 2024', '2024-05-01', 'month', 'International Network of AI Safety Institutes formed (UK, US, Japan, France, Germany, Italy, Singapore, South Korea, Australia, Canada, EU). Interim International AI Safety Report presented.', 'https://internationalaisafetyreport.org/about', true, NULL, 'active', '2026-08-01', 10) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('a27ede03-6493-4aa8-ad6b-793d2116d444', 'ai__timeline__ai-opportunities-action-plan-published', 'ai', 'timeline', NULL, 'AI Opportunities Action Plan published', NULL, '13 Jan 2025', '2025-01-13', 'day', 'Matt Clifford''s 50-recommendation plan, all accepted same day. Headline commitments: 20-fold increase in public compute by 2030, new AI Growth Zones, a National Data Library, an AI Energy Council, and a Sovereign AI capability unit. £14bn / 13,250 jobs in private commitments announced alongside it.', 'https://www.gov.uk/government/news/prime-minister-sets-out-blueprint-to-turbocharge-ai', true, NULL, 'active', '2026-08-01', 11) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('03262d8d-6430-478e-86f0-34835270eb22', 'ai__timeline__first-international-ai-safety-report-published', 'ai', 'timeline', NULL, 'First International AI Safety Report published', NULL, '29 Jan 2025', '2025-01-29', 'day', 'Led by Yoshua Bengio, ~100 experts, backed by 30 countries plus UN/OECD/EU; commissioned by the UK, secretariat hosted inside the UK AI Safety Institute. Presented at the Paris Summit two weeks later.', 'https://internationalaisafetyreport.org/about', true, NULL, 'active', '2026-08-01', 12) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('7251d0a9-d059-4c37-bc98-0644cbb9d2e7', 'ai__timeline__uk-signs-mou-with-anthropic-on-ai-opportunities', 'ai', 'timeline', NULL, 'UK signs MoU with Anthropic on AI opportunities', NULL, 'Feb 2025', '2025-02-01', 'month', 'First of four frontier-lab MoUs signed over the following six months (Anthropic Feb, Nvidia Jun, Cohere Jun, OpenAI Jul 2025) — see Initiatives (International).', 'https://www.gov.uk/government/publications/memorandum-of-understanding-between-the-uk-and-anthropic-on-ai-opportunities/memorandum-of-understanding-between-uk-and-anthropic-on-ai-opportunities', true, NULL, 'active', '2026-08-01', 13) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('2133061d-c676-4bd8-8bc1-cbfd26c7c24c', 'ai__timeline__rta-formerly-cdei-ceases-to-exist-as-a-standalone-unit', 'ai', 'timeline', NULL, 'RTA (formerly CDEI) ceases to exist as a standalone unit', NULL, 'Jan 2025', '2025-01-01', 'month', 'Functions folded into other DSIT teams including the Government Digital Service.', 'https://www.gov.uk/government/organisations/centre-for-data-ethics-and-innovation', true, NULL, 'active', '2026-08-01', 14) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('b7f631c4-20bb-461f-a3b4-ecbc23422998', 'ai__timeline__paris-ai-action-summit-uk-and-us-decline-to-sign-the-summit-declaration', 'ai', 'timeline', NULL, 'Paris AI Action Summit; UK and US decline to sign the summit declaration', NULL, '10–11 Feb 2025', '2025-02-11', 'range', '60+ countries (incl. France, China, India, EU) sign "Statement on Inclusive and Sustainable Artificial Intelligence"; UK cites the declaration not going far enough on national security and global governance. A marked shift from the UK''s Bletchley-era framing as the safety-first host.', 'https://internationalaisafetyreport.org/', true, NULL, 'active', '2026-08-01', 15) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('159dcdd7-6c8d-49aa-9855-dd730abc55cf', 'ai__timeline__uk-ai-safety-institute-renamed-ai-security-institute', 'ai', 'timeline', NULL, 'UK AI Safety Institute renamed AI Security Institute', NULL, 'Feb 2025', '2025-02-01', 'month', 'Explicit reframe from broad safety to national-security-focused evaluation; precedes the equivalent US rename of its AISI to CAISI in June 2025.', 'https://www.aisi.gov.uk/blog', true, NULL, 'active', '2026-08-01', 16) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('77b46270-f2cf-42a3-821b-1d90833b15b3', 'ai__timeline__manchester-prize-round-1-won-by-polaron', 'ai', 'timeline', NULL, 'Manchester Prize Round 1 won by Polaron', NULL, 'Mar 2025', '2025-03-01', 'month', '£1m grand prize (of a £2m+ Round 1 fund incl. 10 finalist grants of £100k each) for AI-accelerated advanced-materials design; announced 19 Mar 2025.', 'https://www.gov.uk/government/publications/manchester-prize', true, NULL, 'active', '2026-08-01', 17) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('6be6a961-de9c-474a-8c65-76138bc8c163', 'ai__timeline__first-ai-growth-zone-confirmed-culham-oxfordshire', 'ai', 'timeline', NULL, 'First AI Growth Zone confirmed: Culham, Oxfordshire', NULL, 'Apr 2025', '2025-04-01', 'month', 'UK Atomic Energy Authority site; pilot for fast-tracked planning and energy connection for AI data centres, beginning at 100MW scaling to 500MW.', 'https://www.gov.uk/government/publications/ai-opportunities-action-plan/ai-opportunities-action-plan', true, NULL, 'active', '2026-08-01', 18) ON CONFLICT (record_key) DO NOTHING;
