INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('20ba45e9-9e32-45d9-90b4-e47de9df18c6', 'ai__timeline__isambard-ai-officially-launched-bristol', 'ai', 'timeline', NULL, 'Isambard-AI officially launched, Bristol', NULL, '17 Jul 2025', '2025-07-17', 'day', 'UK''s most powerful supercomputer at launch (#11 on the June 2025 Top500 list, 216.5 PFLOPS), alongside Dawn at Cambridge — combined branded as "23 AI ExaFLOPs" for AI workloads, as part of the AIRR. £225m of the £300m Bletchley-era AIRR package.', 'https://www.bristol.ac.uk/research/centres/bristol-supercomputing/articles/2025/isambard-ai-launches-july-2025.html', true, NULL, 'active', '2026-08-01', 22) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('f6e778c4-cdfd-43d5-8dac-0d3f0f24ee87', 'ai__timeline__alan-turing-institute-governance-crisis-becomes-public', 'ai', 'timeline', NULL, 'Alan Turing Institute governance crisis becomes public', NULL, 'Aug 2025', '2025-08-01', 'month', 'Science Secretary Peter Kyle warns £100m annual funding could be withdrawn unless the Institute prioritises defence AI research; Charity Commission opens an assessment following a staff whistleblowing complaint. See Evolving Developments.', 'https://hansard.parliament.uk/Lords/2025-05-19/debates/C65CD4DB-8C3A-4477-B7DD-CFBDC7AD35AE/ScienceAndInnovationAlanTuringInstitute', true, 'Ongoing and unresolved as of this research — see the Evolving Developments tab.', 'active', '2026-08-01', 23) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('0414db9d-b375-4f4e-81af-77a54ed4006d', 'ai__timeline__microsoft-30bn-and-google-5bn-announce-combined-36bn-uk-ai-investment-north-east', 'ai', 'timeline', NULL, 'Microsoft ($30bn) and Google (£5bn) announce combined $36bn+ UK AI investment; North East AI Growth Zone confirmed', NULL, '16–17 Sep 2025', '2025-09-17', 'range', 'Coincides with the state visit that produced the US–UK Technology Prosperity Deal. North East zone (Blyth plus Cobalt Park, Newcastle) tied to OpenAI''s Stargate UK project.', 'https://www.ncl.ac.uk/business-and-partnerships/latest-news/item/north-east-ai-powerhouse/', true, NULL, 'active', '2026-08-01', 24) ON CONFLICT (record_key) DO NOTHING;
