INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('21f7ced9-a84f-4d87-ad09-6d96469daf1a', 'ai__timeline__sovereign-ai-unit-s-500m-investment-phase-launched', 'ai', 'timeline', NULL, 'Sovereign AI Unit''s £500m investment phase launched', NULL, '16 Apr 2026', '2026-04-16', 'day', 'Technology Secretary Liz Kendall''s launch speech at Wayve''s London HQ; the Unit itself had existed since Spring 2025. Chaired by James Wise. First equity investment: Callosum.', 'https://www.gov.uk/government/speeches/tech-secretary-launches-sovereign-ai', true, NULL, 'active', '2026-08-01', 32) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('f4f8c0f1-7a8c-43fb-89d7-d9f4c571f917', 'ai__timeline__ukri-review-reportedly-finds-alan-turing-institute-not-providing-value-for-money', 'ai', 'timeline', NULL, 'UKRI review reportedly finds Alan Turing Institute "not providing value for money"', NULL, 'Apr 2026', '2026-04-01', 'month', 'EPSRC core funding from FY2026/27 made conditional on governance/leadership reform. See Evolving Developments.', NULL, false, 'Unresolved as of this research — see the Evolving Developments tab.', 'active', '2026-08-01', 33) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('fe88dd4b-6142-4c71-9e24-6c352498ad9a', 'ai__timeline__dsit-abolished-kanishka-narayan-becomes-uk-s-first-cabinet-level-ai-minister', 'ai', 'timeline', NULL, 'DSIT abolished; Kanishka Narayan becomes UK''s first Cabinet-level AI Minister', NULL, '20–21 Jul 2026', '2026-07-21', 'range', 'AI strategy, public sector AI adoption, and the AI Security Institute move to the Cabinet Office (new AI Taskforce within the Office for the PM and Cabinet). General science/innovation policy moves to the renamed business department; digital transformation and online harms move to a renamed DCMS.', 'https://questions-statements.parliament.uk/written-statements/detail/2026-07-21/hlws298', true, 'Machinery-of-government change; the department''s own acronym changed again within a week — see Evolving Developments.', 'active', '2026-08-01', 34) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('3520ecb8-2d03-45ae-8c76-d1b92cc01949', 'ai__institution__cabinet-office-incl-new-ai-taskforce-within-opmc', 'ai', 'institution', NULL, 'Cabinet Office (incl. new AI Taskforce within OPMC)', NULL, NULL, NULL, NULL, 'Since Jul 2026: home of AI strategy, public sector AI adoption, and the AI Security Institute. New Office for the Prime Minister and Cabinet (OPMC) houses a dedicated AI Taskforce supported by a Prime Ministerial adviser on AI; also leads AI adoption across the Civil Service.', 'https://questions-statements.parliament.uk/written-statements/detail/2026-07-21/hlws298', true, NULL, 'active', '2026-08-01', 0) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('af274758-7498-4d1e-af1d-482eb6cadd46', 'ai__institution__dsit-dissolved-jul-2026', 'ai', 'institution', NULL, 'DSIT (dissolved Jul 2026)', NULL, NULL, NULL, NULL, 'Former Department for Science, Innovation and Technology; created 7 Feb 2023 specifically to give tech/AI a dedicated Cabinet-level home; carried the AI Opportunities Action Plan, the AI Security Institute, the Sovereign AI Fund, and the Incubator for AI before dissolution.', 'https://gov.uk/government/publications/dsit-accounting-officer-system-statement-2024/dsit-accounting-officer-system-statement-2024-html', true, 'Abolished Jul 2026.', 'dissolved', '2026-08-01', 1) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('6ddff768-e248-43a3-8c46-c4e352602e36', 'ai__institution__business-department-formerly-dbist', 'ai', 'institution', NULL, 'Business department (formerly DBIST)', NULL, NULL, NULL, NULL, 'Successor department holding general science, innovation and technology-adoption policy — the same department that leads quantum and engineering biology policy in this tool — but not the lead department for AI strategy specifically, which sits with the Cabinet Office. Its own acronym changed within days of formation — see Evolving Developments.', 'https://questions-statements.parliament.uk/written-statements/detail/2026-07-21/hlws298', true, 'Departmental name genuinely still in flux as of this research.', 'active', '2026-08-01', 2) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('0e1164ee-dd7d-44ae-a9ca-0a03de74bcf4', 'ai__institution__dcms-department-for-digital-culture-media-and-sport', 'ai', 'institution', NULL, 'DCMS (Department for Digital, Culture, Media and Sport)', NULL, NULL, NULL, NULL, 'Regained "Digital" in its name in the Jul 2026 reshuffle; took on digital foundations, digital transformation, digital inclusion and skills, information resilience, and online harms — relevant to AI insofar as online-safety regulation of AI-generated content sits here.', 'https://questions-statements.parliament.uk/written-statements/detail/2026-07-21/hlws298', true, NULL, 'active', '2026-08-01', 3) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('19e53331-102b-4fea-8cb8-6c4bf08b5957', 'ai__institution__alan-turing-institute', 'ai', 'institution', NULL, 'Alan Turing Institute', NULL, NULL, NULL, NULL, 'UK''s national institute for data science and AI, founded 2015. Currently in significant public governance turmoil — see Evolving Developments for the fuller, still-unresolved arc. Now pursuing a "Turing 2.0" strategy focused on 4 areas: health, environment, defence and security, and fundamental AI.', 'https://www.turing.ac.uk/about-us', true, 'Governance and funding situation unresolved as of this research.', 'active', '2026-08-01', 4) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('49ee9f1c-cf6d-48e6-966c-991f7f7c881b', 'ai__institution__ai-security-institute-aisi-formerly-ai-safety-institute', 'ai', 'institution', NULL, 'AI Security Institute (AISI, formerly AI Safety Institute)', NULL, NULL, NULL, NULL, 'Est. Nov 2023 as an evolution of the Frontier AI Taskforce; renamed Feb 2025. Describes itself as "the world''s largest and best-funded team dedicated to understanding advanced AI risks." Conducts frontier model evaluations using its open-source "Inspect" framework; grew to 30+ researchers within its first year, opened a San Francisco office, and runs the multi-funder Alignment Project. Moved to the Cabinet Office in the Jul 2026 reshuffle.', 'https://www.aisi.gov.uk/blog', true, NULL, 'active', '2026-08-01', 5) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('50a074a4-7450-49a9-a931-d0555f2a9114', 'ai__institution__ukri-epsrc', 'ai', 'institution', NULL, 'UKRI / EPSRC', NULL, NULL, NULL, NULL, 'Principal public research funder; funds the Alan Turing Institute''s core grant, AI Centres for Doctoral Training (16 CDTs under the 2018 Sector Deal), and co-delivers BridgeAI.', 'https://hansard.parliament.uk/commons/2018-04-26/debates/32372DF8-9B87-47C1-BDC0-6DCFE420AA61/ArtificialIntelligenceSectorDeal', true, NULL, 'active', '2026-08-01', 6) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('cbaa72c5-1fd3-4e93-9892-72401f83fec4', 'ai__institution__incubator-for-ai-i-ai', 'ai', 'institution', NULL, 'Incubator for AI (i.AI)', NULL, NULL, NULL, NULL, 'Cross-government AI delivery unit; moved from Cabinet Office into DSIT in the 2024 machinery-of-government change. Post-Jul-2026 departmental home not independently confirmed.', 'https://gov.uk/government/publications/dsit-accounting-officer-system-statement-2024/dsit-accounting-officer-system-statement-2024-html', true, 'Current departmental home unconfirmed.', 'active', '2026-08-01', 7) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('ae78868a-1c1e-439b-a69a-5464f735baa0', 'ai__institution__centre-for-data-ethics-and-innovation-cdei-responsible-technology-adoption-unit-', 'ai', 'institution', NULL, 'Centre for Data Ethics and Innovation (CDEI) → Responsible Technology Adoption Unit (RTA) → dissolved', NULL, NULL, NULL, NULL, 'Est. Jun 2018 with an independent advisory board; board quietly disbanded Sept 2023; renamed RTA Feb 2024; ceased to exist as a standalone unit Jan 2025, folded into other DSIT teams.', 'https://www.gov.uk/government/organisations/centre-for-data-ethics-and-innovation', true, NULL, 'dissolved', '2026-08-01', 8) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('c1b9f933-972e-4a14-905a-20b67f648ba8', 'ai__institution__ada-lovelace-institute', 'ai', 'institution', NULL, 'Ada Lovelace Institute', NULL, NULL, NULL, NULL, 'Independent research institute on AI/data ethics, est. 2018 with £5m Nuffield Foundation funding, explicitly positioned to complement (and outlast) CDEI. Still active and publicly vocal on AI governance.', 'https://www.adalovelaceinstitute.org/feature/aisi/', true, NULL, 'active', '2026-08-01', 9) ON CONFLICT (record_key) DO NOTHING;
