INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('6c5a3782-02cd-4191-a6ac-6c4369a36d8c', 'ai__institution__google-deepmind-london', 'ai', 'institution', NULL, 'Google DeepMind (London)', NULL, NULL, NULL, NULL, 'Founded as independent "DeepMind Technologies" in London, September 2010; acquired by Google in 2014 for a price widely reported at ~$500m; merged with Google Brain to form "Google DeepMind" in April 2023; remains headquartered in London. ~6,000 employees (2025); £1.33bn revenue (2024). The single most consequential UK-headquartered AI research institution by global impact.', 'https://deepmind.google/about/', true, NULL, 'active', '2026-08-01', 14) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('6871b9e3-dd7e-4d32-b40b-410f665530d8', 'ai__institution__isomorphic-labs', 'ai', 'institution', NULL, 'Isomorphic Labs', NULL, NULL, NULL, NULL, 'DeepMind spinout (2021), Hassabis-led, applying AlphaFold-derived technology to drug discovery.', 'https://www.isomorphiclabs.com/people/sir-demis-hassabis-phd', true, NULL, 'active', '2026-08-01', 15) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('f67c20c7-8887-4e7c-aff3-6f6472597828', 'ai__institution__wayve', 'ai', 'institution', NULL, 'Wayve', NULL, NULL, NULL, NULL, 'Autonomous-driving AI company, founded 21 Aug 2017 in Cambridge; headquartered in London; ~1,000 employees (2026). Licenses its "AI Driver" foundation model to automakers rather than operating its own fleet. Hosted the Apr 2026 Sovereign AI Unit launch.', 'https://en.wikipedia.org/wiki/Wayve', true, NULL, 'active', '2026-08-01', 16) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('209d0f4b-4d5d-4e52-ae82-3f641e57106e', 'ai__institution__ukai', 'ai', 'institution', NULL, 'UKAI', NULL, NULL, NULL, NULL, 'Trade body representing UK AI businesses; publicly welcomed the government''s decision not to sign the Feb 2025 Paris declaration.', NULL, false, NULL, 'active', '2026-08-01', 17) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('a496874b-cf00-4235-8db1-37a4bda2ee27', 'ai__institution__techuk', 'ai', 'institution', NULL, 'techUK', NULL, NULL, NULL, NULL, 'Broader tech trade association; ran member briefings on the AI Opportunities Action Plan; publicly criticised (jointly with the Startup Coalition) the Jul 2026 DSIT abolition.', 'https://www.techuk.org/what-we-deliver/events/ai-opportunities-action-plan-techuk-member-briefing.html', true, NULL, 'active', '2026-08-01', 18) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('28d19770-8827-46c4-8062-c4c3106d5107', 'ai__initiative__ai-sector-deal', 'ai', 'initiative', 'domestic', 'AI Sector Deal', NULL, 'Apr 2018', '2018-04-01', 'month', '~£1bn (£300m private); training, PhD places, Turing Fellowships.', 'https://hansard.parliament.uk/commons/2018-04-26/debates/32372DF8-9B87-47C1-BDC0-6DCFE420AA61/ArtificialIntelligenceSectorDeal', true, NULL, 'active', '2026-08-01', 0) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('d60fa4ec-0744-429e-a978-aeb9e38914d7', 'ai__initiative__turing-ai-fellowships', 'ai', 'initiative', 'domestic', 'Turing AI Fellowships', NULL, '2018', '2018-01-01', 'year', '£50m via the Alan Turing Institute plus Government Office for AI and UKRI, to attract senior international AI researchers to the UK.', 'https://www.turing.ac.uk/news/ps50-million-develop-world-leading-ai-talent-uk', true, NULL, 'active', '2026-08-01', 1) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('73e82807-9fcc-4f67-a6e6-feec3e4d5d01', 'ai__initiative__national-ai-strategy-implementation', 'ai', 'initiative', 'domestic', 'National AI Strategy implementation', NULL, 'Since Sep 2021', '2021-09-01', 'range', '10-year plan; committed to a future AI regulation White Paper, an AI assurance roadmap, and UKRI research-funding alignment — all of which materialised over the following 3 years.', 'https://assets.publishing.service.gov.uk/media/614db4d1e90e077a2cbdf3c4/National_AI_Strategy_-_PDF_version.pdf', true, NULL, 'active', '2026-08-01', 2) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('cfe851b2-3165-4570-83bc-7c48b553bf76', 'ai__initiative__ai-white-paper-feb-2024-government-response', 'ai', 'initiative', 'domestic', 'AI White Paper + Feb 2024 government response', NULL, 'Mar 2023 / Feb 2024', '2023-03-01', 'range', 'Pro-innovation, regulator-led approach; 5 cross-cutting principles; no new AI-specific regulator or primary legislation.', 'https://www.gov.uk/government/publications/ai-regulation-a-pro-innovation-approach/white-paper', true, NULL, 'active', '2026-08-01', 3) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('23143cb3-8f8d-4168-83cc-efbf0f7b4d38', 'ai__initiative__ai-safety-institute-funding', 'ai', 'initiative', 'domestic', 'AI Safety Institute funding', NULL, 'Nov 2023', '2023-11-01', 'month', '~£100m over 2 years at founding, evolving the Frontier AI Taskforce into a standing evaluation body (now AI Security Institute).', 'https://www.aisi.gov.uk/blog', true, NULL, 'active', '2026-08-01', 4) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('0a094305-a10a-4001-9b1c-c22cd800a21f', 'ai__initiative__ai-research-resource-airr', 'ai', 'initiative', 'domestic', 'AI Research Resource (AIRR)', NULL, 'From Nov 2023', '2023-11-01', 'range', '£300m announced at Bletchley (£225m of which built Isambard-AI, Bristol); Dawn (Cambridge) also operational. A separate £750m national supercomputer for Edinburgh (successor to ARCHER2) was confirmed 11 Jun 2025 — described by the University as working alongside AIRR rather than as an AIRR node.', 'https://www.bristol.ac.uk/research/centres/bristol-supercomputing/articles/2025/isambard-ai-launches-july-2025.html', true, NULL, 'active', '2026-08-01', 5) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('f37ca8c3-4a07-4bd8-9a8e-5fab6384084d', 'ai__initiative__manchester-prize', 'ai', 'initiative', 'domestic', 'Manchester Prize', NULL, 'Round 1: Dec 2023–Mar 2025; Round 2: Nov 2024–Jul 2026', '2023-12-01', 'range', 'DSIT challenge prize (delivered by Challenge Works), framed as a decade-long commitment. Round 1 (energy, environment, infrastructure): £1m grand prize plus 10 finalists at £100,000 each; won by Polaron (Imperial College London spinout, generative AI for advanced-materials design), announced 19 Mar 2025 — nearly 300 teams applied. Round 2 (net zero energy systems): £2m total fund; winner announced 8 Jul 2026.', 'https://www.gov.uk/government/publications/manchester-prize', true, NULL, 'active', '2026-08-01', 6) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('983e78a5-b5af-4fac-8006-d395bdefed90', 'ai__initiative__bridgeai', 'ai', 'initiative', 'domestic', 'BridgeAI', NULL, 'Jan/Apr 2023 – Jun 2026 (concluded)', '2023-04-01', 'range', '£100m Innovate UK programme to raise AI adoption in historically low-AI-maturity sectors (agriculture/food, construction, creative industries, transport/logistics); delivered with the Alan Turing Institute, Digital Catapult, STFC Hartree Centre, and BSI.', 'https://www.turing.ac.uk/partnering-turing/current-partnerships-and-collaborations/innovateukbridgeai', true, NULL, 'active', '2026-08-01', 7) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('a49fdac8-c5ef-4ea1-98d5-f52fbc147f45', 'ai__initiative__ai-opportunities-action-plan', 'ai', 'initiative', 'domestic', 'AI Opportunities Action Plan', NULL, 'Jan 2025', '2025-01-01', 'month', '50 recommendations, all accepted; 20x public compute by 2030; AI Growth Zones; National Data Library; AI Energy Council; Sovereign AI. £14bn / 13,250 jobs in accompanying private commitments. Progress against all 50 recommendations is tracked live on an official government site.', 'https://www.gov.uk/government/news/prime-minister-sets-out-blueprint-to-turbocharge-ai', true, NULL, 'active', '2026-08-01', 8) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('c66d6063-ee2c-4e1b-a734-1f7b18811cee', 'ai__initiative__ai-growth-zones', 'ai', 'initiative', 'domestic', 'AI Growth Zones', NULL, 'Rolling, Apr 2025 – Jan 2026', '2025-04-01', 'range', '5 zones designated to date: Culham (Oxfordshire, pilot), North East (Blyth/Cobalt Park, tied to OpenAI''s Stargate UK), North Wales, South Wales, North Lanarkshire (Scotland). Fast-tracked planning plus energy grid access for AI data centres. Collective private investment figures vary meaningfully by source — see Evolving Developments.', 'https://www.gov.uk/government/collections/ai-growth-zones', true, NULL, 'active', '2026-08-01', 9) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('0aa4c495-b69d-4916-8a62-622ee3e431ed', 'ai__initiative__national-data-library', 'ai', 'initiative', 'domestic', 'National Data Library', NULL, 'Announced Jan 2025', '2025-01-01', 'range', 'Central infrastructure for responsible management/sharing of public data to support AI development.', 'https://www.gov.uk/government/publications/ai-opportunities-action-plan/ai-opportunities-action-plan', true, NULL, 'active', '2026-08-01', 10) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('c8e1ba74-cb95-4f18-b82a-a720bb9aeb48', 'ai__initiative__ai-energy-council', 'ai', 'initiative', 'domestic', 'AI Energy Council', NULL, 'Announced Jan 2025', '2025-01-01', 'range', 'Chaired jointly by the Science and Energy Secretaries; coordinates with energy companies on data-centre power demand.', 'https://www.gov.uk/government/publications/ai-opportunities-action-plan/ai-opportunities-action-plan', true, NULL, 'active', '2026-08-01', 11) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('5b760dc5-9ac6-4828-8b06-1317fef4c083', 'ai__initiative__sovereign-ai-unit-fund', 'ai', 'initiative', 'domestic', 'Sovereign AI Unit / Fund', NULL, 'Unit est. Spring 2025; £500m phase launched 16 Apr 2026', '2026-04-16', 'range', '£500m ($675m) state-backed VC-style fund; equity investments up to £20m/startup; AIRR compute access; same-day visa decisions plus 10 free visas per backed startup. First equity investment: Callosum. Before the April 2026 launch, the Unit had already allocated sovereign compute to Cambridge''s MACE and Oxford''s EGGROLL research projects, provided £8m seed funding for the OpenBind drug-discovery data consortium, and scaled Pillar VC/ARIA''s Encode Fellowship.', 'https://www.gov.uk/government/speeches/tech-secretary-launches-sovereign-ai', true, NULL, 'active', '2026-08-01', 12) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('2e3e06db-30d9-419b-9cf5-769e1e32fc91', 'ai__initiative__80m-ai-procurement-de-risking-competition', 'ai', 'initiative', 'domestic', '£80m AI procurement de-risking competition', NULL, 'Apr 2026', '2026-04-01', 'month', 'Government acting as early customer for AI capability prototypes, drawing on the Sovereign AI Fund; contracts up to £5m/project, 12–24 months.', NULL, false, NULL, 'active', '2026-08-01', 13) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('5907f3af-f32a-46bd-8e9e-2820de94d87c', 'ai__initiative__global-partnership-on-ai-gpai', 'ai', 'initiative', 'international', 'Global Partnership on AI (GPAI)', NULL, 'Founding: 15 Jun 2020', '2020-06-15', 'range', 'UK is one of 15 founding members (with Australia, Canada, France, Germany, India, Italy, Japan, Mexico, New Zealand, South Korea, Singapore, Slovenia, the US, and the EU). 4 working groups: Responsible AI, Data Governance, Future of Work, Innovation & Commercialization. Merged into an integrated partnership with the OECD in Jul 2024; now 46 members plus EU.', 'https://www.gov.uk/government/publications/joint-statement-from-founding-members-of-the-global-partnership-on-artificial-intelligence/joint-statement-from-founding-members-of-the-global-partnership-on-artificial-intelligence', true, NULL, 'active', '2026-08-01', 14) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('5b0d14e1-f941-41ff-a5f8-75591c1fc77c', 'ai__initiative__bletchley-declaration', 'ai', 'initiative', 'international', 'Bletchley Declaration', NULL, '1–2 Nov 2023', '2023-11-02', 'range', '28 countries plus EU (29 after New Zealand, Oct 2024). Leading AI labs (OpenAI, Google DeepMind, Anthropic, Microsoft, Meta) agreed to pre-deployment government testing of frontier models.', 'https://www.gov.uk/government/publications/ai-safety-summit-2023-the-bletchley-declaration/the-bletchley-declaration-by-countries-attending-the-ai-safety-summit-1-2-november-2023', true, NULL, 'active', '2026-08-01', 15) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('4f71d256-1363-4dfb-aa1a-3fb039e76d73', 'ai__initiative__ai-seoul-summit-international-network-of-ai-safety-institutes', 'ai', 'initiative', 'international', 'AI Seoul Summit / International Network of AI Safety Institutes', NULL, 'May 2024', '2024-05-01', 'month', 'UK, US, Japan, France, Germany, Italy, Singapore, South Korea, Australia, Canada plus EU form a coordinating network of national AI safety institutes.', 'https://internationalaisafetyreport.org/about', true, NULL, 'active', '2026-08-01', 16) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('be720c8f-20af-418a-aa70-c0cfe922f14d', 'ai__initiative__international-ai-safety-report', 'ai', 'initiative', 'international', 'International AI Safety Report', NULL, 'Interim May 2024; annual reports Jan 2025 & Feb 2026; Key Updates Oct/Nov 2025', '2024-05-01', 'range', 'UK-commissioned, Bengio-chaired, 30+ countries plus UN/OECD/EU backing; secretariat hosted inside the UK AI Security Institute, with UK committed to hosting until a permanent international home is agreed.', 'https://internationalaisafetyreport.org/about', true, NULL, 'active', '2026-08-01', 17) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('8c00000b-4369-4870-90cc-bffdf0e891db', 'ai__initiative__paris-ai-action-summit', 'ai', 'initiative', 'international', 'Paris AI Action Summit', NULL, '10–11 Feb 2025', '2025-02-11', 'range', 'UK (and US) declined to sign the "Statement on Inclusive and Sustainable Artificial Intelligence," signed by 60+ countries. UK cited insufficient national-security and global-governance provisions.', 'https://internationalaisafetyreport.org/', true, NULL, 'active', '2026-08-01', 18) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('6d9db11d-3ce2-4712-9967-558926d3c1af', 'ai__initiative__frontier-ai-lab-mous-anthropic-nvidia-cohere-openai', 'ai', 'initiative', 'international', 'Frontier AI lab MoUs (Anthropic, Nvidia, Cohere, OpenAI)', NULL, 'Feb–Jul 2025', '2025-07-01', 'range', 'UK government signed sequential opportunity-focused MoUs: Anthropic (Feb 2025), Nvidia (Jun 2025, AI skills focus), Cohere (Jun 2025), OpenAI (Jul 2025). Strengthen shared commitments on responsible frontier-model development, UK AI workforce upskilling, and public-sector adoption pilots.', 'https://www.gov.uk/government/publications/memorandum-of-understanding-between-the-uk-and-anthropic-on-ai-opportunities/memorandum-of-understanding-between-uk-and-anthropic-on-ai-opportunities', true, NULL, 'active', '2026-08-01', 19) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('3880ddad-eef4-4097-bbca-336041fcae63', 'ai__initiative__us-uk-technology-prosperity-deal-ai-strand', 'ai', 'initiative', 'international', 'US–UK Technology Prosperity Deal — AI strand', NULL, 'Signed 18 Sep 2025', '2025-09-18', 'range', 'Covers AI alongside quantum and nuclear; explicitly linked in UK government communications to AI Growth Zone investment.', 'https://www.ncl.ac.uk/business-and-partnerships/latest-news/item/north-east-ai-powerhouse/', true, 'Broader deal''s pause/restart status not independently re-checked for the AI strand specifically — see Evolving Developments.', 'paused', '2026-08-01', 20) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('a7ac1968-9a54-4b6f-8aaa-58d9fc727d93', 'ai__initiative__the-alignment-project', 'ai', 'initiative', 'international', 'The Alignment Project', NULL, 'Ongoing (AISI-hosted)', NULL, NULL, 'International, multi-funder AI alignment research programme hosted by the UK AI Security Institute, alongside Canada''s AI Safety Institute, Australia''s AI Safety Institute, CIFAR, UKRI, ARIA, and industry/philanthropic funders including OpenAI, Microsoft, AWS, Anthropic, and Schmidt Sciences.', 'https://alignmentproject.aisi.gov.uk/about', true, NULL, 'active', '2026-08-01', 21) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('bb7adb88-e0a4-4d93-a89d-cd5e6ded58b7', 'ai__initiative__india-ai-impact-summit', 'ai', 'initiative', 'international', 'India AI Impact Summit', NULL, '2026', '2026-01-01', 'year', 'Next summit in the Bletchley→Seoul→Paris→India series; the second annual International AI Safety Report was published Feb 2026 specifically to be showcased there.', 'https://internationalaisafetyreport.org/publication/international-ai-safety-report-2026', true, NULL, 'active', '2026-08-01', 22) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('d10bab3e-58cf-4e84-8767-14df439cca74', 'ai__breakthrough__deepmind-founded-london', 'ai', 'breakthrough', NULL, 'DeepMind founded, London', 'Demis Hassabis, Shane Legg, Mustafa Suleyman', 'Sep 2010', '2010-09-01', 'month', 'Founded with the stated mission to "solve intelligence." Acquired by Google in 2014 for a price widely reported at ~$500m — one of the largest AI acquisitions at the time. Became "Google DeepMind" after merging with Google Brain in April 2023; remains headquartered in London.', 'https://deepmind.google/about/', true, NULL, 'active', '2026-08-01', 0) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('9b2b22b0-35cd-4dc0-8019-ea431c0ca152', 'ai__breakthrough__alphago-defeats-lee-sedol', 'ai', 'breakthrough', NULL, 'AlphaGo defeats Lee Sedol', 'Demis Hassabis; David Silver; Google DeepMind', 'Mar 2016', '2016-03-01', 'month', 'DeepMind''s AlphaGo beats the world Go champion — a landmark demonstration of deep reinforcement learning and the moment DeepMind''s work entered global public consciousness.', 'https://deepmind.google/about/', true, NULL, 'active', '2026-08-01', 1) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('9d811dbf-92c4-45e8-b320-3cbd665f3c7f', 'ai__breakthrough__alphafold2-solves-the-50-year-protein-folding-problem', 'ai', 'breakthrough', NULL, 'AlphaFold2 solves the 50-year protein-folding problem', 'Demis Hassabis; John Jumper; Google DeepMind', '2020', '2020-01-01', 'year', 'Presented at CASP14, reaching ~90% accuracy versus the ~40% ceiling of prior methods; open-sourced with 350,000+ protein structure predictions including the full human proteome (Jul 2021).', 'https://assets.publishing.service.gov.uk/media/614db4d1e90e077a2cbdf3c4/National_AI_Strategy_-_PDF_version.pdf', true, NULL, 'active', '2026-08-01', 2) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('a116cde2-aada-475d-90f9-1a899e3c610e', 'ai__breakthrough__isomorphic-labs-spun-out-from-deepmind', 'ai', 'breakthrough', NULL, 'Isomorphic Labs spun out from DeepMind', 'Demis Hassabis', '2021', '2021-01-01', 'year', 'Hassabis-led drug discovery company applying AlphaFold-derived technology to therapeutics.', 'https://www.isomorphiclabs.com/people/sir-demis-hassabis-phd', true, NULL, 'active', '2026-08-01', 3) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('2cb3f828-77ae-496a-8a8d-87b93526bfc9', 'ai__breakthrough__hassabis-and-jumper-awarded-the-nobel-prize-in-chemistry', 'ai', 'breakthrough', NULL, 'Hassabis and Jumper awarded the Nobel Prize in Chemistry', 'Demis Hassabis; John Jumper; (shared with David Baker, Univ. of Washington)', 'Oct 2024', '2024-10-01', 'month', 'For AlphaFold''s contribution to protein structure prediction. Hassabis was knighted the same year.', 'https://deepmind.google/blog/demis-hassabis-john-jumper-awarded-nobel-prize-in-chemistry/', true, 'David Baker''s share of the prize was for separate work at the University of Washington, not DeepMind-affiliated.', 'active', '2026-08-01', 4) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('833443f7-e1a9-4dd3-9af1-5300b7d4b53f', 'ai__breakthrough__wayve-end-to-end-learned-autonomous-driving', 'ai', 'breakthrough', NULL, 'Wayve — end-to-end learned autonomous driving', 'Alex Kendall; Amar Shah', '21 Aug 2017 (founded); 2024–2026 (scale-up)', '2017-08-21', 'range', 'Founded in Cambridge by Cambridge machine-learning PhD students. Licenses its "AI Driver" foundation model to automakers rather than operating its own fleet, without reliance on HD maps. $1.05bn SoftBank-led Series C (2024) — reported as the largest AI fundraise in European history at the time; $1.2bn Series D (May 2025) took the valuation to $8.6bn.', 'https://technologymagazine.com/news/ai-model-in-70-countries-drives-wayve-to-us-8-6bn-valuation', true, NULL, 'active', '2026-08-01', 5) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('91f33929-961b-4c89-8aa4-526e4e1d87f2', 'ai__breakthrough__synthesia-enterprise-ai-video-generation', 'ai', 'breakthrough', NULL, 'Synthesia — enterprise AI video generation', 'Victor Riparbelli; Steffen Tjerrild; Lourdes Agapito; Matthias Niessner', '2017 (founded); 2025–2026 (scale-up)', '2017-01-01', 'range', 'Founded by researchers from UCL, Stanford, Cambridge and TU Munich. AI-avatar video generation in 140+ languages, $100m+ ARR (Apr 2025). Series D closed and announced 15 Jan 2025 ($180m, $2.1bn valuation); Series E closed ~29–30 Oct 2025 but not announced until 26 Jan 2026 ($200m, $4bn valuation).', 'https://www.synthesia.io/post/series-e-200-million-4-billion-valuation-future-work', true, NULL, 'active', '2026-08-01', 6) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('1d51bd27-bff4-402f-9f13-8d0d2331c142', 'ai__breakthrough__stability-ai-open-source-generative-media-london', 'ai', 'breakthrough', NULL, 'Stability AI — open-source generative media, London', NULL, '2019 (founded)', '2019-01-01', 'range', 'Best known for Stable Diffusion; also develops text-to-video/audio/3D models. Has faced ongoing litigation from Getty Images over training-data use — a live, unresolved legal question relevant to any UK AI-and-copyright discussion.', NULL, false, 'Getty Images litigation ongoing and unresolved.', 'active', '2026-08-01', 7) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('8d4818eb-8659-4b60-885a-0080b774a140', 'ai__breakthrough__darktrace-ai-native-cybersecurity-cambridge', 'ai', 'breakthrough', NULL, 'Darktrace — AI-native cybersecurity, Cambridge', NULL, '2013 (founded); 2024 (exit)', '2013-01-01', 'range', 'Acquired by Thoma Bravo for $5.3bn in 2024 — reported as the largest AI exit in UK history. Directly relevant to a future Cybersecurity sector build.', NULL, false, NULL, 'active', '2026-08-01', 8) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('2ac935e0-4e70-4e59-8c6a-3cd47cb763e3', 'ai__breakthrough__graphcore-ai-accelerator-chips-bristol-london', 'ai', 'breakthrough', NULL, 'Graphcore — AI accelerator chips, Bristol/London', NULL, '2016 (founded); 2024 (acquisition)', '2016-01-01', 'range', 'Raised over half a billion pounds across 8 rounds before being acquired by SoftBank for £462m — well below its earlier private funding peak. Directly relevant to a future Semiconductors sector build.', NULL, false, NULL, 'active', '2026-08-01', 9) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('e85d7137-414b-4732-80c2-e5b9a0b40eef', 'ai__evolving__alan-turing-institute-governance-crisis', 'ai', 'evolving', NULL, 'Alan Turing Institute governance crisis', NULL, 'Aug 2025 – ongoing', '2025-08-01', 'range', 'Science Secretary''s Aug 2025 funding threat over defence-AI prioritisation led to a Charity Commission whistleblowing assessment, senior departures, and by Apr 2026 a UKRI review reportedly finding the Institute "not providing value for money," with FY2026/27 funding made conditional on governance reform. Leadership itself is in transition. None of this reads as resolved as of this research.', 'https://hansard.parliament.uk/Lords/2025-05-19/debates/C65CD4DB-8C3A-4477-B7DD-CFBDC7AD35AE/ScienceAndInnovationAlanTuringInstitute', true, 'Worth re-checking before treating any part of this as settled.', 'active', '2026-08-01', 0) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('8bb362cc-d96f-4977-be1f-4032b609ce2a', 'ai__evolving__department-name-changed-twice-within-days', 'ai', 'evolving', NULL, 'Department name changed twice within days', NULL, 'Jul 2026', '2026-07-01', 'month', 'DSIT''s functions were redistributed into a business department initially referred to as "DBIST"; GOV.UK''s own Machinery of Government fact sheet was itself corrected on 27 Jul 2026, shortening the acronym to "BIST." This tool uses "DBIST"/the business department descriptively throughout — worth checking current usage before publishing further updates.', 'https://www.gov.uk/government/news/machinery-of-government-changes-fact-sheet', true, 'Terminology genuinely still in flux; affects every sector in this tool, not just AI.', 'active', '2026-08-01', 1) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('45a96d05-f6bf-4b74-b7ca-1ff5695925a0', 'ai__evolving__jul-2026-machinery-of-government-split-reception-still-contested', 'ai', 'evolving', NULL, 'Jul 2026 machinery-of-government split — reception still contested', NULL, 'Jul 2026 – ongoing', '2026-07-01', 'range', 'AI gaining a Cabinet seat was welcomed; splitting DSIT was not. techUK and the Startup Coalition wrote jointly to the PM calling it "the wrong change at the wrong time"; AISI''s chair and former government AI adviser Matt Clifford also criticised the move publicly. How the new Cabinet Office AI Taskforce, the business department, and DCMS divide AI-adjacent work in practice remains to be seen.', 'https://www.resultsense.com/news/2026-07-21-narayan-cabinet-ai-minister-dsit-axed/', true, NULL, 'active', '2026-08-01', 2) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('6c89e2c1-e0ac-4d0a-95a9-39b3e669c0c7', 'ai__evolving__ai-growth-zone-investment-totals-vary-by-source', 'ai', 'evolving', NULL, 'AI Growth Zone investment totals vary by source', NULL, 'Ongoing', NULL, NULL, 'Cumulative figures attributed to the 5 designated zones range from roughly £28bn confirmed to $100bn+ potential, depending on what is counted and when. Individual zone figures are more consistent than the running total.', 'https://www.gov.uk/government/collections/ai-growth-zones', true, NULL, 'active', '2026-08-01', 3) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('a13772a9-559a-4c12-856f-529fab2e52e1', 'ai__evolving__sovereign-ai-unit-early-days', 'ai', 'evolving', NULL, 'Sovereign AI Unit — early days', NULL, 'Since 16 Apr 2026', '2026-04-16', 'range', 'Only three weeks into its £500m investment phase as of this research; one confirmed equity investment (Callosum) and reportedly in discussion with ~30 further firms at launch. Too early to assess delivery against the Unit''s stated ambitions.', 'https://www.gov.uk/government/speeches/tech-secretary-launches-sovereign-ai', true, NULL, 'active', '2026-08-01', 4) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('5a7501c7-324a-465e-928e-0e44c9852211', 'ai__evolving__manchester-prize-round-2-winner-not-yet-confirmed-by-name-here', 'ai', 'evolving', NULL, 'Manchester Prize Round 2 winner not yet confirmed by name here', NULL, 'Announced 8 Jul 2026', '2026-07-08', 'range', 'GOV.UK confirms a winner was announced, but the specific team/technology was not independently confirmed in this research pass — check the GOV.UK link directly for the current name.', 'https://www.gov.uk/government/publications/manchester-prize', true, NULL, 'active', '2026-08-01', 5) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('54a796bb-1cb2-4992-a5cd-7aeaab783f7b', 'semiconductors__timeline__national-security-and-investment-act-2021-comes-into-force', 'semiconductors', 'timeline', NULL, 'National Security and Investment Act 2021 comes into force', NULL, '4 Jan 2022', '2022-01-04', 'day', 'Introduces mandatory notification/pre-closing clearance for acquisitions in 17 sensitive sectors including "computing hardware" and "advanced materials" — the legal basis for the Newport Wafer Fab intervention that follows.', 'https://www.cooley.com/news/insight/2023/2023-06-06-uk-government-publishes-national-semiconductor-strategy', true, NULL, 'active', '2026-08-01', 0) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('9757bb42-2f8e-42c4-ae83-a6e3ebd53bd8', 'semiconductors__timeline__newport-wafer-fab-acquisition-called-in-for-national-security-assessment', 'semiconductors', 'timeline', NULL, 'Newport Wafer Fab acquisition called in for national security assessment', NULL, '25 May 2022', '2022-05-25', 'day', 'Nexperia''s acquisition called in by the then Secretary of State for BEIS under the NSI Act 2021, despite two earlier reviews (BEIS and the National Security Adviser) having found no substantive concern.', 'https://www.mofo.com/resources/insights/221129-reflections-on-the-uk-governments-decision', true, NULL, 'active', '2026-08-01', 1) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('c12de7c0-5fba-42f0-93c2-bb7f5d1c6e4f', 'semiconductors__timeline__final-order-nexperia-ordered-to-divest-86-of-newport-wafer-fab', 'semiconductors', 'timeline', NULL, 'Final Order: Nexperia ordered to divest 86% of Newport Wafer Fab', NULL, '16 Nov 2022', '2022-11-16', 'day', 'Kwasi Kwarteng issued a final order under s.26 of the NSI Act requiring divestment; Nexperia publicly rejected the national-security rationale. The most consequential single semiconductor-policy event in the UK to date.', 'https://assets.publishing.service.gov.uk/government/uploads/system/uploads/attachment_data/file/1118350/NWF_Final_Order_Public_Notice_16112022.pdf', true, NULL, 'active', '2026-08-01', 2) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('efeb846d-5b51-45f9-8e66-a637fe95f522', 'semiconductors__timeline__national-semiconductor-strategy-published', 'semiconductors', 'timeline', NULL, 'National Semiconductor Strategy published', NULL, '19 May 2023', '2023-05-19', 'day', '20-year vision (CP 838), presented to Parliament by then-DSIT Secretary of State Chloe Smith. Up to £200m committed 2023–25 and up to £1bn over the following decade; launches the UK Semiconductor Infrastructure Initiative and UKSAP.', 'https://assets.publishing.service.gov.uk/media/66599c1f0c8f88e868d3343c/national_semiconductor_strategy.pdf', true, NULL, 'active', '2026-08-01', 3) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('e91cd93e-1004-4701-a544-3e2024912998', 'semiconductors__timeline__modern-industrial-strategy-digital-and-technologies-sector-plan-published', 'semiconductors', 'timeline', NULL, 'Modern Industrial Strategy / Digital and Technologies Sector Plan published', NULL, '23 Jun 2025', '2025-06-23', 'day', 'Joint DBT/DSIT document; for semiconductors specifically it announces a new UK Semiconductor Centre, two new Innovation and Knowledge Centres, a Chip Design Enablement Programme, and a skills programme — see Initiatives for the itemised breakdown.', 'https://assets.publishing.service.gov.uk/media/685862e5b328f1ba50f3cea4/industrial_strategy_digital_and_technologies_sector_plan.pdf', true, NULL, 'active', '2026-08-01', 4) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('798c3dae-135e-404c-a700-a340e22e65da', 'semiconductors__timeline__uk-ai-hardware-plan-published', 'semiconductors', 'timeline', NULL, 'UK AI Hardware Plan published', NULL, '8 Jun 2026', '2026-06-08', 'day', '£1.1bn package announced by Technology Secretary Liz Kendall at London Tech Week: a new national AI supercomputer, uplifted semiconductor skills funding, and a new deeptech hardware venture strand — see Initiatives for the itemised breakdown. Explicitly positions UK chip companies'' "lab to market" gap as the core problem to solve.', 'https://www.gov.uk/government/publications/uk-ai-hardware-plan/uk-ai-hardware-plan', true, NULL, 'active', '2026-08-01', 5) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('ed5c7179-6902-4824-9593-9d80fc6bd21c', 'semiconductors__timeline__dsit-abolished-semiconductor-policy-moves-to-renamed-business-department', 'semiconductors', 'timeline', NULL, 'DSIT abolished; semiconductor policy moves to renamed business department', NULL, '20–27 Jul 2026', '2026-07-27', 'range', 'Machinery-of-government reshuffle under new PM Andy Burnham: DSIT dissolved (20–21 Jul); general science/business/innovation policy moves to the Department for Business, Innovation, Science and Trade, re-acronymed DBIST→BIST on 27 Jul. The Investment Security Unit also moves to BIST. AI strategy moves instead to a new Cabinet Office AI Taskforce. Exactly how this splits semiconductor/AI-hardware policy ownership is still unclear — see Evolving.', 'https://questions-statements.parliament.uk/written-statements/detail/2026-07-21/hlws298', true, 'Machinery-of-government change; continuity of semiconductor-specific policy leadership still to be confirmed.', 'active', '2026-08-01', 6) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('658a769b-dd07-41d7-b5e1-5b44db1fe5fa', 'semiconductors__institution__uk-semiconductor-centre-uksc', 'semiconductors', 'institution', NULL, 'UK Semiconductor Centre (UKSC)', NULL, NULL, NULL, NULL, 'Industry-led national hub announced in the June 2025 Digital and Technologies Sector Plan; £19m+ initial government backing plus a further £6.6m (Mar 2026); London HQ (Apr 2026); first CEO Andy McLean appointed May 2026; acts as a single gateway for international semiconductor collaboration and produces R&D/infrastructure roadmaps. Steering group co-chaired by Jonathan Flint CBE (CSA Catapult) and Dr Jalal Bagherli CBE.', 'https://www.uksemicentre.org.uk', false, 'Site referenced but not directly fetched during research.', 'active', '2026-08-01', 0) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('23676a5d-8d2d-44b0-b48a-da6f75d78650', 'semiconductors__institution__uk-semiconductor-advisory-panel-uksap', 'semiconductors', 'institution', NULL, 'UK Semiconductor Advisory Panel (UKSAP)', NULL, NULL, NULL, NULL, 'Established alongside the May 2023 National Semiconductor Strategy; jointly chaired by a government minister and Dr Jalal Bagherli CBE throughout; other long-standing members include Richard Grisenthwaite (Arm Chief Architect), Prof. John Goodenough (Sheffield), Janet Collyer MBE, Scott White (Pragmatic), Dr Andy Sellars (CORNERSTONE/Southampton), and Prof. Rachel Oliver OBE (Cambridge, co-founder of Porotech). Government co-chair has changed repeatedly: Paul Scully (2023) → Saqib Bhatti (2024) → Patrick Vallance (by Nov 2024) — successor after Vallance''s departure not confirmed as of this research.', 'https://www.gov.uk/government/publications/uk-semiconductor-advisory-panel-terms-of-reference/uk-semiconductor-advisory-panel-terms-of-reference', true, 'Government co-chair seat status unconfirmed since Patrick Vallance''s departure.', 'active', '2026-08-01', 1) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('2970adee-e99b-47e9-94ff-02f4f3b973eb', 'semiconductors__institution__compound-semiconductor-applications-catapult-csa-catapult-semiconductor-catapult', 'semiconductors', 'institution', NULL, 'Compound Semiconductor Applications Catapult (CSA Catapult) / Semiconductor Catapult', NULL, NULL, NULL, NULL, 'Founded 2018 by Innovate UK; part of the Innovate UK Catapult Network; HQ and Innovation Centre in Newport, South Wales (power electronics, RF/microwave and photonics labs), with a further site in Glasgow (power electronics design/packaging). Renamed "Semiconductor Catapult" from June 2026 as part of the AI Hardware Plan response, broadening its remit toward deployable AI hardware. CEO Caroline O''Brien.', 'https://csa.catapult.org.uk/', true, NULL, 'active', '2026-08-01', 2) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('2b7ea67b-5ee2-46fa-99df-35f31789c898', 'semiconductors__institution__institute-for-compound-semiconductors-ics-cardiff-university', 'semiconductors', 'institution', NULL, 'Institute for Compound Semiconductors (ICS), Cardiff University', NULL, NULL, NULL, NULL, 'Founded 2015 (10th anniversary marked April 2025); positions Cardiff as a European leader in compound semiconductor research; moved into a purpose-built cleanroom within the Translational Research Hub (200mm wafer processing capability) in 2023. Founding partner of CSconnected.', 'https://www.cardiff.ac.uk/institute-compound-semiconductors', true, NULL, 'active', '2026-08-01', 3) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('4de44a6b-4a99-46b3-b405-161d86b84962', 'semiconductors__institution__compound-semiconductor-centre-csc', 'semiconductors', 'institution', NULL, 'Compound Semiconductor Centre (CSC)', NULL, NULL, NULL, NULL, '£24m joint venture between IQE plc and Cardiff University for compound-semiconductor materials development and prototyping; core CSconnected partner alongside ICS.', 'https://www.csfusion.org/overview/', false, NULL, 'active', '2026-08-01', 4) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('b85fd590-af8c-43ca-b8a0-e84fa2b3452c', 'semiconductors__institution__centre-for-integrative-semiconductor-materials-cism-swansea-university', 'semiconductors', 'institution', NULL, 'Centre for Integrative Semiconductor Materials (CISM), Swansea University', NULL, NULL, NULL, NULL, 'Core CSconnected partner, complementing Cardiff''s device-fabrication focus.', 'https://compoundsemiconductorhub.org/landscape/', false, NULL, 'active', '2026-08-01', 5) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('47a14c12-8d93-4fd5-9139-afe324ef50b3', 'semiconductors__institution__csconnected', 'semiconductors', 'institution', NULL, 'CSconnected', NULL, NULL, NULL, NULL, 'Formal gateway/consortium for the South Wales compound semiconductor cluster — described as the world''s first compound semiconductor cluster; brings together ICS, CSC, CSA Catapult and CISM with business partners including IQE plc, SPTS, Microchip and the Newport fab (now Vishay-owned).', 'https://csconnected.com/', true, NULL, 'active', '2026-08-01', 6) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('87eae924-4a6e-4b12-adff-3f11fa9d7cac', 'semiconductors__institution__zepler-institute-for-photonics-and-nanoelectronics-optoelectronics-research-cent', 'semiconductors', 'institution', NULL, 'Zepler Institute for Photonics and Nanoelectronics / Optoelectronics Research Centre (ORC), University of Southampton', NULL, NULL, NULL, NULL, 'Described as the UK''s (and possibly Europe''s) leading photonics and nanoelectronics research institute; over 200 researchers, 90+ labs. Hosts CORNERSTONE, an open-access, licence-free silicon photonics rapid-prototyping foundry serving telecoms, sensing, LiDAR and quantum applications. Silicon Photonics Research Group led by Prof. Graham Reed.', 'https://zepler.soton.ac.uk/', true, NULL, 'active', '2026-08-01', 7) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('651cf467-4390-45db-b8e5-54983e3a82a8', 'semiconductors__institution__centre-for-process-innovation-cpi-netpark-county-durham', 'semiconductors', 'institution', NULL, 'Centre for Process Innovation (CPI) / NETPark, County Durham', NULL, NULL, NULL, NULL, 'Part of the High Value Manufacturing Catapult; hosted Pragmatic Semiconductor''s first manufacturing facility from 2013 before Pragmatic scaled to its own Durham site.', 'https://en.wikipedia.org/wiki/Pragmatic_Semiconductor', false, NULL, 'active', '2026-08-01', 8) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('ed086b35-f146-40b8-a2e8-57847655fd1b', 'semiconductors__institution__national-graphene-institute-ngi-graphene-engineering-innovation-centre-geic-sir-', 'semiconductors', 'institution', NULL, 'National Graphene Institute (NGI) / Graphene Engineering Innovation Centre (GEIC) / Sir Henry Royce Institute, University of Manchester', NULL, NULL, NULL, NULL, 'NGI (£61m, opened 2015) is the UK''s national centre for graphene research; GEIC (£60m) focuses on taking graphene/2D-materials products to market; the Royce Institute (£235m) is the UK''s national materials-research institute. Together described by the University as forming "Graphene City."', 'https://www.manchester.ac.uk/about/news/introducing-the-geic/', true, NULL, 'active', '2026-08-01', 9) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('8e1479d2-fc98-4efc-a105-03a13b0474e9', 'semiconductors__institution__arm-holdings-plc', 'semiconductors', 'institution', NULL, 'Arm Holdings plc', NULL, NULL, NULL, NULL, 'Cambridge-headquartered CPU/GPU IP design company; licensing (not manufacturing) business model; majority-owned by SoftBank since 2016; IPO''d jointly on Nasdaq in September 2023. Chief Architect Richard Grisenthwaite sits on UKSAP. Over 325bn Arm-based chips shipped worldwide as of 2025 — the clearest example of the UK''s "design and IP, not fabrication" strategic positioning.', 'https://newsroom.arm.com/blog/arm-official-history', true, NULL, 'active', '2026-08-01', 10) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('9b9fa04d-5425-47b2-8de4-cc911ccc0ccd', 'semiconductors__institution__iqe-plc', 'semiconductors', 'institution', NULL, 'IQE plc', NULL, NULL, NULL, NULL, 'Cardiff-headquartered global supplier of compound semiconductor epiwafers, founded 1988; manufacturing in the UK, US and Taiwan; listed on AIM. A strategic review — expanded Sep 2025 to consider a sale of the whole Group — concluded 27 Apr 2026 without a sale: IQE instead secured an ~£81m fundraising led by a £45m strategic investment from MACOM Technology Solutions Inc. (a US semiconductor company and existing customer), completed 28 May 2026, with MACOM taking board representation and ~11.5% of voting rights. CEO Jutta Meier also sits on the UK Semiconductor Centre''s Interim Steering Group.', 'https://www.iqep.com/media/press-releases/2026/conclusion-of-strategic-review/', true, NULL, 'active', '2026-08-01', 11) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('a347a870-850a-4332-84e8-cd88ba53273e', 'semiconductors__institution__innovation-and-knowledge-centres-ikcs-neuroware-ucl-and-chimes-sheffield', 'semiconductors', 'institution', NULL, 'Innovation and Knowledge Centres (IKCs) — Neuroware (UCL) and CHIMES (Sheffield)', NULL, NULL, NULL, NULL, 'Two new semiconductor IKCs launched under 2025 Sector Plan / 2026 AI Hardware Plan funding: Neuroware (UCL) in neuromorphic computing hardware, and CHIMES (Sheffield) in heterogeneous integration system design.', 'https://www.gov.uk/government/publications/digital-and-technologies-sector-plan-year-one-update/digital-and-technologies-sector-plan-year-one-update', true, NULL, 'active', '2026-08-01', 12) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('837f7209-95d1-4f2d-82a1-9c86634dc003', 'semiconductors__institution__semiconductor-industry-future-skills-centre-for-doctoral-training-swansea-univer', 'semiconductors', 'institution', NULL, 'Semiconductor Industry Future Skills Centre for Doctoral Training, Swansea University', NULL, NULL, NULL, NULL, 'Launched as part of the sector''s skills push; sits alongside a further £12m commitment to a Centre for Doctoral Training in Chip Design.', 'https://www.gov.uk/government/publications/digital-and-technologies-sector-plan-year-one-update/digital-and-technologies-sector-plan-year-one-update', true, NULL, 'active', '2026-08-01', 13) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('53d9c2b9-99f8-40aa-9b86-50edee66f3d8', 'semiconductors__institution__investment-security-unit', 'semiconductors', 'institution', NULL, 'Investment Security Unit', NULL, NULL, NULL, NULL, 'Administers NSI Act 2021 national-security screening — the mechanism used against Newport Wafer Fab, and currently pending for MACOM''s investment in IQE. Moved from its prior departmental structures to BIST as part of the July 2026 reshuffle.', 'https://www.hsfkramer.com/notes/corporate/2026-posts/company-law-and-ma-uk-government-department-dbt-renamed-dbist-and-assumes-wider-responsibilities', true, NULL, 'active', '2026-08-01', 14) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('f981361a-5590-44b5-9e44-7be8fe4b1ce6', 'semiconductors__institution__department-for-business-innovation-science-and-trade-bist-formerly-dbist', 'semiconductors', 'institution', NULL, 'Department for Business, Innovation, Science and Trade (BIST, formerly DBIST)', NULL, NULL, NULL, NULL, 'Post-reshuffle home for general science/business/innovation matters, including the Investment Security Unit; the same department now leading quantum and engineering biology policy in this tool. Acronym updated from DBIST to BIST on 27 Jul 2026. Whether AI-hardware-specific elements of semiconductor policy sit here or with the Cabinet Office AI Taskforce is unresolved — see Evolving.', 'https://questions-statements.parliament.uk/written-statements/detail/2026-07-21/hlws298', true, NULL, 'active', '2026-08-01', 15) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('990a3db5-448c-4fb0-8317-6d3c30f53b4c', 'semiconductors__initiative__national-semiconductor-strategy-2023', 'semiconductors', 'initiative', 'domestic', 'National Semiconductor Strategy (2023)', NULL, NULL, NULL, NULL, '20-year strategy; up to £200m 2023–25 and up to £1bn over the following decade; three goals (grow the domestic sector, mitigate supply-chain risk, protect national security); launched the UK Semiconductor Infrastructure Initiative and UKSAP.', 'https://assets.publishing.service.gov.uk/media/66599c1f0c8f88e868d3343c/national_semiconductor_strategy.pdf', true, NULL, 'active', '2026-08-01', 0) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('49e31305-e558-44f3-8be2-7544336d1375', 'semiconductors__initiative__uk-ai-hardware-plan-2026', 'semiconductors', 'initiative', 'domestic', 'UK AI Hardware Plan (2026)', NULL, NULL, NULL, NULL, '£1.1bn package: £750m new national AI supercomputer (£400m chip procurement incl. a £150m Advance Market Commitment for UK-designed inference chips), £48m semiconductor skills programme (uplifted from £35m), a new deeptech hardware venture funding strand, and the CSA→Semiconductor Catapult transition.', 'https://www.gov.uk/government/publications/uk-ai-hardware-plan/uk-ai-hardware-plan', true, NULL, 'active', '2026-08-01', 1) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('ecf6c06d-3f87-4f0a-9f8a-a03bbb6db7bb', 'semiconductors__initiative__uk-semiconductor-centre-funding', 'semiconductors', 'initiative', 'domestic', 'UK Semiconductor Centre funding', NULL, NULL, NULL, NULL, 'Up to £19m to establish (2025) plus a further £6.6m (Mar 2026) for 12 infrastructure projects spanning compound semiconductors, photonics and advanced packaging.', 'https://www.techuk.org/resource/uk-semiconductor-centre-announced-as-part-of-strong-support-for-semiconductors-in-the-industrial-strategy.html', true, NULL, 'active', '2026-08-01', 2) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('a7b87e60-8680-45b8-94af-7d94a264671d', 'semiconductors__initiative__chip-design-enablement-programme', 'semiconductors', 'initiative', 'domestic', 'Chip Design Enablement Programme', NULL, NULL, NULL, NULL, 'Up to £5m initial funding for state-of-the-art chip-design tools, talent support and technical expertise for startups/SMEs, particularly for AI and emerging architectures; piloted and delivered by the Science and Technology Facilities Council (STFC).', 'https://www.gov.uk/government/publications/digital-and-technologies-sector-plan-year-one-update/digital-and-technologies-sector-plan-year-one-update', true, NULL, 'active', '2026-08-01', 3) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('0ffa3981-20c4-4ef3-ac6f-f6e4bff27b50', 'semiconductors__initiative__semiconductor-skills-programme', 'semiconductors', 'initiative', 'domestic', 'Semiconductor skills programme', NULL, NULL, NULL, NULL, '£35m committed in the 2025 Sector Plan, increased to £48m via the 2026 AI Hardware Plan; associated with a reported 14% year-on-year rise in Electronic and Electrical Engineering enrolments (2024→2025), the largest in over five years.', 'https://www.gov.uk/government/publications/digital-and-technologies-sector-plan-year-one-update/digital-and-technologies-sector-plan-year-one-update', true, NULL, 'active', '2026-08-01', 4) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('fb8114fb-8b5c-416a-a0c0-e8df1ec05bdd', 'semiconductors__initiative__two-new-semiconductor-ikcs-neuroware-chimes', 'semiconductors', 'initiative', 'domestic', 'Two new semiconductor IKCs (Neuroware, CHIMES)', NULL, NULL, NULL, NULL, '£25m combined to launch Innovation and Knowledge Centres in neuromorphic computing hardware (UCL) and heterogeneous integration system design (Sheffield).', 'https://www.gov.uk/government/publications/digital-and-technologies-sector-plan-year-one-update/digital-and-technologies-sector-plan-year-one-update', true, NULL, 'active', '2026-08-01', 5) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('14368a9e-5037-45b4-835f-0a6c7db6b5e0', 'semiconductors__initiative__centre-for-doctoral-training-in-chip-design', 'semiconductors', 'initiative', 'domestic', 'Centre for Doctoral Training in Chip Design', NULL, NULL, NULL, NULL, 'Further £12m commitment, alongside the Swansea-led Semiconductor Industry Future Skills CDT.', 'https://www.gov.uk/government/publications/digital-and-technologies-sector-plan-year-one-update/digital-and-technologies-sector-plan-year-one-update', true, NULL, 'active', '2026-08-01', 6) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('a1854e57-a519-4376-b599-60fcb5b1c84c', 'semiconductors__initiative__uk-infrastructure-bank-national-wealth-fund-equity-in-pragmatic-semiconductor', 'semiconductors', 'initiative', 'domestic', 'UK Infrastructure Bank / National Wealth Fund equity in Pragmatic Semiconductor', NULL, NULL, NULL, NULL, '£60m direct equity investment (Dec 2023), part of a £162–182m Series D round, to build two further fabrication lines at Pragmatic Park, Durham — pitched explicitly as scaling the domestic semiconductor supply chain in North-East England.', 'https://www.nationalwealthfund.org.uk/news/bank-announces-ps60-million-direct-equity-investment-boost-uk-supply-chain-semiconductors', true, NULL, 'active', '2026-08-01', 7) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('c1578e9c-0d8d-441f-8004-8d83b7e15eee', 'semiconductors__initiative__south-wales-ai-growth-zone', 'semiconductors', 'initiative', 'domestic', 'South Wales AI Growth Zone', NULL, NULL, NULL, NULL, 'M4-corridor zone (Newport–Bridgend); up to £10bn private investment (Vantage Data Centers/Vanguard-led), 5,000+ projected jobs, up to £5m UK Government skills funding; directly overlaps the CSconnected compound semiconductor cluster.', 'https://www.gov.wales/welsh-government-welcomes-artificial-intelligence-growth-zone-south-wales', true, NULL, 'active', '2026-08-01', 8) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('79391202-7880-4428-83cd-d94e4f50031d', 'semiconductors__initiative__autumn-budget-2025-10m-for-south-wales-semiconductor-sector', 'semiconductors', 'initiative', 'domestic', 'Autumn Budget 2025 — £10m for South Wales semiconductor sector', NULL, NULL, NULL, NULL, 'Targeted at semiconductor technologies linked to AI and data centres, alongside the AI Growth Zone announcements.', 'https://www.gasworld.com/story/uk-budget-2025-10m-boost-for-wales-semiconductor-industry/2169145.article/', false, NULL, 'active', '2026-08-01', 9) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('cf60a053-3cca-4484-a148-7a048a8d9985', 'semiconductors__initiative__uk-japan-semiconductor-partnership', 'semiconductors', 'initiative', 'international', 'UK–Japan Semiconductor Partnership', NULL, '19 May 2023', '2023-05-19', 'day', 'Signed alongside the G7 Hiroshima summit (DSIT/METI); joint R&D in chip design, fabrication, advanced packaging and materials; an industry dialogue; skills exchanges; up to £2m in joint early-stage research (UKRI/JST). Sits within the wider "Hiroshima Accord" package announced the same visit.', 'https://www.meti.go.jp/english/press/2023/0519_002.html', true, NULL, 'active', '2026-08-01', 10) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('782a2204-d1ea-40e7-b827-ac02f43e747a', 'semiconductors__initiative__uk-japan-frontier-technology-partnership', 'semiconductors', 'initiative', 'international', 'UK–Japan Frontier Technology Partnership', NULL, 'Jan–Jun 2026', '2026-06-01', 'range', 'Announced following a Jan 2026 Starmer–Takaichi meeting; explicitly commits to "exploring formal pathways to interlock our AI semiconductor strengths," alongside 6G security/resilience work through the Global Coalition on Telecommunications.', 'https://www.gov.uk/government/news/uk-japan-frontier-technology-partnership', true, NULL, 'active', '2026-08-01', 11) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('b7464a3e-b48b-4e08-a3cf-1ca29d3d05f7', 'semiconductors__initiative__us-uk-technology-prosperity-deal', 'semiconductors', 'initiative', 'international', 'US–UK Technology Prosperity Deal', NULL, 'Signed 18 Sep 2025', '2025-09-18', 'range', '£31bn (~$42bn) of US corporate commitments across AI, quantum and nuclear; semiconductor-relevant elements include references to Arm chip designs within Nvidia''s Grace Blackwell architecture and broader AI-compute infrastructure commitments. Suspended 16 Dec 2025 amid wider US–UK trade disputes; reported "cautiously restarting" from Feb 2026.', 'https://bisi.org.uk/reports/us-uk-tech-prosperity-deal-implications-for-technology-cooperation', true, 'Whether the deal''s semiconductor-specific elements have resumed is unclear as of this research — see Evolving.', 'paused', '2026-08-01', 12) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('db0512f9-f0ee-4f48-8e0e-09a45e663563', 'semiconductors__initiative__amd-s-2bn-uk-investment', 'semiconductors', 'initiative', 'international', 'AMD''s £2bn UK investment', NULL, '8 Jun 2026', '2026-06-08', 'day', 'Announced at London Tech Week; chip supply and research partnerships for two AI supercomputers (Zenith with Dell/Cambridge; Sunrise with UKAEA/Cambridge for fusion research) plus a new Imperial College London computational-science collaboration.', 'https://ir.amd.com/news-events/press-releases/detail/1288/amd-commits-up-to-2-billion-to-accelerate-ai-innovation-and-research-in-the-united-kingdom', true, NULL, 'active', '2026-08-01', 13) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('efeabe53-6ac6-4c43-8fbd-a899fd961520', 'semiconductors__initiative__global-coalition-on-telecommunications-gcot', 'semiconductors', 'initiative', 'international', 'Global Coalition on Telecommunications (GCOT)', NULL, 'Founded Oct 2023', '2023-10-01', 'range', 'UK, US, Japan, Australia and Canada (Sweden joined Mar 2026; EU became a strategic partner May 2026); focused on telecoms security, 6G development and supply-chain resilience — adjacent to, though not squarely within, semiconductor policy proper.', 'https://en.wikipedia.org/wiki/Global_Coalition_on_Telecommunications', false, NULL, 'active', '2026-08-01', 14) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('5f14d00b-e474-4c30-8a42-b66112665fcb', 'semiconductors__initiative__csa-catapult-international-collaborations', 'semiconductors', 'initiative', 'international', 'CSA Catapult international collaborations', NULL, '2025–2026', '2025-01-01', 'range', 'Sarawak Microelectronics Design (SMD Semiconductor, a Sarawak state government entity) opened an edge-AI R&D hub co-located at CSA Catapult''s Newport Innovation Centre (2025), under a Wales–Sarawak collaboration; a separate UK–Canada collaboration on optical engines for AI data centres was announced in early 2026.', 'https://www.semiconductor-today.com/news_items/2025/may/csacatapult-smd-010525.shtml', true, NULL, 'active', '2026-08-01', 15) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('4a95df2f-6623-4195-8118-08da11ec0ed2', 'semiconductors__regulation__uk-strategic-export-control-lists', 'semiconductors', 'regulation', 'export', 'UK Strategic Export Control Lists', NULL, NULL, NULL, NULL, 'Administered by the Export Control Joint Unit (ECJU); UK exporters need a licence to export listed dual-use items. Post-Brexit, Great Britain runs an independent list (Northern Ireland remained aligned to EU dual-use law under the Windsor Framework). "High specification semiconductors, electronics, computers and telecommunications" is one of the list''s core categories.', 'https://globalinvestigationsreview.com/guide/the-guide-sanctions/sixth-edition/article/how-the-united-kingdom-approaches-export-controls', true, NULL, 'active', '2026-08-01', 0) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('bbc614b7-6de0-4533-8237-23f21d622f78', 'semiconductors__regulation__new-emerging-technology-control-entries-apr-2024', 'semiconductors', 'regulation', 'export', 'New emerging-technology control entries (Apr 2024)', NULL, 'Apr 2024', '2024-04-01', 'month', 'The UK, alongside like-minded partners, added three new entries to the Export Control Order 2008: PL9013 (semiconductor technologies, production equipment and materials), PL9014 (quantum computing technologies), PL9015 (additive manufacturing technologies).', 'https://www.akingump.com/en/insights/alerts/the-uk-continues-to-expand-its-controls-on-emerging-technologies', true, NULL, 'active', '2026-08-01', 1) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('d98e034e-c946-485a-88b2-6f15b3e44557', 'semiconductors__regulation__500-series-alignment-with-the-eu', 'semiconductors', 'regulation', 'export', '"500-series" alignment with the EU', NULL, 'In force 16 Dec 2025', '2025-12-16', 'range', 'The Export Control (Amendment) (No. 2) Regulations 2025 bring UK dual-use controls into closer alignment with the EU''s new "500-series" entries — covering semiconductor manufacturing equipment (ALD tools, epitaxial-deposition equipment, lithography equipment, EUV pellicles/masks/reticles, SEM equipment, etching equipment), advanced computing integrated circuits and other emerging technologies.', 'https://www.lexology.com/library/detail.aspx?g=5faa798d-da7e-4d8f-ac4a-b9b95998d492', true, NULL, 'active', '2026-08-01', 2) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('b8e2ad3b-19fb-4bf0-b395-bae4696b963c', 'semiconductors__regulation__wassenaar-arrangement-effectively-stalled', 'semiconductors', 'regulation', 'export', 'Wassenaar Arrangement effectively stalled', NULL, 'Since 2022', '2022-01-01', 'range', 'The main multilateral dual-use control forum has been unable to agree new listings since 2022 because of a Russian veto — a structural reason why the UK, EU and US have moved to unilateral/plurilateral "like-minded" controls instead of updating Wassenaar itself for technologies like advanced semiconductor tools.', 'https://www.globaltradeandsanctionslaw.com/new-eu-uk-export-controls-emerging-technologies/', true, NULL, 'active', '2026-08-01', 3) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('a40b5aef-e3f6-4d94-a320-f5d607950202', 'semiconductors__regulation__national-security-and-investment-act-2021', 'semiconductors', 'regulation', 'nsi', 'National Security and Investment Act 2021', NULL, 'In force 4 Jan 2022', '2022-01-04', 'range', 'Mandatory notification/pre-closing clearance for acquisitions across 17 sensitive sectors including "computing hardware" and "advanced materials." The core legal tool behind every semiconductor-ownership intervention below.', 'https://www.cooley.com/news/insight/2023/2023-06-06-uk-government-publishes-national-semiconductor-strategy', true, NULL, 'active', '2026-08-01', 4) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('fdd59061-8973-466b-ad08-b209fb364a91', 'semiconductors__regulation__newport-wafer-fab-call-in-and-divestment-order', 'semiconductors', 'regulation', 'nsi', 'Newport Wafer Fab: call-in and divestment order', NULL, '2022–2024', '2022-01-01', 'range', 'Nexperia''s acquisition called in 25 May 2022; final order requiring 86% divestment issued 16 Nov 2022 — the highest-profile NSI Act semiconductor case to date, and the trigger for the National Semiconductor Strategy''s national-security strand. Resolved by Vishay''s $177m acquisition, completed 5 Mar 2024.', 'https://assets.publishing.service.gov.uk/government/uploads/system/uploads/attachment_data/file/1118350/NWF_Final_Order_Public_Notice_16112022.pdf', true, NULL, 'active', '2026-08-01', 5) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('79bec9b7-2142-46c0-a2d3-e250a83b65d5', 'semiconductors__regulation__macom-s-investment-in-iqe-plc-pending-nsi-act-clearance', 'semiconductors', 'regulation', 'nsi', 'MACOM''s investment in IQE plc — pending NSI Act clearance', NULL, '2026', '2026-01-01', 'year', 'IQE''s £81m fundraising (concluded 27 Apr 2026, completed 28 May 2026) is conditional on clearance under the NSI Act 2021 and equivalent Italian foreign-investment legislation, given MACOM (a US company) will hold board representation and ~11.5% of voting rights. A live illustration of the same screening regime now applying to inbound US, not just Chinese, semiconductor investment.', 'https://www.iqep.com/media/press-releases/2026/conclusion-of-strategic-review/', true, NULL, 'active', '2026-08-01', 6) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('f6b60581-d725-407c-b5d0-9e0c3675d87f', 'semiconductors__regulation__investment-security-unit', 'semiconductors', 'regulation', 'nsi', 'Investment Security Unit', NULL, NULL, NULL, NULL, 'The body administering NSI Act screening; moved from its prior departmental home to BIST as part of the July 2026 reshuffle.', 'https://www.hsfkramer.com/notes/corporate/2026-posts/company-law-and-ma-uk-government-department-dbt-renamed-dbist-and-assumes-wider-responsibilities', true, NULL, 'active', '2026-08-01', 7) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('c7f1bb39-e0b0-479c-bae6-e8e51729ec7e', 'semiconductors__regulation__no-dedicated-semiconductor-specific-uk-standards-programme-identified', 'semiconductors', 'regulation', 'standards', 'No dedicated semiconductor-specific UK standards programme identified', NULL, NULL, NULL, NULL, 'Unlike the engineering biology tool''s NPL-related standards work, no comparable formal semiconductor standards-setting programme was identified during research. CSA/Semiconductor Catapult''s technical work (Double Pulse Testing methodology, JOINER network testbed participation) touches on de facto industry testing standards but isn''t a formal standards programme as such.', NULL, false, 'Flagged as a genuine research gap rather than filled with thin material.', 'active', '2026-08-01', 8) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('fab93acd-9521-4fb6-9f53-158114323087', 'semiconductors__regulation__product-security-and-telecommunications-infrastructure-act-2022-psti', 'semiconductors', 'regulation', 'ipsec', 'Product Security and Telecommunications Infrastructure Act 2022 (PSTI)', NULL, 'In force 29 Apr 2024', '2024-04-29', 'range', 'Mandates minimum cybersecurity requirements (no default passwords, vulnerability disclosure, etc.) for consumer connectable products, aligned to ETSI EN 303 645 and NCSC guidance. Semiconductors themselves aren''t directly in scope — obligations typically flow down from device manufacturers to their chip suppliers contractually rather than applying to chipmakers by law.', 'https://www.mofo.com/resources/insights/260121-cybersecurity-at-the-core-eu-and-uk-cybersecurity-rules', true, NULL, 'active', '2026-08-01', 9) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('f9b20233-4b00-4ae1-8fc3-ed139d38a7af', 'semiconductors__regulation__cyber-security-and-resilience-bill-in-progress', 'semiconductors', 'regulation', 'ipsec', 'Cyber Security and Resilience Bill (in progress)', NULL, NULL, NULL, NULL, 'Would extend UK cyber obligations to a wider range of "critical suppliers," with fines up to £17m or 4% of global turnover; a semiconductor manufacturer supplying UK critical national infrastructure (energy, telecoms, healthcare) could in principle be designated a critical supplier under it. Still a Bill, not yet in force.', 'https://www.mofo.com/resources/insights/260121-cybersecurity-at-the-core-eu-and-uk-cybersecurity-rules', false, 'Bill status/timing not independently confirmed during research.', 'active', '2026-08-01', 10) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('b7a8918f-8ee4-4336-a722-175268de0825', 'semiconductors__breakthrough__charles-kao-s-optical-fibre-proposal-standard-telecommunication-laboratories-har', 'semiconductors', 'breakthrough', NULL, 'Charles Kao''s optical-fibre proposal, Standard Telecommunication Laboratories, Harlow', 'Charles Kao; George Hockham — STL Harlow (STC/ITT)', '1966', '1966-01-01', 'year', 'Kao and Hockham showed that impurities, not fundamental physics, caused signal loss in glass fibres, and that sufficiently pure glass could carry light signals over 100km rather than 20m — the founding insight of fibre-optic communication. Kao was awarded half the 2009 Nobel Prize in Physics for this work.', 'https://www.nobelprize.org/prizes/physics/2009/kao/facts/', true, 'Photonics-adjacent rather than a semiconductor breakthrough in the strict sense — the 2009 Nobel Prize''s other half went to Boyle and Smith (Bell Labs, US) for inventing the CCD image sensor, a semiconductor device but not a UK one.', 'active', '2026-08-01', 0) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('1370d590-ef8d-4338-b86d-0e1c06c44407', 'semiconductors__breakthrough__graphene-isolated', 'semiconductors', 'breakthrough', NULL, 'Graphene isolated', 'Andre Geim; Konstantin Novoselov — University of Manchester', '2004', '2004-01-01', 'year', 'First isolation of a 2D crystalline material, using mechanical exfoliation (the "Scotch tape method"); foundational to the UK''s later strength in 2D-materials electronics (Paragraf) and to Manchester''s status as a global graphene research hub.', 'https://www.graphene.manchester.ac.uk/about/history/', true, NULL, 'active', '2026-08-01', 1) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('2f6682f8-388d-469d-b5e5-680a21f17b83', 'semiconductors__breakthrough__nobel-prize-in-physics-for-graphene', 'semiconductors', 'breakthrough', NULL, 'Nobel Prize in Physics for graphene', 'Geim; Novoselov', '2010', '2010-01-01', 'year', 'International recognition of the 2004 discovery, six years on — an unusually fast prize-to-discovery gap reflecting the work''s immediate significance.', 'https://www.nobelprize.org/prizes/physics/2010/summary/', true, NULL, 'active', '2026-08-01', 2) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('b68cdc4b-ed8f-4ad6-af93-af1a3f6b757c', 'semiconductors__breakthrough__arm-architecture-spun-out-as-an-independent-company', 'semiconductors', 'breakthrough', NULL, 'Arm architecture spun out as an independent company', 'Original Arm team (12 engineers, incl. Steve Furber, Sophie Wilson design lineage) — Cambridge', 'Nov 1990', '1990-11-01', 'month', 'Commercial/IP milestone rather than a single scientific result, but foundational: the ARM instruction-set architecture, refined from Acorn''s 1985 ARM1 design, became the basis for the dominant low-power CPU architecture in mobile and embedded computing worldwide.', 'https://newsroom.arm.com/blog/arm-official-history', true, NULL, 'active', '2026-08-01', 3) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('6e47c42e-82b0-45c9-9e24-00ee6763f7aa', 'semiconductors__breakthrough__world-s-first-graphene-electronics-foundry-online', 'semiconductors', 'breakthrough', NULL, 'World''s first graphene electronics foundry online', 'Paragraf (Dr Simon Thomas, CEO) — Cambridge', 'Dec 2024', '2024-12-01', 'month', 'Paragraf''s Cambridge facility began producing Graphene Hall Sensors and Graphene Field-Effect Transistors at commercially relevant volumes using standard semiconductor manufacturing processes — described as the first company to mass-produce graphene-based electronic devices this way.', 'https://www.deeptechleaders.com/lab-to-market-leadership-podcast/simon-thomas-paragraf-graphene-electronics-foundry', true, 'Company-affiliated source; no independent press release located during research.', 'active', '2026-08-01', 4) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('8cb5c15f-fac0-4fad-9638-9db9583bf3f4', 'semiconductors__breakthrough__world-s-first-all-silicon-optical-transmitter-at-100gbps', 'semiconductors', 'breakthrough', NULL, 'World''s first all-silicon optical transmitter at 100Gbps', 'Prof. Graham Reed; Dr Ke Li — Zepler Institute/ORC, University of Southampton', 'c. 2020', '2020-01-01', 'range', 'Integrated-photonics milestone treating photonics and electronics as a single integrated system on a chip — relevant to CSA/Semiconductor Catapult''s current photonics focus.', 'https://phys.org/news/2020-11-world-all-silicon-optical-transmitter-100gbps.html', true, 'Exact date not pinned down precisely during research (article dated Nov 2020, referencing an EPSRC-funded programme grant).', 'active', '2026-08-01', 5) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('72602d2c-75da-4876-a217-5f26489dc3b4', 'semiconductors__breakthrough__world-s-first-ai-driven-electron-beam-lithography-ebl-tool', 'semiconductors', 'breakthrough', NULL, 'World''s first AI-driven electron-beam lithography (EBL) tool', 'UK Semiconductor Centre-backed project', 'Mar 2026', '2026-03-01', 'month', 'Announced as one of 12 projects under the UK Semiconductor Centre''s £6.6m infrastructure investment; described as in development rather than completed.', 'https://www.semiconductor-today.com/news_items/2026/mar/uksemiconductorcentre-200326.shtml', true, '"World''s first" claim sourced only to trade press/UKSC material — not independently verified during research.', 'active', '2026-08-01', 6) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('0db01d47-3ba2-4bff-b796-25ab34595023', 'semiconductors__evolving__departmental-home-for-semiconductor-policy-post-reshuffle', 'semiconductors', 'evolving', NULL, 'Departmental home for semiconductor policy post-reshuffle', NULL, NULL, NULL, NULL, 'DSIT''s semiconductor policy team was still operating as such as of the 8 Jun 2026 AI Hardware Plan. DSIT was abolished 20–21 Jul 2026; general science/business/innovation policy (and the Investment Security Unit) moved to BIST, while AI strategy moved to a new Cabinet Office AI Taskforce. Given the AI Hardware Plan sits across both briefs, it''s unclear whether day-to-day semiconductor policy now sits wholly with BIST, is split with the Cabinet Office, or hasn''t been formally reassigned yet.', 'https://questions-statements.parliament.uk/written-statements/detail/2026-07-21/hlws298', true, NULL, 'active', '2026-08-01', 0) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('774debd9-8905-4ae2-a941-1ee33f8050f8', 'semiconductors__evolving__us-uk-technology-prosperity-deal-semiconductor-specific-status', 'semiconductors', 'evolving', NULL, 'US–UK Technology Prosperity Deal — semiconductor-specific status', NULL, 'Since Dec 2025', '2025-12-01', 'range', 'Signed 18 Sep 2025, suspended 16 Dec 2025, reported "cautiously restarting" from Feb 2026 — but restart reporting found during this research focuses specifically on civil nuclear and fusion, not semiconductors. Whether the deal''s semiconductor/AI-hardware elements have resumed, remain suspended, or were effectively superseded by the June 2026 AI Hardware Plan and the standalone AMD deal, is unclear.', 'https://www.aol.com/articles/us-uk-tech-deal-cautiously-121730348.html', true, NULL, 'active', '2026-08-01', 1) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('66498e5a-5d6b-4c89-ad9f-4370eb5263e8', 'semiconductors__evolving__horizon-europe-eu-chips-joint-undertaking-participation', 'semiconductors', 'evolving', NULL, 'Horizon Europe / EU Chips Joint Undertaking participation', NULL, NULL, NULL, NULL, 'The UK rejoined Horizon Europe as an associate member in 2024, but it''s unconfirmed whether that association extends to the EU Chips Joint Undertaking specifically, which has historically had a narrower participation model than the core Horizon Europe programme.', NULL, false, 'Not verified during this research pass.', 'active', '2026-08-01', 2) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('c1c5bbfd-aa0d-4d1c-b3b5-4012ddb0211b', 'cyber__timeline__uk-cyber-security-strategy-2011-2016-published', 'cyber', 'timeline', NULL, 'UK Cyber Security Strategy 2011–2016 published', NULL, '2011', '2011-01-01', 'year', 'Backed by an £860m National Cyber Security Programme; the UK''s first dedicated cross-government cyber crime response coordination and the direct precursor to Cyber Essentials.', 'https://assets.publishing.service.gov.uk/media/5a81bae5e5274a2e8ab558ca/UK_Cyber_Security_Strategy_Annual_Report_2016.pdf', true, NULL, 'active', '2026-08-01', 0) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('b1d549c1-377b-4203-acd4-fb4faa1002b4', 'cyber__timeline__national-cyber-security-strategy-2016-2021-published', 'cyber', 'timeline', NULL, 'National Cyber Security Strategy 2016–2021 published', NULL, 'Nov 2016', '2016-11-01', 'month', '£1.9bn five-year programme; established the “Defend, Deter, Develop” framework and directly funded the creation of the NCSC the same year.', 'https://en.wikipedia.org/wiki/National_Cyber_Security_Centre_(United_Kingdom)', true, NULL, 'active', '2026-08-01', 1) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('f7d05a04-d76a-4f0f-b507-12986bb8eebf', 'cyber__timeline__national-cyber-strategy-2022-published', 'cyber', 'timeline', NULL, 'National Cyber Strategy 2022 published', NULL, '15 Dec 2021', '2021-12-15', 'day', 'Successor strategy; five pillars (ecosystem, resilience, technology advantage, global leadership, countering threats), backed by the £2.6bn cyber settlement from the 2021 Spending Review. Gov.uk lists the publication date as 15 Dec 2021 despite the “2022” title.', 'https://www.gov.uk/government/publications/national-cyber-strategy-2022', true, NULL, 'active', '2026-08-01', 2) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('fb975b55-8a99-463c-97dd-3362773d3f0d', 'cyber__timeline__government-cyber-security-strategy-2022-2030-published', 'cyber', 'timeline', NULL, 'Government Cyber Security Strategy 2022–2030 published', NULL, '25 Jan 2022', '2022-01-25', 'day', 'Companion strategy focused on the government''s own estate rather than the wider economy: aims to harden core government functions against cyber attack by 2025 and make the whole public sector resilient by 2030, via a “Defend as One” model. Cabinet Office-owned at launch.', 'https://securityprofession.blog.gov.uk/gcss', true, NULL, 'active', '2026-08-01', 3) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('442ee34a-6795-48d3-bb63-8c0d3cc18b58', 'cyber__timeline__digital-and-cyber-security-policy-moves-from-dcms-to-newly-formed-dsit', 'cyber', 'timeline', NULL, 'Digital and cyber security policy moves from DCMS to newly formed DSIT', NULL, '7 Feb 2023', '2023-02-07', 'day', 'Machinery-of-government change creating the Department for Science, Innovation and Technology, bringing quantum, AI, engineering biology, semiconductors, future telecoms and cyber under one department for the first time.', 'https://www.gov.uk/government/publications/dsit-cyber-security-newsletter-february-2023/dsit-cyber-security-newsletter-february-2023', true, NULL, 'active', '2026-08-01', 4) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('05a63012-7b40-4f8c-83b6-c1b7410ffb17', 'cyber__timeline__cyber-security-and-resilience-bill-announced-king-s-speech', 'cyber', 'timeline', NULL, 'Cyber Security and Resilience Bill announced (King''s Speech)', NULL, '17 Jul 2024', '2024-07-17', 'day', 'New Labour government commits to legislate to update the 2018 NIS Regulations regime (see Regulation).', 'https://en.wikipedia.org/wiki/Cyber_Security_and_Resilience_Bill', true, NULL, 'active', '2026-08-01', 5) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('66a332b3-2e43-4873-a319-d9d90fb9c59f', 'cyber__timeline__responsibility-for-government-public-sector-cyber-security-moves-from-cabinet-of', 'cyber', 'timeline', NULL, 'Responsibility for government/public-sector cyber security moves from Cabinet Office to DSIT', NULL, '3 Jun 2025', '2025-06-03', 'day', 'PM Keir Starmer''s written statement to the Commons transferred this into DSIT''s Government Digital Service (GDS), aiming to integrate cyber expertise with the rest of the “digital centre of government.” Followed a March 2024 National Audit Office finding of fragmented cyber accountability across government.', 'https://www.gov.uk/government/publications/dsit-accounting-officer-system-statement-2026/dsit-accounting-officer-system-statement-2026', true, NULL, 'active', '2026-08-01', 6) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('0284d646-cb5c-4b7d-920a-ead4933b576f', 'cyber__timeline__government-confirms-targeted-ransomware-payment-ban-for-public-sector-cni', 'cyber', 'timeline', NULL, 'Government confirms targeted ransomware payment ban for public sector/CNI', NULL, '22 Jul 2025', '2025-07-22', 'day', 'Response to the Jan 2025 Home Office consultation; confirms a ban on ransomware payments by public bodies and critical national infrastructure operators, a “payment prevention” notification regime for other organisations, and a new mandatory incident-reporting requirement.', 'https://www.burges-salmon.com/articles/102kyhv/uk-government-moves-to-ban-ransomware-payments-for-public-sector/', true, 'Legislative vehicle and commencement date not yet finalised — see Evolving.', 'active', '2026-08-01', 7) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('46c16442-32dc-4b9a-8cf8-c88b29594f3c', 'cyber__timeline__cyber-security-and-resilience-nis-bill-introduced-to-parliament', 'cyber', 'timeline', NULL, 'Cyber Security and Resilience (NIS) Bill introduced to Parliament', NULL, '12 Nov 2025', '2025-11-12', 'day', 'First reading, House of Commons. Sponsoring department listed as DSIT.', 'https://bills.parliament.uk/bills/4035', true, NULL, 'active', '2026-08-01', 8) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('72968441-6c6a-46c2-a4a4-6426241c34b2', 'cyber__timeline__cs-and-r-bill-second-reading-commons', 'cyber', 'timeline', NULL, 'CS&R Bill second reading (Commons)', NULL, '6 Jan 2026', '2026-01-06', 'day', 'Second reading of the Cyber Security and Resilience (Network and Information Systems) Bill.', 'https://commonslibrary.parliament.uk/research-briefings/cbp-10442/', true, NULL, 'active', '2026-08-01', 9) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('6e555f70-6cd9-4406-8746-c90fca038f3f', 'cyber__timeline__government-cyber-action-plan-launched-210m', 'cyber', 'timeline', NULL, 'Government Cyber Action Plan launched (£210m)', NULL, '7 Jan 2026', '2026-01-07', 'day', 'Establishes a Government Cyber Unit — and, within it, the Government Cyber Coordination Centre (GC3), jointly sponsored with NCSC — to coordinate risk management and incident response across departments, delivering against the Government Cyber Security Strategy 2022–2030.', 'https://www.gov.uk/government/publications/government-cyber-action-plan/government-cyber-action-plan', true, NULL, 'active', '2026-08-01', 10) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('f6ef31a2-532b-4f32-aa38-5246489b7971', 'cyber__timeline__cs-and-r-bill-committee-stage-commons', 'cyber', 'timeline', NULL, 'CS&R Bill committee stage (Commons)', NULL, '3–24 Feb 2026', '2026-02-24', 'range', 'Committee stage of the Cyber Security and Resilience (NIS) Bill.', 'https://commonslibrary.parliament.uk/research-briefings/cbp-10442/', true, NULL, 'active', '2026-08-01', 11) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('cb3d90b3-095a-4020-b9e8-0d4cf883ee20', 'cyber__timeline__national-security-bill-announced-folding-in-computer-misuse-act-reform', 'cyber', 'timeline', NULL, 'National Security Bill announced, folding in Computer Misuse Act reform', NULL, '13 May 2026', '2026-05-13', 'day', 'King''s Speech announcement. Chiefly a state-threats/counter-terror bill, but includes the first reform of the 1990 Computer Misuse Act in 35 years: a new “Cyber Crime Risk Order” and, subject to drafting, a statutory defence for good-faith security research (see Regulation).', 'https://www.computerweekly.com/news/366642884/Computer-Misuse-Act-reform-to-move-forward-in-National-Security-Bill', true, NULL, 'active', '2026-08-01', 12) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('34593245-a21d-4d49-9b99-c8d2a1ba1a12', 'cyber__timeline__cs-and-r-bill-report-stage-and-third-reading-commons', 'cyber', 'timeline', NULL, 'CS&R Bill report stage and third reading (Commons)', NULL, '10 Jun 2026', '2026-06-10', 'day', 'Bill passes the Commons and moves to the House of Lords.', 'https://commonslibrary.parliament.uk/research-briefings/cbp-10442/', true, NULL, 'active', '2026-08-01', 13) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('08a7a16f-7cdb-454a-9399-4d9f081360b3', 'cyber__timeline__cs-and-r-bill-introduced-to-house-of-lords-hl-bill-32', 'cyber', 'timeline', NULL, 'CS&R Bill introduced to House of Lords (HL Bill 32)', NULL, '17 Jun 2026', '2026-06-17', 'day', 'At Lords committee stage as of this research (late Jul/Aug 2026).', 'https://bills.parliament.uk/bills/4035', true, NULL, 'active', '2026-08-01', 14) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('fa5adbae-8984-4201-b1ca-e90dbbe710f6', 'cyber__timeline__dsit-abolished-functions-split-across-dbist-dcms-and-cabinet-office', 'cyber', 'timeline', NULL, 'DSIT abolished; functions split across DBIST, DCMS and Cabinet Office', NULL, '21 Jul 2026', '2026-07-21', 'day', 'Wider Whitehall reshuffle under new PM Andy Burnham. Science/innovation/emerging-sector policy moves to DBIST; “digital foundations” (reported to include cyber resilience) moves to an enlarged DCMS; AI strategy and the AI Security Institute move to the Cabinet Office.', 'https://www.ukauthority.com/articles/dsit-scrapped-as-burnham-government-reshapes-whitehall-tech-functions/', true, 'Precise landing point for cyber security policy ownership is unconfirmed — see Evolving.', 'active', '2026-08-01', 15) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('8f7b753d-0242-46fe-ab63-34ec5c2caada', 'cyber__institution__gchq', 'cyber', 'institution', NULL, 'GCHQ', NULL, NULL, NULL, NULL, 'Founded 1 November 1919 as the Government Code & Cypher School (GC&CS), formed by merging Admiralty “Room 40” and War Office “MI1(b)” WWI signals intelligence units. Took the GCHQ cover name in 1939, moved HQ to Cheltenham in 1950. Parent body of the NCSC.', 'https://www.gchq.gov.uk/section/history/our-origins-and-wwi', true, NULL, 'active', '2026-08-01', 0) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('e47b464b-72a7-46b4-a101-6cc403064b58', 'cyber__institution__national-cyber-security-centre-ncsc', 'cyber', 'institution', NULL, 'National Cyber Security Centre (NCSC)', NULL, NULL, NULL, NULL, 'Formed 3 October 2016 as part of GCHQ, absorbing CESG, the Centre for Cyber Assessment and CERT-UK. The UK''s technical authority on cyber security; publishes the annual NCSC Annual Review. CEO: Richard Horne. HQ: Victoria, London.', 'https://en.wikipedia.org/wiki/National_Cyber_Security_Centre_(United_Kingdom)', true, NULL, 'active', '2026-08-01', 1) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('cffeccb6-93b3-4f2f-8fa9-e62dcd01b7df', 'cyber__institution__national-cyber-force-ncf', 'cyber', 'institution', NULL, 'National Cyber Force (NCF)', NULL, NULL, NULL, NULL, 'UK''s offensive cyber capability, formally launched November 2020 (operational from around April 2020). Unified command bringing together GCHQ, the Ministry of Defence, the Secret Intelligence Service (MI6) and the Defence Science and Technology Laboratory (Dstl). Permanent HQ in Samlesbury, Lancashire.', 'https://www.gchq.gov.uk/news/national-cyber-force', true, NULL, 'active', '2026-08-01', 2) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('c71def69-ea15-4196-aa7f-58b33ef148c2', 'cyber__institution__national-protective-security-authority-npsa', 'cyber', 'institution', NULL, 'National Protective Security Authority (NPSA)', NULL, NULL, NULL, NULL, 'Launched 13 March 2023, part of MI5. Evolved from the Centre for the Protection of National Infrastructure (CPNI, est. 2007, itself merging the 1999-founded NISCC and NSAC) with a broadened remit covering state-threat and insider-threat risk to science, technology and research institutions, not just critical national infrastructure. Works alongside NCSC.', 'https://www.npsa.gov.uk/about-npsa', true, NULL, 'active', '2026-08-01', 3) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('b233fdca-c64c-45d0-adcc-90990e218308', 'cyber__institution__uk-cyber-security-council', 'cyber', 'institution', NULL, 'UK Cyber Security Council', NULL, NULL, NULL, NULL, 'Founded as an independent body in March 2021; granted a Royal Charter on 3 March 2022 (approval announced by the Queen in Dec 2021, alongside the National Cyber Strategy launch). Only body able to award “Chartered Cyber Security Professional” status across 16 specialisms; took over stewardship of NCSC''s Certified Cyber Professional (CCP) scheme in 2022 (CCP now closed to new applicants, existing titles valid to Dec 2026).', 'https://www.gov.uk/government/news/new-blueprint-to-protect-uk-from-cyber-threats', true, NULL, 'active', '2026-08-01', 4) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('313f3bca-952a-40f1-bbd7-e8c90afb663a', 'cyber__institution__national-cyber-advisory-board-ncab', 'cyber', 'institution', NULL, 'National Cyber Advisory Board (NCAB)', NULL, NULL, NULL, NULL, 'Cabinet Office board established under the National Cyber Strategy 2022; first met 8 November 2022, co-chaired by the Chancellor of the Duchy of Lancaster and Lloyds Banking Group''s CIO. Brings senior leaders from industry (Google Cloud, Vodafone, ASOS, M&S), academia and the third sector into a quarterly advisory relationship on the whole-economy National Cyber Strategy — distinct from the Government Cyber Advisory Board below, which advises specifically on government''s own estate. Runs working groups on cyber skills/diversity, risk/crisis management and supply chains.', 'https://www.wired-gov.net/wg/news.nsf/articles/New+National+Cyber+Advisory+Board+meets+to+protect+UKs+interests+09112022142000', true, NULL, 'active', '2026-08-01', 5) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('89c3d307-2561-4aaf-8c1e-3202dae5a157', 'cyber__institution__government-cyber-advisory-board-gcab', 'cyber', 'institution', NULL, 'Government Cyber Advisory Board (GCAB)', NULL, NULL, NULL, NULL, 'Distinct from NCAB above: a DSIT-sponsored board specifically advising on government and public-sector cyber resilience, feeding into the Government Cyber Security Strategy/Action Plan. Relaunched with a new cohort in June 2025 — co-chaired by Daniel Cuthbert (Santander) and Bella Powell (Government Cyber Director, GDS), with members from BAE Systems, AWS, Microsoft, Google DeepMind, Accenture and several universities.', 'https://www.gov.uk/government/news/new-plans-to-supercharge-uk-cyber-sector', true, NULL, 'active', '2026-08-01', 6) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('8a372a57-77d5-4e7f-a4f2-b56ca70bab5d', 'cyber__institution__national-laboratory-for-operational-technology-security', 'cyber', 'institution', NULL, 'National Laboratory for Operational Technology Security', NULL, NULL, NULL, NULL, 'Established alongside the National Cyber Strategy 2022 to bring government, industry and academia together on OT/industrial-control-system security.', 'https://www.techuk.org/resource/uk-government-releases-national-cyber-strategy.html', false, 'Announcement confirmed; current operating status not independently verified — see Evolving.', 'active', '2026-08-01', 7) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('55dd5931-38d1-47d8-ab30-e581eecccf88', 'cyber__institution__national-crime-agency-national-cyber-crime-unit-nccu', 'cyber', 'institution', NULL, 'National Crime Agency — National Cyber Crime Unit (NCCU)', NULL, NULL, NULL, NULL, 'Law enforcement lead on cybercrime; chairs the Five Eyes Cyber Crime Working Group (CCWG) and the International Cyber Crime Operations Group (ICCOG). Led the international operation against the LockBit ransomware group.', 'https://committees.parliament.uk/writtenevidence/114408/html/', true, NULL, 'active', '2026-08-01', 8) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('4f554c81-6814-40a0-b49a-767b6439b969', 'cyber__institution__government-cyber-unit-government-cyber-coordination-centre-gc3', 'cyber', 'institution', NULL, 'Government Cyber Unit / Government Cyber Coordination Centre (GC3)', NULL, NULL, NULL, NULL, 'DSIT function (moved from Cabinet Office 3 June 2025) managing government-wide cyber risk on behalf of the DSIT Permanent Secretary; GC3 sits inside the Government Cyber Unit and is jointly sponsored with NCSC. Backed by the £210m Government Cyber Action Plan.', 'https://www.gov.uk/government/publications/government-cyber-action-plan/government-cyber-action-plan', true, NULL, 'active', '2026-08-01', 9) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('d26daf35-755a-48b8-8e93-6651272e8979', 'cyber__institution__research-institute-for-sociotechnical-cyber-security-riscs', 'cyber', 'institution', NULL, 'Research Institute for Sociotechnical Cyber Security (RISCS)', NULL, NULL, NULL, NULL, 'NCSC-funded academic research institute hosted at the University of Bristol — the UK''s first dedicated to the sociotechnical (people/process/technology) dimension of organisational cyber security, not just the technical layer.', 'https://www.ncsc.gov.uk/information/research-institutes', true, NULL, 'active', '2026-08-01', 10) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('5cf0e1e6-eda8-4973-941c-0fb89a9baf59', 'cyber__institution__research-institute-in-verified-trustworthy-software-systems-vetss', 'cyber', 'institution', NULL, 'Research Institute in Verified Trustworthy Software Systems (VeTSS)', NULL, NULL, NULL, NULL, 'NCSC-funded research institute co-hosted by the University of Surrey and Imperial College London, focused on formal verification methods for software reliability and security.', 'https://www.ncsc.gov.uk/information/research-institutes', true, NULL, 'active', '2026-08-01', 11) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('9a856702-2694-49eb-8511-707b51a94bfd', 'cyber__institution__rephrain-national-research-centre-on-privacy-harm-reduction-and-adversarial-infl', 'cyber', 'institution', NULL, 'REPHRAIN (National Research Centre on Privacy, Harm Reduction and Adversarial Influence Online)', NULL, NULL, NULL, NULL, '£8.6m, three-year UKRI Research Centre of Excellence led by Bristol with UCL, Bath, King''s College London and Edinburgh. Adjacent to core cyber security (focus is online privacy, harms and adversarial influence rather than network/systems security) but directly cyber-relevant and NCSC-linked via joint funding calls.', 'https://www.rephrain.ac.uk/about-us/', true, NULL, 'active', '2026-08-01', 12) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('6cccc54f-2856-40dc-a32b-d1748ef4a624', 'cyber__institution__academic-centres-of-excellence-in-cyber-security-education-ace-cse', 'cyber', 'institution', NULL, 'Academic Centres of Excellence in Cyber Security Education (ACE-CSE)', NULL, NULL, NULL, NULL, 'NCSC/DCMS programme (launched 2020) awarding Gold/Silver recognition to UK universities for cyber security teaching quality; distinct from RISCS/VeTSS (research) and the older ACE-CSR scheme. 13 universities recognised as of the 2022 NCSC Annual Review.', 'https://www.ncsc.gov.uk/collection/annual-review-2022/ecosystem/further-and-higher-education', true, 'Current (2026) university count not independently verified.', 'active', '2026-08-01', 13) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('8d3a2566-afaa-4347-a970-31402da05068', 'cyber__institution__darktrace-plc', 'cyber', 'institution', NULL, 'Darktrace plc', NULL, NULL, NULL, NULL, 'Cambridge-headquartered AI-native cyber security company, founded 2013 (see Breakthroughs). IPO''d on the London Stock Exchange April 2021; acquired by Thoma Bravo October 2024 for $5.3bn. One of the sector''s clearest anchor companies, illustrating the UK''s academic-to-commercial pipeline in cyber AI.', 'https://en.wikipedia.org/wiki/Darktrace', true, NULL, 'active', '2026-08-01', 14) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('7264025e-797a-49d9-97ba-cd359a26b6f3', 'cyber__institution__sophos', 'cyber', 'institution', NULL, 'Sophos', NULL, NULL, NULL, NULL, 'Founded 1985 in Abingdon, Oxfordshire by Jan Hruska and Peter Lammer — one of the UK''s oldest cyber security companies, grown from antivirus into full endpoint/network/cloud security. Publicly listed on the LSE from 2020 before being taken private by Thoma Bravo the same year.', 'https://en.wikipedia.org/wiki/Sophos', false, 'No independent primary source for the Wikipedia summary was separately fetched during this research pass.', 'active', '2026-08-01', 15) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('398d71b8-48fe-4557-a977-15f49fd6e2a2', 'cyber__institution__ncc-group', 'cyber', 'institution', NULL, 'NCC Group', NULL, NULL, NULL, NULL, 'Founded 1999, headquartered in Manchester. LSE-listed (FTSE 250, ticker NCC); cyber resilience, penetration testing (CHECK-accredited for UK government/MOD work) and software escrow; 15,000+ clients worldwide; FY2025 revenue £238.9m.', 'https://en.wikipedia.org/wiki/NCC_Group', true, NULL, 'active', '2026-08-01', 16) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('d8fb8ea4-06e0-4c42-ae93-140e2d594189', 'cyber__institution__bae-systems-digital-intelligence-formerly-bae-systems-applied-intelligence', 'cyber', 'institution', NULL, 'BAE Systems Digital Intelligence (formerly BAE Systems Applied Intelligence)', NULL, NULL, NULL, NULL, 'Defence-sector cyber and intelligence arm of BAE Systems, founded 1971 as Smith Associates; headquartered in Guildford, Surrey. NCSC-approved CHECK penetration-testing provider; approximately 4,500 employees (2024).', 'https://www.ncsc.gov.uk/organisation/bae-systems-applied-intelligence-ltd/about-bae-systems-applied-intelligence-ltd', true, NULL, 'active', '2026-08-01', 17) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('5db138f9-d43c-4c16-a51d-b632e471c190', 'cyber__initiative__cyber-runway', 'cyber', 'initiative', 'domestic', 'Cyber Runway', NULL, NULL, NULL, NULL, 'UK''s largest government-backed cyber accelerator; delivered by Plexal, funded by DCMS then DSIT. Launched 2021, consolidating three earlier DCMS accelerators (HutZero, Cyber101, TechNation Cyber). Now in its fifth annual cohort (2026), plus a dedicated Cyber Runway CNI stream launched December 2025 for critical-national-infrastructure-focused SMEs. Members keep 100% of their IP and equity.', 'https://www.plexal.com/our-work/cyber-runway/', true, NULL, 'active', '2026-08-01', 0) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('8f98718b-b458-45e8-a830-6d01ad42a8d2', 'cyber__initiative__lorca-london-office-for-rapid-cybersecurity-advancement', 'cyber', 'initiative', 'domestic', 'LORCA (London Office for Rapid Cybersecurity Advancement)', NULL, '2018–2021', '2018-01-01', 'range', 'Predecessor to Cyber Runway; opened June 2018, £13.5m DCMS-funded, delivered by Plexal with Deloitte and Queen''s University Belfast''s CSIT. Helped members raise over £200m in investment and generate £37m+ in revenue over three years before consolidating into Cyber Runway in 2021.', 'https://www.plexal.com/cyber-runway-takes-off/', true, 'Consolidated into Cyber Runway in 2021; a scaleup-focused “LORCA Ignite” strand continued for some time afterwards.', 'active', '2026-08-01', 1) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('3dd0b75d-7342-496f-8e9e-8758bcec7691', 'cyber__initiative__ncsc-for-startups', 'cyber', 'initiative', 'domestic', 'NCSC For Startups', NULL, NULL, NULL, NULL, 'NCSC programme (delivered with Plexal) connecting cyber startups with technical experts inside UK government to develop innovations addressing government-identified security challenges, such as ransomware and industrial IoT security.', 'https://www.computerweekly.com/news/252525372/More-than-30-startups-to-join-Plexals-Cyber-Runway-accelerator', true, NULL, 'active', '2026-08-01', 2) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('75ab1cde-81af-4ffb-ab10-4840c29cc287', 'cyber__initiative__cyberasap-cyber-security-academic-startup-accelerator-programme', 'cyber', 'initiative', 'domestic', 'CyberASAP (Cyber Security Academic Startup Accelerator Programme)', NULL, NULL, NULL, NULL, 'Only pre-seed accelerator in the UK cyber ecosystem; funded by DSIT, delivered by Innovate UK Business Connect. Now in Year 10 (2026), up to £800,000 per year in funding. As of June 2025: 34 spin-out companies created, raising £43m+ in investment; a further £10m was committed over 4 years (2025–2029) targeting 25 additional spin-outs and £30m more investment by 2030.', 'https://www.gov.uk/government/news/new-plans-to-supercharge-uk-cyber-sector', true, NULL, 'active', '2026-08-01', 3) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('a3c600d0-bf70-4747-a839-351b01854bad', 'cyber__initiative__cyber-essentials', 'cyber', 'initiative', 'domestic', 'Cyber Essentials', NULL, 'Launched 2014', '2014-01-01', 'range', 'Government-backed baseline certification scheme, launched 5 June 2014, overseen by NCSC. Five technical controls (firewalls, secure configuration, patch management, access control, malware protection); Cyber Essentials Plus adds independent technical audit. IASME became sole delivery partner from April 2020. Passed 200,000 certificates awarded in 2024, its 10th year; required for suppliers handling sensitive government data since Oct 2014.', 'https://www.ncsc.gov.uk/files/Cyber-Essentials-brochure.pdf', true, NULL, 'active', '2026-08-01', 4) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('d770d4d1-e6d4-4f82-98ef-921175686075', 'cyber__initiative__cyberfirst-techfirst-transition', 'cyber', 'initiative', 'domestic', 'CyberFirst / TechFirst transition', NULL, NULL, NULL, NULL, 'NCSC''s schools, bursary (£4,000/yr undergraduate) and girls''-competition programme for young people, running since around 2017. Following the PM''s June 2025 London Tech Week announcement of £187m for embedding AI/tech in education, CyberFirst''s bursary and schools elements are being migrated to a new DSIT-run TechFirst programme during 2026 (bursary being rebranded “Tech Grad”).', 'https://www.ncsc.gov.uk/cyberfirst/overview', true, 'Programme mid-transition to TechFirst at time of research.', 'active', '2026-08-01', 5) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('9906b9fc-7595-4c25-b1f6-fa7cbd659c6f', 'cyber__initiative__cyber-explorers', 'cyber', 'initiative', 'domestic', 'Cyber Explorers', NULL, NULL, NULL, NULL, 'Free online cyber-skills learning platform for 11–14 year-olds, launched by DCMS/NCSC in February 2022 as part of the CyberFirst family.', 'https://www.ncsc.gov.uk/collection/annual-review-2022/ecosystem/engaging-young-people', true, NULL, 'active', '2026-08-01', 6) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('7bcfa514-3e21-4559-a8b7-011f30e73eed', 'cyber__initiative__digital-security-hub-dish-greater-manchester', 'cyber', 'initiative', 'domestic', 'Digital Security Hub (DiSH), Greater Manchester', NULL, 'Launched Jun 2022', '2022-06-01', 'range', 'Regional cyber innovation hub led by Barclays Eagle Labs with Manchester City Council, Lancaster University and the University of Manchester as partners, Plexal as innovation/accelerator delivery partner. A 13-year initiative targeting 500 supported startups and 1,000+ jobs; 11,000 sq ft base at Heron House, Manchester. A local-authority/private-sector-led initiative rather than a DSIT national programme.', 'https://www.greatermanchester-ca.gov.uk/what-we-do/digital/digital-strategy/digitally-enabling-a-resilient-and-prosperous-economy/greater-manchester-cyber-ecosystem/greater-manchester-digital-security-hub-dish/', true, NULL, 'active', '2026-08-01', 7) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('cf2bfb4e-7f77-488c-b008-1789a0b39e1a', 'cyber__initiative__government-cyber-action-plan-government-cyber-unit', 'cyber', 'initiative', 'domestic', 'Government Cyber Action Plan / Government Cyber Unit', NULL, 'Jan 2026', '2026-01-01', 'month', '£210m package establishing a Government Cyber Unit to coordinate cross-department risk management and incident response, delivering against the Government Cyber Security Strategy 2022–2030. Developed by DSIT in consultation with departments, industry and the Government Cyber Advisory Board.', 'https://www.gov.uk/government/publications/government-cyber-action-plan/government-cyber-action-plan', true, 'Cross-referenced in Policy Timeline and Institutions.', 'active', '2026-08-01', 8) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('3db8cfb3-6717-4368-933d-4de4b7193ce8', 'cyber__initiative__cyber-growth-action-plan', 'cyber', 'initiative', 'domestic', 'Cyber Growth Action Plan', NULL, '18 Jun 2025', '2025-06-18', 'day', 'Announced by DSIT and the Cabinet Office; led by independent experts at the University of Bristol and Imperial College London''s Centre for Sectoral Economic Performance. A growth-focused review of the UK cyber sector (then £13.2bn revenue, 67,000+ jobs) examining supply/demand and emerging-tech opportunities (AI, quantum), feeding recommendations into the next National Cyber Strategy.', 'https://www.gov.uk/government/news/new-plans-to-supercharge-uk-cyber-sector', true, NULL, 'active', '2026-08-01', 9) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('c9ed58aa-9608-4a6a-8417-760bdf542f7a', 'cyber__initiative__cyber-local', 'cyber', 'initiative', 'domestic', 'Cyber Local', NULL, '2025–2026', '2025-01-01', 'range', 'DSIT-funded regional programme (2025–2026 round: up to £1.8m) targeting growth of the cyber security sector and cyber skills development outside London and the South East.', 'https://www.ukri.org/opportunity/cyber-local-2025-2026/', true, NULL, 'active', '2026-08-01', 10) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('8fed4a05-5324-4959-930f-3666164f54f4', 'cyber__initiative__five-eyes-cyber-cooperation', 'cyber', 'initiative', 'international', 'Five Eyes cyber cooperation', NULL, NULL, NULL, NULL, 'UK, US, Australia, Canada, New Zealand. Includes the Five Eyes Law Enforcement Group Cyber Crime Working Group (chaired by the UK''s NCA), joint threat briefings, and the Secure Innovation guidance — originally a UK-only NCSC/NPSA product, extended across all Five Eyes countries from late 2024 to help tech startups protect themselves from state-threat targeting.', 'https://www.ncsc.gov.uk/news/five-eyes-launch-shared-advice-tech-startups', true, NULL, 'active', '2026-08-01', 11) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('4ca23121-bad4-42bd-bd3b-bee3c35d56ea', 'cyber__initiative__counter-ransomware-initiative-cri', 'cyber', 'initiative', 'international', 'Counter Ransomware Initiative (CRI)', NULL, NULL, NULL, NULL, 'Multilateral (65+ country) initiative the UK helped found and continues to co-lead, focused on disrupting ransomware actors'' business model through sanctions, law enforcement coordination and information-sharing. UK has sanctioned 36+ cyber-criminal actors since 2021, including figures linked to Evil Corp, LockBit and TrickBot.', 'https://s3.amazonaws.com/thegovernmentsays-files/content/188/1881674.html', true, NULL, 'active', '2026-08-01', 12) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('b9ae8664-70ee-4bec-879b-e54f19c0a86f', 'cyber__initiative__uk-ukraine-cyber-programme-ucp', 'cyber', 'initiative', 'international', 'UK Ukraine Cyber Programme (UCP)', NULL, 'Since Feb 2022', '2022-02-01', 'range', 'Stood up within days of the February 2022 invasion; existence declassified November 2022. Initial £6.35m package; expanded by up to £25m (£16m confirmed UK funding plus up to £9m from allies) in June 2023, extending the programme to at least 2025. Provides incident response, forensic and hardening support to Ukrainian government and CNI entities against attacks including Industroyer2 wiper malware.', 'https://gov.uk/government/news/uk-boosts-ukraines-cyber-defences-with-6-million-support-package', true, NULL, 'active', '2026-08-01', 13) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('0211c7dd-bb3d-445d-8e19-c8ed7be1e9ec', 'cyber__initiative__pall-mall-process', 'cyber', 'initiative', 'international', 'Pall Mall Process', NULL, 'Launched Feb 2024', '2024-02-01', 'range', 'UK–France co-led (launched Lancaster House, London, 6–7 Feb 2024) multistakeholder initiative tackling proliferation and irresponsible use of commercial cyber intrusion capabilities (spyware, malware-as-a-service). 21+ governments, plus Google, Microsoft, Apple and Meta, have signed the resulting Code of Practice for States (Paris conference, April 2025). Second phase from 2026 develops complementary guidance for industry.', 'https://www.gov.uk/government/publications/the-pall-mall-process-declaration-tackling-proliferation-and-irresponsible-use-of-commercial-cyber-intrusion-capabilities/the-pall-mall-process-tackling-the-proliferation-and-irresponsible-use-of-commercial-cyber-intrusion-capabilities', true, NULL, 'active', '2026-08-01', 14) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('f75402e7-ae9d-40d2-bc72-0d4bd3707b10', 'cyber__initiative__budapest-convention-un-cybercrime-treaty-engagement', 'cyber', 'initiative', 'international', 'Budapest Convention / UN cybercrime treaty engagement', NULL, NULL, NULL, NULL, 'UK promotes the Council of Europe''s Budapest Convention as the leading cybercrime cooperation template; participates — alongside allies, having initially resisted a competing Russian-tabled UN process — in the newer UN treaty negotiations following the December 2019 UNGA resolution.', 'https://committees.parliament.uk/writtenevidence/114408/html/', true, NULL, 'active', '2026-08-01', 15) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('42cb7a96-2176-4f2e-b58e-e35b09b4f959', 'cyber__regulation__network-and-information-systems-regulations-2018-nis-regulations', 'cyber', 'regulation', 'crit-infra', 'Network and Information Systems Regulations 2018 (NIS Regulations)', NULL, 'In force May 2018', '2018-05-01', 'range', 'UK''s core cross-sector cyber regulation, covering energy, transport, health, drinking water, digital infrastructure and some digital services (online marketplaces, search engines, cloud). Each sector has a “competent authority” regulator. Derived from the (now-superseded) EU NIS Directive.', 'https://commonslibrary.parliament.uk/research-briefings/cbp-10442/', true, NULL, 'active', '2026-08-01', 0) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('8c8811ba-254e-4101-a51d-e53cfe8f9710', 'cyber__regulation__cyber-security-and-resilience-nis-bill', 'cyber', 'regulation', 'crit-infra', 'Cyber Security and Resilience (NIS) Bill', NULL, 'In progress', NULL, NULL, 'At House of Lords committee stage as of this research. Expands NIS scope to include data centres, large load controllers, managed service providers and critical suppliers; strengthens incident-reporting duties; gives regulators cost-recovery, higher-fine and information-sharing powers; gives the Secretary of State powers to direct organisations on national-security grounds. Broadly welcomed by NCSC and techUK; criticised by some for a sector scope that would not have covered the 2025 M&S/Jaguar Land Rover attacks.', 'https://commonslibrary.parliament.uk/research-briefings/cbp-10442/', true, 'Not yet in force — see Evolving.', 'active', '2026-08-01', 1) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('13f8930d-3f19-4110-836a-9edcbfc2fda5', 'cyber__regulation__computer-misuse-act-1990', 'cyber', 'regulation', 'cybercrime', 'Computer Misuse Act 1990', NULL, 'Royal Assent 1990', '1990-01-01', 'range', 'Principal UK legislation criminalising unauthorised access to computer systems/data. Long criticised by the security-research community (via the CyberUp Campaign, active since 2020) for having no statutory defence for good-faith vulnerability research, exposing legitimate researchers to prosecution risk.', 'https://en.wikipedia.org/wiki/Computer_Misuse_Act_1990', true, NULL, 'active', '2026-08-01', 2) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('353d4ed0-cdac-4201-8e1c-53345bb183af', 'cyber__regulation__computer-misuse-act-reform-via-national-security-bill', 'cyber', 'regulation', 'cybercrime', 'Computer Misuse Act reform, via National Security Bill', NULL, 'Announced 13 May 2026', '2026-05-13', 'range', 'Proposes a new “Cyber Crime Risk Order” and, per the CyberUp Campaign''s stated test, is intended to include a statutory public-interest defence for good-faith security research — though this is not yet confirmed. Follows a long consultation history: 2021 call for evidence, Feb–Apr 2023 consultation, a Nov 2023 King''s Speech omission, a Dec 2024 failed Data Bill amendment, a Jan 2025 rejection by the then science minister, and a Dec 2025 government commitment to reform ahead of the May 2026 vehicle being confirmed.', 'https://www.computerweekly.com/news/366642884/Computer-Misuse-Act-reform-to-move-forward-in-National-Security-Bill', true, 'Still primary legislation in progress — see Evolving.', 'active', '2026-08-01', 3) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('ebfa1339-3f86-4472-b8c6-cabb6b372579', 'cyber__regulation__ransomware-payment-ban-and-mandatory-reporting-regime', 'cyber', 'regulation', 'cybercrime', 'Ransomware payment ban & mandatory reporting regime', NULL, 'Confirmed 22 Jul 2025', '2025-07-22', 'range', 'Targeted ban on ransomware payments for public sector and CNI operators; a “payment prevention” notification regime for other businesses intending to pay; new mandatory ransomware incident-reporting requirement. To be implemented via the CS&R Bill framework and/or further secondary legislation.', 'https://www.jumpsec.com/guides/uk-ransomware-payment-ban-implications-what-it-means-for-public-and-private-sector-cybersecurity/', true, 'Legislative vehicle and commencement date not yet finalised — see Evolving.', 'active', '2026-08-01', 4) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('8ae502e4-f19f-46b4-ad1a-7a5640ce06a7', 'cyber__regulation__telecommunications-security-act-2021', 'cyber', 'regulation', 'consumer-telecoms', 'Telecommunications (Security) Act 2021', NULL, 'Royal Assent 17 Nov 2021', '2021-11-17', 'range', 'New statutory security duties on providers of public electronic communications networks/services (three-tiered, Ofcom-enforced, fines up to 10% of turnover or £100k/day); created the “designated vendor direction” power used to mandate removal of Huawei equipment from UK 5G networks by 2027.', 'https://www.linklaters.com/fr-fr/insights/blogs/digilinks/2021/november/uk-telecommunications-security-act-2021-heralds-a-step-change-in-cyber-laws', true, NULL, 'active', '2026-08-01', 5) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('559ad2aa-5b6d-4678-9607-a8042d0c6b2d', 'cyber__regulation__huawei-designated-vendor-direction', 'cyber', 'regulation', 'consumer-telecoms', 'Huawei Designated Vendor Direction', NULL, 'Issued 13 Oct 2022', '2022-10-13', 'range', 'The statutory instrument that formalised the Jul 2020 Huawei removal policy under the TSA 2021''s section 105Z1 power. A designation notice (under s.105Z8) and the Direction itself were issued the same day to 35 UK public telecoms providers. Key requirements: no Huawei 5G equipment procured after 31 December 2020 may be used; phased restrictions on Huawei equipment in fixed-fibre access networks, tied to the US Foreign-Produced Direct Product Rule changes of 19 May and 17 Aug 2020; a hard deadline of 28 January 2023 for removing Huawei from mobile access networks serving “Sites Significant to National Security.” Followed a targeted consultation opened 18 Feb 2022 with affected providers and Huawei itself.', 'https://www.gov.uk/government/news/huawei-legal-notices-issued', true, 'Added to this dataset in August 2026, sourced directly to gov.uk rather than via the secondary legal commentary the adjacent TSA 2021 entry above still cites — worth eventually re-sourcing that entry too for consistency.', 'active', '2026-08-01', 6) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('1d4b63c4-0257-4793-86f9-2c33ff791c21', 'cyber__regulation__product-security-and-telecommunications-infrastructure-act-2022-psti-part-1', 'cyber', 'regulation', 'consumer-telecoms', 'Product Security and Telecommunications Infrastructure Act 2022 (PSTI), Part 1', NULL, 'Royal Assent 6 Dec 2022', '2022-12-06', 'range', 'Statutory IoT/consumer-connectable-product security regime (bans universal default passwords, mandates vulnerability-disclosure policies and minimum support-period transparency), building on the voluntary 2018 Code of Practice for Consumer IoT Security and ETSI EN 303 645. Detailed requirements set out in the PSTI (Security Requirements for Relevant Connectable Products) Regulations 2023.', 'https://www.lexology.com/library/detail.aspx?g=46f3087d-48d4-4110-81be-430142ba8b4e', true, NULL, 'active', '2026-08-01', 7) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('8e291068-8267-4390-ab35-e5fe7a0eca30', 'cyber__regulation__cyber-governance-code-of-practice', 'cyber', 'regulation', 'codes-standards', 'Cyber Governance Code of Practice', NULL, '2024', '2024-01-01', 'year', 'DSIT/NCSC/industry-developed board-level guidance on director and board responsibilities for cyber resilience — part of the National Cyber Strategy 2022''s implementation.', 'https://www.clydeco.com/en/insights/2024/04/uk-cyber-governance-code-of-practice-what-it-could', true, NULL, 'active', '2026-08-01', 8) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('7dc53f68-76d2-4559-a57f-a6d1b01d7d5d', 'cyber__regulation__software-security-code-of-practice', 'cyber', 'regulation', 'codes-standards', 'Software Security Code of Practice', NULL, NULL, NULL, NULL, 'DSIT/NCSC-co-developed voluntary code for organisations that develop or sell software, addressing supply-chain and resilience risk; feedback survey open to Dec 2026.', 'https://www.isc2.org/Insights/2025/07/UK-Software-Security-AI-Codes-of-Practice', true, NULL, 'active', '2026-08-01', 9) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('967a75f8-5c99-4ffd-8e78-dcfbe1ea82fa', 'cyber__regulation__ai-cyber-security-code-of-practice', 'cyber', 'regulation', 'codes-standards', 'AI Cyber Security Code of Practice', NULL, 'Published 31 Jan 2025', '2025-01-31', 'range', 'Published by DSIT with NCSC, following a May–Aug 2024 Call for Views. Voluntary; sets baseline cyber security requirements across the AI lifecycle (secure design, development, deployment, maintenance, end-of-life), addressing AI-specific risks such as data poisoning, model inversion and prompt injection. Intended as the basis for a new global standard via ETSI (TS 104 223).', 'https://www.regulationtomorrow.com/2025/02/government-publishes-new-ai-cyber-security-code-of-practice-and-implementation-guide/', true, NULL, 'active', '2026-08-01', 10) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('3661f4ba-bb9c-4ec1-9b5b-e55b9cc6b6d4', 'cyber__regulation__export-control-order-2008-uk-dual-use-list-cyber-surveillance-items', 'cyber', 'regulation', 'export', 'Export Control Order 2008 / UK dual-use list (cyber-surveillance items)', NULL, NULL, NULL, NULL, 'UK''s consolidated strategic/dual-use export control list, derived from the Wassenaar Arrangement''s List of Dual-Use Goods and Technologies plus national additions. Covers “intrusion software” and IP-network surveillance systems (see Breakthroughs for the 2013 UK/France Wassenaar proposal). Cryptography-using consumer goods are decontrolled under “Note 3” unless specially modified.', 'https://www.europarl.europa.eu/RegData/etudes/BRIE/2023/754439/EXPO_BRI(2023)754439_EN.pdf', true, NULL, 'active', '2026-08-01', 11) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('0f4f6090-448f-4eb0-b0a4-e3e739855b91', 'cyber__regulation__pall-mall-process-code-of-practice-for-states', 'cyber', 'regulation', 'export', 'Pall Mall Process — Code of Practice for States', NULL, 'Apr 2025', '2025-04-01', 'month', 'Sits alongside (not replacing) formal export-control law: functions as a quasi-regulatory instrument governing state purchase and use of commercial cyber intrusion capabilities. Full initiative detail in International Initiatives.', 'https://www.gov.uk/government/publications/the-pall-mall-process-declaration-tackling-proliferation-and-irresponsible-use-of-commercial-cyber-intrusion-capabilities/the-pall-mall-process-tackling-the-proliferation-and-irresponsible-use-of-commercial-cyber-intrusion-capabilities', true, 'Cross-referenced with International Initiatives.', 'active', '2026-08-01', 12) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('299b577f-eeef-469d-b054-d739aeffce8f', 'cyber__breakthrough__bletchley-park-codebreaking-incl-enigma-decryption', 'cyber', 'breakthrough', NULL, 'Bletchley Park codebreaking, incl. Enigma decryption', 'Alan Turing; Gordon Welchman; Dilly Knox and the wider Government Code & Cypher School team', 'WWII', NULL, NULL, 'Cryptanalysis of the German Enigma and Lorenz ciphers; historians credit the work with shortening the war and saving lives. Direct institutional ancestor of GCHQ/NCSC''s cyber mission — protecting the UK''s own communications while breaking others''.', 'https://www.gchq.gov.uk/section/history/our-origins-and-wwi', true, NULL, 'active', '2026-08-01', 0) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('144374ef-3b93-46fc-ba8b-b83fc467ec6f', 'cyber__breakthrough__colossus-world-s-first-programmable-electronic-digital-computer', 'cyber', 'breakthrough', NULL, 'Colossus — world''s first programmable electronic digital computer', 'Tommy Flowers (engineer)', '1943–44', '1943-01-01', 'range', 'Built at Bletchley Park to break the German Lorenz cipher used for high-command traffic; a foundational moment for both computing and signals-intelligence/cyber history, frequently cited as the origin point of the UK''s computer-security tradition.', 'https://www.historytoday.com/archive/feature/beyond-bletchley-gchq-and-british-intelligence', true, NULL, 'active', '2026-08-01', 1) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('f4da4d98-60e1-471e-af20-ed60fc3936eb', 'cyber__breakthrough__darktrace-s-enterprise-immune-system-first-ai-native-cyber-defence-platform', 'cyber', 'breakthrough', NULL, 'Darktrace''s Enterprise Immune System — first AI-native cyber defence platform', 'Founders incl. Poppy Gustafsson, Dave Palmer, Jack Stockdale; seed-funded by Mike Lynch''s Invoke Capital; drew on Cambridge mathematicians and government-intelligence veterans', '2013', '2013-01-01', 'year', 'Founded in Cambridge; pioneered self-learning/unsupervised-AI anomaly detection modelled on the human immune system, rather than signature-based detection. Later launched Antigena, an autonomous-response capability. IPO on the LSE April 2021 (~$2.4bn valuation); acquired by Thoma Bravo October 2024 for $5.3bn.', 'https://www.summitpartners.com/resources/darktrace-pioneering-ai-in-the-cyber-security-space', true, NULL, 'active', '2026-08-01', 2) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('e16fe1e5-1209-40fa-b398-b34644c10ab4', 'cyber__breakthrough__intrusion-software-export-controls-wassenaar-arrangement', 'cyber', 'breakthrough', NULL, 'Intrusion-software export controls (Wassenaar Arrangement)', 'UK and France (proposing states)', '2013', '2013-01-01', 'year', 'The UK and France jointly proposed adding “intrusion software” and “IP network communications surveillance systems” to the Wassenaar Arrangement''s dual-use control list — the first international effort to directly regulate commercial spyware technologies, and the diplomatic ancestor of the 2024 Pall Mall Process.', 'https://www.lawfaremedia.org/article/wassenaar-export-controls-surveillance-tools-new-exemptions-for-vulnerability-research', true, NULL, 'active', '2026-08-01', 3) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('5ba121e9-b669-4cbe-90a8-4a7d5c1f1a2b', 'cyber__evolving__departmental-home-for-cyber-security-policy-post-dsit', 'cyber', 'evolving', NULL, 'Departmental home for cyber security policy post-DSIT', NULL, 'Jul 2026 – ongoing', '2026-07-01', 'range', 'DSIT was abolished 21 July 2026. Cyber resilience is reported to be moving into an enlarged DCMS alongside other “digital foundations” functions, but no gov.uk primary source confirms this for cyber specifically, and the CS&R Bill''s own parliament.uk page still listed DSIT as sponsoring department as of 23 July 2026 — likely a lag rather than a substantive fact, but not asserted either way here.', 'https://sifted.eu/articles/dsit-reshuffle-uk-tech-policy-dbsit-dcms-cabinet', false, 'No official confirmation identified for cyber security specifically.', 'active', '2026-08-01', 0) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('7a0ded9f-dc65-49ac-b651-13b145c558ab', 'cyber__evolving__department-name-changed-twice-within-days', 'cyber', 'evolving', NULL, 'Department name changed twice within days', NULL, 'Jul 2026', '2026-07-01', 'month', 'DSIT''s functions were redistributed into a business department initially referred to as “DBIST”; GOV.UK''s own Machinery of Government fact sheet was itself corrected on 27 Jul 2026, shortening the acronym to “BIST.” This tool uses “DBIST”/the business department descriptively throughout — worth checking current usage before publishing further updates.', 'https://www.gov.uk/government/news/machinery-of-government-changes-fact-sheet', true, 'Terminology genuinely still in flux; affects every sector in this tool, not just cybersecurity.', 'active', '2026-08-01', 1) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('a03cba7e-36c7-4721-9d8b-371b8723d53d', 'cyber__evolving__cyber-security-and-resilience-bill-final-form-and-commencement', 'cyber', 'evolving', NULL, 'Cyber Security and Resilience Bill — final form and commencement', NULL, NULL, NULL, NULL, 'At Lords committee stage as of this research; Royal Assent and commencement dates not yet set. Final scope — especially whether retail/automotive-style attacks like the 2025 M&S and Jaguar Land Rover incidents will end up in scope — remains contested.', 'https://commonslibrary.parliament.uk/research-briefings/cbp-10442/', true, NULL, 'active', '2026-08-01', 2) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('c56af344-1054-4934-aaf9-38a80aa67c95', 'cyber__evolving__ransomware-payment-ban-and-mandatory-reporting-regime-legislative-vehicle', 'cyber', 'evolving', NULL, 'Ransomware payment ban and mandatory reporting regime — legislative vehicle', NULL, 'Since Jul 2025', '2025-07-01', 'range', 'Policy direction confirmed 22 Jul 2025 but not yet in force; unclear whether it lands inside the CS&R Bill, a separate instrument, or secondary legislation.', 'https://www.jumpsec.com/guides/uk-ransomware-payment-ban-implications-what-it-means-for-public-and-private-sector-cybersecurity/', true, NULL, 'active', '2026-08-01', 3) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('43450408-e1b6-474a-b6d6-06af3a1af7e1', 'cyber__evolving__computer-misuse-act-reform-whether-the-statutory-defence-survives-drafting', 'cyber', 'evolving', NULL, 'Computer Misuse Act reform — whether the statutory defence survives drafting', NULL, 'Since 13 May 2026', '2026-05-13', 'range', 'The CyberUp Campaign''s own reaction to the announcement explicitly frames “a clear, workable statutory defence for good-faith cyber security activity” as the open test of the National Security Bill, not a guaranteed outcome.', 'https://www.computerweekly.com/news/366642884/Computer-Misuse-Act-reform-to-move-forward-in-National-Security-Bill', true, NULL, 'active', '2026-08-01', 4) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('7b938172-ec7b-4211-8a5b-abafa0b470f5', 'cyber__evolving__ai-s-dual-effect-on-the-offence-defence-balance', 'cyber', 'evolving', NULL, 'AI''s dual effect on the offence/defence balance', NULL, '2025–2026', '2025-01-01', 'range', 'Recurring theme across NCSC''s 2025 Annual Review (highly significant attacks up 50%, third consecutive year of growth) and industry commentary on the May 2026 CMA reform announcement: AI is simultaneously scaling attacker capability and creating friction for defenders operating under 35-year-old unauthorised-access law.', 'https://www.computerweekly.com/news/366642884/Computer-Misuse-Act-reform-to-move-forward-in-National-Security-Bill', true, NULL, 'active', '2026-08-01', 5) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('29672d7f-36c8-4fc3-ab44-5b31b893cb71', 'cyber__evolving__national-laboratory-for-operational-technology-security-current-activity', 'cyber', 'evolving', NULL, 'National Laboratory for Operational Technology Security — current activity', NULL, 'Since Dec 2021', '2021-12-01', 'range', 'Announced at the Dec 2021 National Cyber Strategy launch; current operating status or output could not be independently verified during this research pass.', 'https://www.techuk.org/resource/uk-government-releases-national-cyber-strategy.html', false, NULL, 'active', '2026-08-01', 6) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('dc82858b-f326-4246-9f49-63a399869569', 'connectivity__timeline__future-telecoms-infrastructure-review-ftir-published', 'connectivity', 'timeline', NULL, 'Future Telecoms Infrastructure Review (FTIR) published', NULL, '23 Jul 2018', '2018-07-23', 'day', 'DCMS review setting the long-term national strategy for full-fibre and 5G rollout; established the policy basis for subsequent gigabit-broadband and 5G funding programmes.', 'https://www.gov.uk/government/calls-for-evidence/future-telecoms-infrastructure-review-call-for-evidence', true, 'Call for evidence and terms of reference confirmed on gov.uk; the July 2018 final report PDF itself was not independently re-loaded during this research pass.', 'active', '2026-08-01', 0) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('5038be30-9ebb-4ad4-b66a-9dd2522bdf21', 'connectivity__timeline__telecoms-supply-chain-review-launched', 'connectivity', 'timeline', NULL, 'Telecoms Supply Chain Review launched', NULL, 'Nov 2018 – Jul 2019', '2018-11-01', 'range', 'Cross-government review (DCMS-led) of security and resilience risks in the telecoms equipment supply chain; tasked NCSC with assessing “high-risk vendors” (Huawei, ZTE), setting up the 2020 Huawei decisions.', 'https://assets.publishing.service.gov.uk/government/uploads/system/uploads/attachment_data/file/963258/20181108_Telecoms_Supply_Chain_Review_Terms_of_Reference_V2.pdf', true, NULL, 'active', '2026-08-01', 1) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('15f797e8-ad6c-4dec-96e6-06ac2a7b31dd', 'connectivity__timeline__ncsc-advises-capped-huawei-role-in-uk-5g-networks', 'connectivity', 'timeline', NULL, 'NCSC advises capped Huawei role in UK 5G networks', NULL, '28 Jan 2020', '2020-01-28', 'day', 'Following the Telecoms Supply Chain Review, NCSC published Telecoms Security Requirements permitting Huawei a capped role (max 35%) in the non-sensitive periphery of UK 5G networks, excluded from network cores and sensitive sites.', 'https://www.ncsc.gov.uk/guidance/ncsc-advice-on-the-use-of-equipment-from-high-risk-vendors-in-uk-telecoms-networks', true, 'Superseded by the July 2020 decision below, following new US sanctions on Huawei.', 'active', '2026-08-01', 2) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('b3ef72a6-75b0-47f0-924f-dfc36314bb67', 'connectivity__timeline__shared-rural-network-srn-agreement-signed', 'connectivity', 'timeline', NULL, 'Shared Rural Network (SRN) agreement signed', NULL, '9 Mar 2020', '2020-03-09', 'day', '£1bn deal between DCMS/Ofcom and the four then-MNOs (EE, Vodafone, O2, Three) to close mobile “not-spots,” targeting 95% combined 4G geographic coverage by end of 2025 via a jointly owned infrastructure company (Digital Mobile Spectrum Ltd).', 'https://www.gov.uk/government/news/shared-rural-network', true, NULL, 'active', '2026-08-01', 3) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('6ec7fcb0-396f-46bc-b311-5f6fa2776b48', 'connectivity__timeline__uk-government-takes-equity-stake-in-oneweb', 'connectivity', 'timeline', NULL, 'UK government takes equity stake in OneWeb', NULL, 'Jul 2020', '2020-07-01', 'month', 'UK government invested an initial ~$500m/£374m to rescue satellite operator OneWeb from bankruptcy, in pursuit of “UK sovereign space capability,” later rising to £517m total. Retained a “golden share” with national-security veto rights.', 'https://publications.parliament.uk/pa/cm5803/cmselect/cmsctech/100/report.html', true, 'Exact investment date varies slightly across sources (Apr/Jun/Jul 2020). See the Eutelsat OneWeb merger under International Initiatives for the current ownership structure.', 'active', '2026-08-01', 4) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('9de73c4b-c202-48f9-8b15-8639aac50225', 'connectivity__timeline__huawei-ban-complete-removal-from-uk-5g-networks-by-2027-announced', 'connectivity', 'timeline', NULL, 'Huawei ban: complete removal from UK 5G networks by 2027 announced', NULL, '14 Jul 2020', '2020-07-14', 'day', 'Digital Secretary Oliver Dowden’s statement to the House of Commons: no new Huawei 5G equipment purchases after 31 December 2020; complete removal from 5G networks by end of 2027; announced the forthcoming Telecoms Security Bill. Reversed the January 2020 capped-role decision, citing US sanctions on Huawei’s semiconductor supply chain.', 'https://www.gov.uk/government/speeches/digital-culture-media-and-sport-secretarys-statement-on-telecoms', true, NULL, 'active', '2026-08-01', 5) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('5263753d-ef4a-483b-94e1-e1dfd16f37b5', 'connectivity__timeline__5g-supply-chain-diversification-strategy-published', 'connectivity', 'timeline', NULL, '5G Supply Chain Diversification Strategy published', NULL, '30 Nov 2020', '2020-11-30', 'day', 'DCMS strategy to diversify the telecoms vendor market after the Huawei decision, backed by an initial £250m. Three strands: support incumbent suppliers (Nokia, Ericsson); attract new entrants; accelerate Open RAN/open-interface solutions. Established the Telecoms Diversification Taskforce, the National Telecoms Lab commitment, and (with Japan’s NEC) the UK’s first major Open RAN trial.', 'https://www.gov.uk/government/publications/5g-supply-chain-diversification-strategy', true, NULL, 'active', '2026-08-01', 6) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('e3cbc4cc-7302-4785-ba12-b8162653d768', 'connectivity__timeline__telecommunications-security-act-2021-royal-assent', 'connectivity', 'timeline', NULL, 'Telecommunications (Security) Act 2021 — Royal Assent', NULL, '17 Nov 2021', '2021-11-17', 'day', 'Amends the Communications Act 2003, creating a new statutory telecoms security framework and new Ofcom enforcement powers, and putting high-risk-vendor decisions on a statutory footing via Designated Vendor Directions.', 'https://www.legislation.gov.uk/ukpga/2021/31/notes/division/2/index.htm', true, 'Full regulatory detail — including the Designated Vendor Direction later used to formalise the Huawei removal requirement — is filed in full under the Cybersecurity sector’s Regulation tab; this entry marks the legislative milestone only.', 'active', '2026-08-01', 7) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('b2d9fb5a-654f-4c78-974b-399eef066cf4', 'connectivity__timeline__project-gigabit-launched', 'connectivity', 'timeline', NULL, 'Project Gigabit launched', NULL, '2020–2021', '2020-01-01', 'range', '£5bn DCMS/BDUK programme (£1.2bn allocated in the 2020 Spending Review for 2020–2025, remainder reserved) to deliver gigabit-capable broadband to the ~20% of UK premises commercial rollout won’t reach.', 'https://commonslibrary.parliament.uk/research-briefings/cbp-9207/', true, NULL, 'active', '2026-08-01', 8) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('46d1ab18-bd99-436a-98ec-64cfeeabbb5e', 'connectivity__timeline__national-space-strategy-published', 'connectivity', 'timeline', NULL, 'National Space Strategy published', NULL, 'Sep 2021', '2021-09-01', 'month', 'UK’s first National Space Strategy (then-BEIS/DfT, under the National Space Council). Included here only for its communications-relevant content (satellite comms, PNT resilience); broader UK space policy such as launch and Earth observation is out of scope for this sector.', 'https://www.gov.uk/government/publications/national-space-strategy/national-space-strategy', true, NULL, 'active', '2026-08-01', 9) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('34dc6666-38d1-4f45-b22d-46ecd9c97fd0', 'connectivity__timeline__product-security-and-telecommunications-infrastructure-act-2022-royal-assent', 'connectivity', 'timeline', NULL, 'Product Security and Telecommunications Infrastructure Act 2022 — Royal Assent', NULL, '6 Dec 2022', '2022-12-06', 'day', 'Part 1 (consumer connectable-product security) is filed in full under the Cybersecurity sector. Part 2 (Electronic Communications Code reform, speeding up deployment of mobile/full-fibre/gigabit infrastructure) is the Advanced-Connectivity-specific content, filed in full under this sector’s Regulation tab.', 'https://www.legislation.gov.uk/ukpga/2022/46/notes/division/2/index.htm', true, NULL, 'active', '2026-08-01', 10) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('6dd7cad2-d2e3-4457-a340-0ce7121cd703', 'connectivity__timeline__uk-wireless-infrastructure-strategy-published', 'connectivity', 'timeline', NULL, 'UK Wireless Infrastructure Strategy published', NULL, '12 Apr 2023', '2023-04-12', 'day', 'DSIT strategy setting an ambition for standalone 5G (5GSA) coverage of all populated UK areas by 2030 (up from the prior “majority of population by 2027,” itself met early). Includes a UK 6G vision chapter, a national mission backed by up to £100m initial funding for “future telecoms,” the £40m 5G Innovation Regions fund, and £8m for satellite broadband to the hardest-to-reach premises.', 'https://assets.publishing.service.gov.uk/media/64357c81877741001368d7fd/uk_wireless_infrastructure_strategy.pdf', true, NULL, 'active', '2026-08-01', 11) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('7bcae9d9-135a-40fc-8cc4-6d05ca4e6b1f', 'connectivity__timeline__uk-telecoms-innovation-network-uktin-announced', 'connectivity', 'timeline', NULL, 'UK Telecoms Innovation Network (UKTIN) announced', NULL, 'Apr 2023', '2023-04-01', 'month', '£10m DCMS/DSIT-funded coordinating body (recommended by the Telecoms Diversification Taskforce), delivered by Digital Catapult, Cambridge Wireless, University of Bristol and WM5G, to act as a single navigation point for telecoms R&D funding, testbeds and collaboration.', 'https://www.techuk.org/resource/dcms-announces-uk-telecoms-innovation-network.html', false, 'Secondary-sourced (techUK); no standalone gov.uk press release located. See Domestic Initiatives for the canonical UKTIN entry.', 'active', '2026-08-01', 12) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('1e1b5279-3275-4424-b3fc-710a927549dc', 'connectivity__timeline__uk-re-associates-to-horizon-europe-incl-sns-ju-eligibility', 'connectivity', 'timeline', NULL, 'UK re-associates to Horizon Europe (incl. SNS JU eligibility)', NULL, '1 Jan 2024', '2024-01-01', 'day', 'UK research entities became eligible, on equal terms to EU/associated-country entities, for all Horizon Europe 2024-Work-Programme-onward calls — including the EU’s Smart Networks and Services Joint Undertaking (SNS JU), Europe’s main 6G research vehicle.', 'https://www.gov.uk/government/publications/horizon-europe-and-copernicus-programmes-2023-uk-eu-agreement-explainer/horizon-europe-and-copernicus-programmes-2023-uk-eu-agreement-explainer', true, NULL, 'active', '2026-08-01', 13) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('080bda6d-fe45-45cc-ad94-80b6d9af0747', 'connectivity__timeline__dsit-abolished-telecoms-connectivity-policy-returns-to-dcms', 'connectivity', 'timeline', NULL, 'DSIT abolished; telecoms/connectivity policy returns to DCMS', NULL, '21 Jul 2026', '2026-07-21', 'day', 'PM Andy Burnham’s Whitehall reshuffle dissolved DSIT. Telecoms, broadband and mobile policy — including BDUK, and hence Project Gigabit and the Shared Rural Network — moved to an expanded DCMS (Department for Digital, Culture, Media and Sport) under Secretary of State Lisa Nandy MP; Ofcom’s sponsoring department also reverted to DCMS. Science/innovation policy went to the renamed DBIST; AI strategy went to the Cabinet Office.', 'https://www.gov.uk/government/news/machinery-of-government-changes-fact-sheet', true, 'Very recent; see Evolving for residual uncertainty (junior ministerial appointment, UK Space Agency/OneWeb-Eutelsat stake sponsorship).', 'active', '2026-08-01', 14) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('cd6ac31b-b493-4e2f-a488-15f38de3ca47', 'connectivity__institution__ofcom', 'connectivity', 'institution', NULL, 'Ofcom', NULL, NULL, NULL, NULL, 'Independent regulator for UK communications (telecoms, spectrum, post, broadcasting). Central to this sector: spectrum licensing/auctions, telecoms security enforcement, Electronic Communications Code disputes, satellite/space spectrum authorisation. Sponsoring department: DCMS.', 'https://www.ofcom.org.uk', true, NULL, 'active', '2026-08-01', 0) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('3b941b1e-b74c-432e-a7bb-cf56692e4c1f', 'connectivity__institution__dcms-department-for-digital-culture-media-and-sport', 'connectivity', 'institution', NULL, 'DCMS (Department for Digital, Culture, Media and Sport)', NULL, NULL, NULL, NULL, 'Current sponsoring department for telecoms, broadband, mobile and spectrum policy (since 21 July 2026; also 2016–Feb 2023). Sponsors Ofcom and BDUK.', 'https://www.gov.uk/government/organisations/department-for-digital-culture-media-and-sport', true, NULL, 'active', '2026-08-01', 1) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('92254090-6d35-474b-811a-1a18fc45c8bb', 'connectivity__institution__dsit-historical-2023-2026', 'connectivity', 'institution', NULL, 'DSIT (historical, 2023–2026)', NULL, NULL, NULL, NULL, 'Sponsored telecoms/connectivity policy from February 2023 until its abolition on 21 July 2026. Preserved as the accurate historical departmental attribution for entries dated in that window, per this tool’s standing convention of not retrospectively relabelling history.', NULL, false, NULL, 'dissolved', '2026-08-01', 2) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('99bbb3b8-9192-4521-9013-1abcb425bacc', 'connectivity__institution__building-digital-uk-bduk', 'connectivity', 'institution', NULL, 'Building Digital UK (BDUK)', NULL, NULL, NULL, NULL, 'Executive agency responsible for delivering Project Gigabit and the Shared Rural Network. Moved DCMS→DSIT→DCMS with its parent department each time. Current sponsor: DCMS.', 'https://www.gov.uk/government/organisations/building-digital-uk', true, NULL, 'active', '2026-08-01', 3) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('ce6c5b29-13c9-4b85-a5d1-d026349a3005', 'connectivity__institution__uk-space-agency', 'connectivity', 'institution', NULL, 'UK Space Agency', NULL, NULL, NULL, NULL, 'Executive agency responsible for UK space policy, including satellite communications programmes via ESA’s ARTES scheme and the National Timing Centre (PNT resilience) — the connectivity-relevant slice of its remit.', 'https://www.gov.uk/government/organisations/uk-space-agency', true, 'Current sponsoring department not confirmed following the July 2026 DSIT abolition — see Evolving.', 'active', '2026-08-01', 4) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('1df4df04-2a47-4144-aa07-31d04ab6d709', 'connectivity__institution__digital-catapult', 'connectivity', 'institution', NULL, 'Digital Catapult', NULL, NULL, NULL, NULL, 'UK innovation agency for advanced digital technologies; delivers SONIC Labs (Open RAN testbed, with Ofcom) and co-delivers UKTIN.', 'https://www.digicatapult.org.uk', true, NULL, 'active', '2026-08-01', 5) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('8dd2fed4-1a96-47ed-aa7b-8d6d64b9557a', 'connectivity__institution__satellite-applications-catapult', 'connectivity', 'institution', NULL, 'Satellite Applications Catapult', NULL, NULL, NULL, NULL, 'UK Catapult centre bridging space-sector research and business application; included here for its satellite-communications-relevant work only — broader Earth-observation/space-domain-awareness activity is out of this sector’s scope.', 'https://sa.catapult.org.uk', true, NULL, 'active', '2026-08-01', 6) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('2c83ac32-9b79-4d01-b1cf-d9cf941ac81e', 'connectivity__institution__smart-internet-lab-university-of-bristol', 'connectivity', 'institution', NULL, 'Smart Internet Lab, University of Bristol', NULL, NULL, NULL, NULL, 'Founded 2015 by Prof. Dimitra Simeonidou; one of the UK’s leading 5G/6G/optical-networks research testbeds. Hosted the world’s first public 5G showcase (March 2018). Delivers the national 5GUK Test Network and leads the JOINER platform (14 federated UK labs/testbeds). Co-delivery partner of UKTIN.', 'https://www.bristol.ac.uk/engineering/research/smart/', true, NULL, 'active', '2026-08-01', 7) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('ef6d0062-9216-44e5-8e09-6fc7105fd0c8', 'connectivity__institution__institute-for-communication-systems-5g-6g-innovation-centre-university-of-surrey', 'connectivity', 'institution', NULL, 'Institute for Communication Systems / 5G-6G Innovation Centre, University of Surrey', NULL, NULL, NULL, NULL, 'Founded 2013 (opened as 5GIC September 2015) by Regius Professor Rahim Tafazolli; renamed 6GIC in November 2020 alongside a distinct 6G research vision. One of Europe’s largest academic telecoms research centres, with a strong non-terrestrial-network research strand.', 'https://www.surrey.ac.uk/institute-communication-systems', true, NULL, 'active', '2026-08-01', 8) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('de3e2eab-5ec2-4219-a0a6-f9e807910b1b', 'connectivity__institution__national-physical-laboratory-npl-national-timing-centre-role', 'connectivity', 'institution', NULL, 'National Physical Laboratory (NPL) — National Timing Centre role', NULL, NULL, NULL, NULL, 'Leads the £36m National Timing Centre, developing terrestrial alternatives to satellite-based Positioning, Navigation and Timing (PNT), reducing single-point-of-failure risk from GNSS/satellite dependency. NPL also appears in the Quantum sector’s Institutions list; cross-sector.', 'https://publications.parliament.uk/pa/cm5803/cmselect/cmsctech/100/report.html', true, 'Sourced to a Parliament committee report rather than an NPL or gov.uk primary announcement.', 'active', '2026-08-01', 9) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('e96cca49-ebf0-4311-870d-6daf7ab31dc7', 'connectivity__institution__sonic-labs-smartran-open-network-interoperability-centre', 'connectivity', 'institution', NULL, 'SONIC Labs (SmartRAN Open Network Interoperability Centre)', NULL, NULL, NULL, NULL, 'Joint Digital Catapult/Ofcom Open RAN interoperability testbed (funded by DCMS/DSIT under the 5G Diversification Strategy), launched February 2022, across four sites indoor and outdoor, including a dedicated outdoor field-testing site under a special Ofcom R&D spectrum licence.', 'https://www.digicatapult.org.uk/programmes/programme/sonic-labs/', true, NULL, 'active', '2026-08-01', 10) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('c6d9b8a6-f6e2-421e-b058-bd1a2d8f49b3', 'connectivity__institution__telecoms-diversification-taskforce', 'connectivity', 'institution', NULL, 'Telecoms Diversification Taskforce', NULL, NULL, NULL, NULL, 'Expert industry/academic advisory taskforce established alongside the 5G Supply Chain Diversification Strategy (Nov 2020) to guide implementation; recommended the creation of UKTIN.', 'https://www.gov.uk/government/publications/5g-supply-chain-diversification-strategy', false, 'Current activity status unconfirmed — unclear whether still operating in named form, folded into UKTIN’s governance, or wound down. See Evolving.', 'active', '2026-08-01', 11) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('14c3f186-45ef-4007-b8f4-2cef97a251fa', 'connectivity__initiative__5g-testbeds-and-trials-programme-5gtt', 'connectivity', 'initiative', 'domestic', '5G Testbeds and Trials Programme (5GTT)', NULL, '2018 onward', '2018-01-01', 'range', 'Series of DCMS/DSIT-funded testbeds and trials (5G ENCODE, 5GUK Test Networks at Bristol/Surrey/King’s College London and others), run under the Future Networks Programme umbrella, exploring industrial and public-sector 5G applications.', 'https://www.bristol.ac.uk/research/groups/smart/5g-demonstrations/', false, 'Corroborated across multiple university project pages citing DCMS as funder; no single consolidated gov.uk programme page covering total spend across all phases was located.', 'active', '2026-08-01', 0) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('d8fb2045-e873-4bb7-8952-1ff869a2c862', 'connectivity__initiative__open-networks-r-and-d-fund-5g-supply-chain-diversification-strategy', 'connectivity', 'initiative', 'domestic', 'Open Networks R&D Fund (5G Supply Chain Diversification Strategy)', NULL, 'From Nov 2020', '2020-11-01', 'range', '£250m fund backing Open RAN R&D, including SONIC Labs (the SmartRAN Open Network Interoperability Centre) and the “Open Networks Ecosystem Competition.”', 'https://assets.publishing.service.gov.uk/media/66154515eb8a1bb45e05e2f2/Open_Networks_Programme_Accounting_Officer_Assessment_Letter.pdf', true, NULL, 'active', '2026-08-01', 1) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('e30f68f1-dfa7-416e-81eb-424be2cd064d', 'connectivity__initiative__shared-rural-network-delivery', 'connectivity', 'initiative', 'domestic', 'Shared Rural Network delivery', NULL, 'Ongoing since Mar 2020', '2020-03-01', 'range', 'Live delivery of the £1bn Shared Rural Network agreement (see Timeline); legally binding coverage obligations run to January 2027.', 'https://www.gov.uk/government/consultations/shared-rural-network-consultation/outcome/summary-of-consultation-responses-and-next-steps', true, NULL, 'active', '2026-08-01', 2) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('ac37ca3c-24d8-4fbd-be39-d1800a753504', 'connectivity__initiative__project-gigabit-delivery', 'connectivity', 'initiative', 'domestic', 'Project Gigabit delivery', NULL, 'Ongoing', NULL, NULL, 'Live regional procurement of the £5bn Project Gigabit programme via BDUK — e.g. a £112.3m contract awarded to CityFibre for Kent & Medway (Feb 2024). As of March 2026, over 1 million premises were included in awarded contracts, of which 227,310 had been connected.', 'https://commonslibrary.parliament.uk/research-briefings/cbp-8392/', true, NULL, 'active', '2026-08-01', 3) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('740fbeea-a6ab-46f6-b78b-577608ea974a', 'connectivity__initiative__future-telecoms-research-hubs-technology-missions-fund', 'connectivity', 'initiative', 'domestic', 'Future Telecoms Research Hubs (Technology Missions Fund)', NULL, 'Ongoing', NULL, NULL, 'UKRI (Innovate UK + EPSRC)-delivered funding stream, distinct from the 5G Testbeds/Open Networks programmes, for 6G and future-telecoms R&D. Funds research hubs including CHEDDAR (all-spectrum connectivity, 7 partner institutions), TITAN, and the JOINER national-scale experimentation platform (led by Bristol); example project: the £6.08m EWOC optical-communications project at UCL, 2023–2028.', 'https://uktin.net/whats-happening/news/uk-government-launches-future-telecoms-technology-missions-fund-programme', false, 'Corroborated via UKTIN’s own pages; no standalone gov.uk/UKRI press release with total fund size was located.', 'active', '2026-08-01', 4) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('3282e86a-009e-4f7c-abdb-7096cf1da1fb', 'connectivity__initiative__uk-telecoms-innovation-network-uktin', 'connectivity', 'initiative', 'domestic', 'UK Telecoms Innovation Network (UKTIN)', NULL, 'Ongoing since 2023', '2023-01-01', 'range', '£10m coordinating programme and standing body for UK telecoms R&D, delivered by Digital Catapult, Cambridge Wireless, University of Bristol and WM5G; took over from the earlier UK5G programme. Current sponsor: DCMS (was DSIT at launch).', 'https://uktin.net', true, NULL, 'active', '2026-08-01', 5) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('0c922b6a-93e4-4d85-a095-7d6957fa1945', 'connectivity__initiative__5g-innovation-regions-fund', 'connectivity', 'initiative', 'domestic', '5G Innovation Regions fund', NULL, 'Announced Apr 2023; ran to Mar 2025', '2023-04-01', 'range', '£40m fund for local authorities to establish themselves as “5G Innovation Regions,” promoting adoption of 5G/advanced wireless technology in sectors such as transport, agriculture, manufacturing and public services. Delivered with UKTIN. Example regions: North East (7-local-authority partnership), Ayrshire (manufacturing focus), Borderlands, and Belfast (secured £5.1m in total across extensions to April 2025).', 'https://assets.publishing.service.gov.uk/media/64c3c3177aea5b00126a8e34/5g_innovation_regions_application_guidance.pdf', true, NULL, 'active', '2026-08-01', 6) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('e495a030-3172-4bdf-b495-1b278203c354', 'connectivity__initiative__uk-space-agency-esa-artes-satellite-communications-investment', 'connectivity', 'initiative', 'domestic', 'UK Space Agency / ESA ARTES satellite communications investment', NULL, 'Latest tranche Nov 2025', '2025-11-01', 'range', 'UK Space Agency investment in satellite communications R&D via ESA’s ARTES programme. Latest round: £6.9m across five projects, including a 5G Non-Terrestrial Network (NTN) payload/terminal project (Vicinity Technologies, £1.19m) and a lunar-communications interface project at Goonhilly Earth Station (£1.6m).', 'https://www.gov.uk/government/news/uk-backs-next-generation-satellite-communications-with-69-million-investment', true, NULL, 'active', '2026-08-01', 7) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('16ad3ee7-c59b-46d5-aa91-2e30c9989e96', 'connectivity__initiative__devolved-administrations-broadband-programmes', 'connectivity', 'initiative', 'domestic', 'Devolved administrations’ broadband programmes', NULL, 'Ongoing', NULL, NULL, 'Scotland (R100 programme), Wales (“Extending high speed broadband” project) and Northern Ireland (Project Stratum, completed July 2025) run their own gigabit-broadband subsidy schemes alongside Project Gigabit.', 'https://commonslibrary.parliament.uk/research-briefings/cbp-8392/', true, 'Summary pointer only — no dedicated per-nation research pass was done for this sector.', 'active', '2026-08-01', 8) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('11fdb44a-fb89-4090-8ad2-4676487bb995', 'connectivity__initiative__uk-japan-open-ran-digital-partnership-collaboration', 'connectivity', 'initiative', 'international', 'UK–Japan Open RAN / Digital Partnership collaboration', NULL, 'From Nov 2020', '2020-11-01', 'range', 'Following the Huawei decision, the UK government partnered with Japan’s NEC for the UK’s first major Open RAN trial; NEC opened a Global Open RAN Centre of Excellence in the UK, November 2020. Broadened into a UK–Japan Digital Partnership covering joint Open RAN Security work and DSIT/MIC (Japan’s Ministry of Internal Affairs and Communications) working groups on vendor diversification.', 'https://www.gov.uk/government/publications/uk-japan-digital-partnership/uk-japan-digital-partnership-progress-report-18-january-2024', true, NULL, 'active', '2026-08-01', 9) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('a95724b8-33ba-4212-a7ac-e33b34d8fde8', 'connectivity__initiative__uk-republic-of-korea-telecoms-technology-partnership', 'connectivity', 'initiative', 'international', 'UK–Republic of Korea telecoms technology partnership', NULL, 'Announced 2023', '2023-01-01', 'range', 'Up to £1.6m UK funding (industry-matched) plus a matching ROK contribution for a joint UK–South Korea competition on 5G/6G telecoms technology collaboration, announced alongside the UKTIN launch.', 'https://gov.uk/government/news/new-government-plans-to-fire-up-innovation-in-5g-and-6g-as-uk-and-south-korea-launch-telecoms-technology-partnership', true, 'Only a partial snippet of the gov.uk press release was retrieved — recommend a full re-fetch before finalising exact figures.', 'active', '2026-08-01', 10) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('0288f138-e192-4501-9943-b230469b88eb', 'connectivity__initiative__global-coalition-on-telecommunications-gcot', 'connectivity', 'initiative', 'international', 'Global Coalition on Telecommunications (GCOT)', NULL, 'Founded Oct 2023', '2023-10-01', 'range', 'UK, US, Japan, Australia and Canada (Sweden joined Mar 2026; the EU became a strategic partner May 2026); focused on telecoms security, 6G development and supply-chain resilience.', 'https://en.wikipedia.org/wiki/Global_Coalition_on_Telecommunications', false, 'Already present in the Semiconductors sector’s International Initiatives (flagged there as “adjacent to, though not squarely within, semiconductor policy proper”) — arguably more core to this sector; kept as a full entry in both for now rather than resolved.', 'active', '2026-08-01', 11) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('f1a53305-f827-4aa5-a6f3-a71e2c8719cf', 'connectivity__initiative__horizon-europe-sns-ju-eligibility-post-association', 'connectivity', 'initiative', 'international', 'Horizon Europe SNS JU eligibility (post-association)', NULL, 'From 1 Jan 2024', '2024-01-01', 'range', 'UK entities fully eligible for the EU’s Smart Networks and Services Joint Undertaking (SNS JU) — overall budget at least €1.8bn (2021–27, EU + industry) — from the 2024 Work Programme onward, including as consortium coordinators.', 'https://smart-networks.europa.eu/faq-sns-ju-2025-calls/', true, NULL, 'active', '2026-08-01', 12) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('8e0a1d51-d6ce-4a34-8cb5-743a116c3996', 'connectivity__initiative__oneweb-eutelsat-oneweb-uk-sovereign-stake', 'connectivity', 'initiative', 'international', 'OneWeb / Eutelsat OneWeb — UK sovereign stake', NULL, 'Merger completed 28 Sep 2023', '2023-09-28', 'range', 'The UK’s OneWeb investment (see Timeline) became an international holding when OneWeb merged with France’s Eutelsat in an all-share deal (OneWeb valued at $3.4bn), creating “Eutelsat Group,” then the first multi-orbit (GEO+LEO) satellite operator. UK retains a “golden share”/Special Share with national-security veto rights, alongside French state stakes (Bpifrance) and Bharti Global as largest private shareholder.', 'https://spacenews.com/eutelsat-completes-multi-orbit-oneweb-merger-after-shareholder-vote/', true, 'Golden-share governance mechanics not independently confirmed against a UK-government primary source. See Evolving for current stake valuation and departmental-sponsorship questions.', 'active', '2026-08-01', 13) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('ba9877ef-dd74-4bcc-bdb1-114f3eb034fb', 'connectivity__initiative__o-ran-alliance-telecom-infra-project-membership', 'connectivity', 'initiative', 'international', 'O-RAN Alliance / Telecom Infra Project membership', NULL, 'Ongoing', NULL, NULL, 'Digital Catapult (via SONIC Labs) is a member of the O-RAN Alliance and the Telecom Infra Project (TIP), and hosts a “European PlugFest Lab” — the UK’s route into international Open RAN interoperability standards work.', 'https://www.digicatapult.org.uk/programmes/programme/sonic-labs/the-programme/', true, NULL, 'active', '2026-08-01', 14) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('7052d9bd-393d-4ad6-8e64-8ea1f2c1d129', 'connectivity__regulation__wireless-telegraphy-act-2006', 'connectivity', 'regulation', 'spectrum', 'Wireless Telegraphy Act 2006', NULL, NULL, NULL, NULL, 'Core statutory framework for radio spectrum licensing (alongside the Communications Act 2003). Requires MNOs, satellite operators and other spectrum users to hold an Ofcom licence; empowers Ofcom to set fees, including “administered incentive pricing” for efficient spectrum use.', 'https://www.legislation.gov.uk/ukpga/2006/36/pdfs/ukpga_20060036_en.pdf', true, NULL, 'active', '2026-08-01', 0) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('4a25b91f-083f-4f11-809b-e80336d134cb', 'connectivity__regulation__ofcom-700mhz-3-6-3-8ghz-spectrum-auction', 'connectivity', 'regulation', 'spectrum', 'Ofcom 700MHz / 3.6–3.8GHz spectrum auction', NULL, 'Mar–Apr 2021', '2021-04-01', 'range', 'Second major UK 5G spectrum auction: 80MHz (700MHz) + 120MHz (3.6–3.8GHz), an 18% increase in mobile-available spectrum. £1.38bn raised across EE, Vodafone, Three and O2 (then-separate entities).', 'https://www.ofcom.org.uk/spectrum/spectrum-awards/final-spectrum-auction-results', true, NULL, 'active', '2026-08-01', 1) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('ae9b4492-953f-494d-9b96-7419c5c819da', 'connectivity__regulation__product-security-and-telecommunications-infrastructure-act-2022-part-2-electroni', 'connectivity', 'regulation', 'infra-access', 'Product Security and Telecommunications Infrastructure Act 2022, Part 2 — Electronic Communications Code reform', NULL, 'Commenced in stages through 2023', '2023-01-01', 'range', 'Reforms operators’ rights to install, maintain and upgrade communications apparatus (masts, cabinets, fibre); changes to the Electronic Communications Code, alternative dispute resolution (in force 7 Nov 2023), and measures targeting deployment in multi-dwelling buildings.', 'https://www.legislation.gov.uk/ukpga/2022/46/notes/division/2/index.htm', true, NULL, 'active', '2026-08-01', 2) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('ed1b627b-817c-4714-91cf-4efb36baf9ac', 'connectivity__regulation__ofcom-space-spectrum-strategy', 'connectivity', 'regulation', 'satellite', 'Ofcom Space Spectrum Strategy', NULL, NULL, NULL, NULL, 'Ofcom’s framework and periodic consultations on spectrum for satellite services (GSO and NGSO systems), including “stations in motion” (aircraft/ship connectivity) and monitoring of direct-to-handset satellite services.', 'https://www.ofcom.org.uk/siteassets/resources/documents/consultations/category-2-6-weeks/233841-space-spectrum-strategy/associated-documents/secondary-documents/consultation-space-spectrum-refresh.pdf', true, NULL, 'active', '2026-08-01', 3) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('bf39a56a-de51-4bf2-8c27-ba3703b29dee', 'connectivity__regulation__direct-to-device-d2d-satellite-connectivity-framework', 'connectivity', 'regulation', 'satellite', 'Direct-to-Device (D2D) satellite connectivity framework', NULL, 'Mar 2025 – Feb 2026', '2025-03-01', 'range', 'Two-part authorisation framework: a discretionary licence exemption for mobile handsets/SIM-enabled devices connecting to D2D satellite services, plus a process for MNOs to request a variation of their existing spectrum licence to offer D2D. Consultation published 25 Mar 2025; UK announced 9 Sep 2025 as the first country in Europe to permit D2D satellite connectivity over existing mobile spectrum; final decision 9 Dec 2025; final regulations statement 17 Feb 2026. VodafoneThree became the first operator approved (900MHz spectrum), with a further consultation on adding its specific frequencies open 15 Apr–18 May 2026. Regulations to be titled the Wireless Telegraphy (Direct to Device Satellite Communications) (Exemption) Regulations 2026. Enables ordinary smartphones to connect directly to satellites for calls/texts/data where terrestrial coverage is absent, complementing the Shared Rural Network in rural/coastal not-spots.', 'https://www.ofcom.org.uk/spectrum/space-and-satellites/consultation-enabling-satellite-direct-to-device-services-in-mobile-spectrum-bands', true, 'A live amendment consultation for VodafoneThree’s specific frequencies was still open as of this research (closing 18 May 2026); there may be a further Ofcom statement since.', 'active', '2026-08-01', 4) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('06aa273b-3d63-4ba1-a51e-2295012057b4', 'connectivity__regulation__telecommunications-security-act-2021-see-cybersecurity-sector', 'connectivity', 'regulation', 'consumer-telecoms', 'Telecommunications (Security) Act 2021 — see Cybersecurity sector', NULL, NULL, NULL, NULL, 'Placeholder only. Statutory telecoms security framework, new Ofcom enforcement powers, and the basis for Designated Vendor Directions (used to formalise the Huawei 5G removal requirement). Full entry, with complete sourcing, is filed under the Cybersecurity sector’s Regulation tab (Consumer, Product & Telecoms Security).', 'https://www.legislation.gov.uk/ukpga/2021/31/notes/division/2/index.htm', true, 'Cross-referenced rather than duplicated — see Cybersecurity sector for full detail.', 'active', '2026-08-01', 5) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('7228ad50-bc15-4f3e-99b4-a3d0b595547f', 'connectivity__regulation__huawei-designated-vendor-direction-see-cybersecurity-sector', 'connectivity', 'regulation', 'consumer-telecoms', 'Huawei Designated Vendor Direction — see Cybersecurity sector', NULL, 'Issued 13 Oct 2022', '2022-10-13', 'range', 'Placeholder only. Legally formalises the Jul 2020 Huawei removal policy under the TSA 2021: designation notice and Designated Vendor Direction issued 13 Oct 2022 to 35 UK public telecoms providers, with a 28 Jan 2023 deadline for removing Huawei from mobile access networks serving “Sites Significant to National Security.” Full entry now added to the Cybersecurity sector’s Regulation tab (Consumer, Product & Telecoms Security), directly beneath its Telecommunications (Security) Act 2021 entry.', 'https://www.gov.uk/government/news/huawei-legal-notices-issued', true, 'Cross-referenced rather than duplicated — see Cybersecurity sector for full detail.', 'active', '2026-08-01', 6) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('c70314ac-6082-4312-9d0f-d8fe46f1141d', 'connectivity__breakthrough__uk-s-first-5g-network-launched-ee', 'connectivity', 'breakthrough', NULL, 'UK’s first 5G network launched (EE)', 'Marc Allera, CEO, BT Consumer', '30 May 2019', '2019-05-30', 'day', 'EE became the first UK operator to launch commercial 5G, live in six cities (London, Birmingham, Cardiff, Manchester, Edinburgh, Belfast) on launch day, offering 100–150Mbps. Non-standalone (NSA) 5G running alongside 4G.', 'https://newsroom.ee.co.uk/ee-launching-uks-first-5g-service-in-six-cities-bringing-a-new-era-in-faster-more-reliable-connectivity/', true, NULL, 'active', '2026-08-01', 0) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('eb7b9d62-3391-4964-94d2-ae05ac8ca671', 'connectivity__breakthrough__world-s-first-public-5g-showcase', 'connectivity', 'breakthrough', NULL, 'World’s first public 5G showcase', 'Prof. Dimitra Simeonidou, Director, Smart Internet Lab', '17–18 Mar 2018', '2018-03-18', 'range', 'University of Bristol’s Smart Internet Lab, with Watershed, hosted what is described as the world’s first public 5G showcase, in Millennium Square, Bristol — ahead of any commercial 5G launch anywhere.', 'https://www.bristol.ac.uk/research/groups/smart/5g-demonstrations/', true, NULL, 'active', '2026-08-01', 1) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('599fff80-e742-4b1c-a979-e6333fd9e310', 'connectivity__breakthrough__university-of-surrey-5gic-1-terabit-per-second-demonstration', 'connectivity', 'breakthrough', NULL, 'University of Surrey 5GIC 1 terabit-per-second demonstration', 'Regius Prof. Rahim Tafazolli, founder/director, 5G Innovation Centre', 'By 15 Sep 2015', '2015-09-15', 'range', 'University of Surrey’s 5G Innovation Centre (£70m investment, £12m from HEFCE) demonstrated a technology enabling speeds of 1 terabit per second — reported as 1,000x the fastest available 4G speed at the time — alongside 15+ filed patents, unveiled at the Centre’s official opening. Partners at the time included EE, Huawei, O2, Vodafone and the BBC.', 'https://www.surrey.ac.uk/news/5g-innovation-centre-officially-opens', true, NULL, 'active', '2026-08-01', 2) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('2e67f8fa-2d12-448b-95cd-5099d769096f', 'connectivity__breakthrough__ucl-optical-networks-group-data-rate-record-progression', 'connectivity', 'breakthrough', NULL, 'UCL Optical Networks Group data-rate record progression', 'Prof. Dame Polina Bayvel, founder (1994) and head, UCL Optical Networks Group', '2016–2026', '2016-01-01', 'range', 'Repeated world records for fibre-optic data transmission capacity: 1.125 Tb/s (2016) → 120 Tb/s over 630km with Xtera (Mar 2018) → 300.28 Tb/s (Nov 2025) → 450 Tb/s over a 39km commercially installed fibre link (Apr 2026, with Japan’s NICT) — roughly 4 million times a typical household connection, presented as a post-deadline paper at OFC 2026.', 'https://www.ucl.ac.uk/news/2026/apr/new-fibre-optic-data-transmission-speed-record', true, NULL, 'active', '2026-08-01', 3) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('6903af08-524c-4f1e-b884-3b31a22d66a3', 'connectivity__breakthrough__surrey-5g-core-connected-via-leo-satellite-constellation', 'connectivity', 'breakthrough', NULL, 'Surrey 5G core connected via LEO satellite constellation', NULL, 'Oct 2023', '2023-10-01', 'month', 'University of Surrey’s 6G/5G Innovation Centre connected its 5G core network to a cell site via the OneWeb LEO satellite constellation (600+ satellites) — an early practical demonstration of non-terrestrial-network (NTN) integration with terrestrial 5G.', 'https://www.surrey.ac.uk/news/university-surreys-5g6g-innovation-centre-celebrates-triple-awards-success', true, NULL, 'active', '2026-08-01', 4) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('f81d91a0-8a6e-4c50-b897-43a987e86ae8', 'connectivity__breakthrough__sonic-labs-first-outdoor-open-ran-test-site-under-special-ofcom-r-and-d-licence', 'connectivity', 'breakthrough', NULL, 'SONIC Labs first outdoor Open RAN test site under special Ofcom R&D licence', NULL, 'Nov 2024', '2024-11-01', 'month', 'Digital Catapult, with Ofcom, Cellnex UK and Capgemini, launched what is described as the UK’s first independent 5G Standalone outdoor field-testing site for Open RAN technology, under a special Ofcom R&D spectrum licence.', 'https://www.digicatapult.org.uk/about/press-releases/post/sonic-labs-outdoor-site-launches/', true, NULL, 'active', '2026-08-01', 5) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('f693f31e-9574-448d-a6cc-84f11a1388a8', 'connectivity__breakthrough__uk-becomes-first-country-in-europe-to-authorise-direct-to-device-satellite-conne', 'connectivity', 'breakthrough', NULL, 'UK becomes first country in Europe to authorise direct-to-device satellite connectivity', NULL, '9 Sep 2025', '2025-09-09', 'day', 'Ofcom’s decision positions the UK ahead of the rest of Europe in enabling ordinary smartphones to connect directly to satellites for calls, texts and data where terrestrial coverage is absent. A regulatory rather than technical first — see the Regulation tab for the full framework.', 'https://www.techuk.org/resource/ofcom-issues-framework-for-direct-to-device-d2d-services-in-the-uk.html', true, 'Included as a candidate entry — the only regulatory (rather than technical) “first” in this tab; happy to remove if it should stay Regulation-only.', 'active', '2026-08-01', 6) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('d7caf837-997b-486c-9e92-32afa500760e', 'connectivity__evolving__departmental-sponsor-for-uk-space-agency-and-oneweb-eutelsat-stake-post-dsit', 'connectivity', 'evolving', NULL, 'Departmental sponsor for UK Space Agency and OneWeb/Eutelsat stake, post-DSIT', NULL, 'Jul 2026 – ongoing', '2026-07-01', 'range', 'Confirmed: telecoms/broadband/mobile policy and BDUK moved to DCMS; Ofcom sponsorship reverted to DCMS. Not confirmed: which department now sponsors the UK Space Agency generally, or the UK government’s Eutelsat OneWeb shareholding specifically — DSIT’s own accounts recorded the stake’s value as of March 2026, but DSIT no longer exists.', 'https://www.gov.uk/government/news/machinery-of-government-changes-fact-sheet', true, NULL, 'active', '2026-08-01', 0) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('c502eb69-87ea-4c80-af3d-76e43bf559f4', 'connectivity__evolving__junior-ministerial-appointment-for-digital-infrastructure', 'connectivity', 'evolving', NULL, 'Junior ministerial appointment for digital infrastructure', NULL, 'Jul 2026 – ongoing', '2026-07-01', 'range', 'Secretary of State Lisa Nandy MP is confirmed at DCMS with an expanded digital brief, but which junior minister now holds the specific “digital infrastructure” portfolio (broadband/mobile/telecoms delivery) has not been independently confirmed.', 'https://sbcnews.co.uk/europe/uk/2026/07/21/burnham-dcms-nandy-brief/', true, NULL, 'active', '2026-08-01', 1) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('b62ab106-c307-43f8-b517-7ed36951af4d', 'connectivity__evolving__oneweb-eutelsat-stake-valuation', 'connectivity', 'evolving', NULL, 'OneWeb/Eutelsat stake valuation', NULL, 'As of 20 Jul 2026', '2026-07-20', 'range', 'The UK government’s Eutelsat OneWeb stake was valued at approximately £175m against total capital injections of £517m — a paper loss of over £340m, driven by a ~38% fall in Eutelsat’s public share price over the prior 12 months. Eutelsat’s full-year results (year to 30 Jun 2026) were due 7 Aug 2026.', 'https://satnews.com/2026/07/20/uk-government-faces-340-million-paper-loss-on-legacy-oneweb-low-earth-orbit-satellite-investment/', true, NULL, 'active', '2026-08-01', 2) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('dd62ba72-8530-4773-8a0b-ae984d05e44f', 'connectivity__evolving__vodafone-s-full-buyout-of-vodafonethree', 'connectivity', 'evolving', NULL, 'Vodafone’s full buyout of VodafoneThree', NULL, 'Around 31 Jul 2026', '2026-07-31', 'range', 'Vodafone paid £4.3bn for CK Hutchison Group Telecom’s remaining 49% of VodafoneThree, taking full ownership just over a year after the merger completed — reducing the UK mobile market to three MNOs (VodafoneThree, BT/EE, VMO2). Too recent for downstream regulatory or market-structure commentary to have surfaced yet.', 'https://www.theregister.com/networks/2026/07/31/three-becomes-one-as-vodafone-buys-out-merger-partner/5281722', true, NULL, 'active', '2026-08-01', 3) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('ec38d5ae-ff8c-46ec-9940-02058b50c4fb', 'connectivity__evolving__upcoming-1-4ghz-spectrum-auction', 'connectivity', 'evolving', NULL, 'Upcoming 1.4GHz spectrum auction', NULL, 'Statement 11 Jun 2026; auction expected H1 2027', '2026-06-11', 'range', 'Ofcom published a statement on plans to auction the upper block of the 1.4GHz band (1492–1517MHz) for 4G/5G use; the auction itself has not yet run.', 'https://www.ofcom.org.uk/spectrum/spectrum-awards', true, NULL, 'active', '2026-08-01', 4) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('99ed30dd-0ab8-4f21-8bda-30a8936f6254', 'connectivity__evolving__project-gigabit-pace-against-original-targets', 'connectivity', 'evolving', NULL, 'Project Gigabit pace against original targets', NULL, 'Ongoing', NULL, NULL, 'Multiple sources note the programme is running behind its original “85% by 2025” ambition, with 2026–2027 suggested as more realistic for that milestone and full coverage pushed toward 2030–2032. Figures vary across sources (£1.2bn of £5bn released vs. “over 1 million premises under contract as of March 2026”) and have not been fully reconciled.', 'https://commonslibrary.parliament.uk/research-briefings/cbp-8392/', true, NULL, 'active', '2026-08-01', 5) ON CONFLICT (record_key) DO NOTHING;
INSERT INTO records (record_id, record_key, sector_id, section_key, subtab_key, title, subtitle, date_label, date_sort_key, date_precision, description, url, url_verified, caveat, status, last_verified_date, sort_order) VALUES ('04b3f887-b238-46ce-947f-6331bb36b513', 'connectivity__evolving__telecoms-diversification-taskforce-current-activity-status', 'connectivity', 'evolving', NULL, 'Telecoms Diversification Taskforce — current activity status', NULL, 'Since Nov 2020', '2020-11-01', 'range', 'Established alongside the 5G Supply Chain Diversification Strategy; could not establish from gov.uk whether it is still operating in its original form, has been folded into UKTIN’s governance, or has been wound down.', 'https://www.gov.uk/government/publications/5g-supply-chain-diversification-strategy', false, NULL, 'active', '2026-08-01', 6) ON CONFLICT (record_key) DO NOTHING;
